/* נוצר אוטומטית ע"י build.mjs */
window.TB_COURSE = [{"id":"base-concepts","track":"BASE","order":1,"icon":"📚","title":"מושגים לפני המערכת","goal":"להסביר במילים פשוטות את המושגים שהמערכת והבוחן משתמשים בהם, ולמצוא אותם במסך.","why":"שאלות בעל פה שוות 10 נקודות בפרק, ורובן על המושגים האלה. מי שמבין אותם מבין גם למה המערכת מתנהגת כמו שהיא מתנהגת.","before":[{"term":"Incoming / Outgoing","text":"Incoming = תיירות נכנסת: תיירים מחו״ל שמגיעים לישראל. זה החומר שלנו, והדוקט מסומן Incoming. Outgoing = תיירות יוצאת (לומדים אותה במידענות). יש גם Domestic = תיירות פנים, ולא לומדים אותה כאן."},{"term":"FIT / Group","text":"FIT = לקוח פרטי, נוסע עצמאי. בבגרות: בלי סוכן ובלי אשראי, מחירי ברוטו, והרווח הוא עמלה מהספק. בסוף הדוקט מתאפס. קבוצה = דרך סוכן נסיעות עם אשראי (ירוק), מחירי נטו, ואנחנו מוסיפים Markup. ההבדל בחשבונאות בא מהסוכן עם האשראי, לא מזה שזו קבוצה."},{"term":"Allocation / Free Sale / Commitment","text":"Allocation (הקצאה): הספק שומר לנו מקומות. מזמינים מתוך המערכת ומקבלים אישור מיד, אבל חובה לדווח לספק על כל מכירה. Free Sale: מזמינים אצל הספק עצמו (בין הרים), ובטרוול בוסטר רק רושמים. לא צריך לדווח. Commitment: התחייבות מלאה (בקבוצות). משלמים על המקומות בכל מקרה, ומדווחים פעם אחת בסוף."},{"term":"Single / DBL / TWIN / Adult Share / Child Share","text":"Single = חדר ליחיד. DBL = חדר זוגי עם מיטה זוגית. TWIN = חדר זוגי עם שתי מיטות נפרדות. Adult Share = מבוגר שלישי בחדר. Child Share = ילד שלישי בחדר של ההורים. במחירון כתוב בסוגריים עד איזה גיל נחשבים ילד."},{"term":"BB / HB / FB","text":"בסיס אירוח (Board Basis). BB = לינה וארוחת בוקר. זה הבסיס, בלי תוספת. HB = חצי פנסיון. FB = פנסיון מלא. במחירון של המלון מופיעה התוספת ל-HB ול-FB."},{"term":"Docket / Transaction / Supplier","text":"Docket = תיק נסיעה (Travel File). לכל נסיעה דוקט נפרד, גם ללקוח שחוזר בפעם החמישית. Transaction = עסקה: כל שירות בדוקט (מלון, העברה, סיור) הוא שורה אחת, וכל שורה היא טרנזקציה. Supplier = הספק שנותן את השירות, למשל המלון או בין הרים."}],"steps":[{"title":"נכנסים להזמנות","text":"נכנסים לאתר עם שם משתמש וסיסמה ולוחצים [[RESERVATION]]. בתפריט העליון מוצאים את ארבעת השירותים מתוך המערכת: [[Hotel]], [[Transport]], [[Activity]], [[Guide]].","why":"אלה ההזמנות מתוך המערכת (Allocation). הזמנות מבין הרים נרשמות בדרך אחרת, דרך [[Add Manual Services]].","shot":"מסך הבית של Reservation אחרי כניסה. לסמן את ארבעת השירותים בתפריט העליון ואת כפתור Find."},{"title":"פותחים דוקט לדוגמה","text":"לוחצים [[Find]], בוחרים [[By Number]] ומקלידים את מספר הדוקט שהמורה נתן. בכותרת הדוקט מוצאים את המילה [[Incoming]].","why":"Incoming אומר שזה דוקט של תיירות נכנסת, כמו שצריך. הסבר מלא על הכותרת ביחידה ״מבנה הדוקט ואיתור דוקט״.","shot":"כותרת של דוקט FIT. לסמן את מספר הדוקט ואת הסימון Incoming.","verify":"איפה בדיוק בכותרת מופיע Incoming, והאם מופיע שם גם Individual Travel File."},{"title":"כל שורה היא טרנזקציה","text":"גוללים לחלק [[Services]]. סופרים את השורות: כל שורה = שירות אחד = טרנזקציה. מעבירים את העכבר על האייקון בתחילת כל שורה, ומזהים: מלון, העברה, Activity או Guide.","why":"בבחינה שואלים ״מהי טרנזקציה?״, וצריך לזהות סוג שירות לפי האייקון.","shot":"חלק Services בדוקט עם כמה סוגי שירות. לסמן את עמודת האייקונים ואת ה-tooltip שנפתח במעבר עכבר."},{"title":"קוראים שורת מלון","text":"בשורת המלון מוצאים: תאריך התחלה וסיום, מספר לילות, שם המלון, מספר חדרים, סוג חדר, בסיס אירוח (למשל B/B), סמל סטטוס ומחיר.","why":"כאן רואים במסך את המושגים מהכרטיסים: סוג חדר ובסיס אירוח.","shot":"שורת מלון אחת בחלק Services. לסמן את הלילות, סוג החדר ובסיס האירוח."},{"title":"מחיר ספק ועמלה","text":"לוחצים על העיפרון ([[Edit]]) של שורת שירות. בתוך מסך השירות מוצאים את החלק החשבונאי: [[Supplier Price]] (מה שהמשרד משלם לספק) ו-[[Commission]] (העמלה שהספק נותן למשרד). יוצאים בלי לשנות כלום.","why":"ב-FIT הרווח של המשרד הוא העמלה מהספק. העמלה שייכת לשירות עצמו.","shot":"מסך עריכה של שירות מלון, החלק החשבונאי. לסמן Supplier Price ו-Commission.","verify":"שם הלשונית או החלק החשבונאי בתוך מסך השירות, ואיך יוצאים ממנו בלי לשמור שינוי."},{"title":"דמי טיפול","text":"חוזרים לדוקט ומוצאים את החלק [[Transaction Fee]]. אלה דמי טיפול שהמשרד גובה מהלקוח, מעבר למחיר השירותים. הם שייכים לדוקט, ולא לשירות.","why":"בבגרות לא משתמשים בדמי טיפול, אבל שואלים מה ההבדל בינם לבין עמלה.","shot":"החלק Transaction Fee בדוקט, בין Services ל-Accounting. לסמן את כותרת החלק."}],"oral":[{"q":"מה ההבדל בין Incoming ל-Outgoing?","a":"Incoming = תיירות נכנסת: מביאים תיירים מחו״ל לישראל. Outgoing = תיירות יוצאת: ישראלים שנוסעים לחו״ל. בטרוול בוסטר בבגרות עובדים רק על Incoming."},{"q":"מה ההבדל בין הזמנה מתוך המערכת להזמנה מבין הרים?","a":"מתוך המערכת = Allocation: יש לנו הקצאה, מקבלים אישור מיד, וחובה לדווח לספק. מבין הרים = Free Sale: מזמינים במערכת של הספק, וטרוול בוסטר משמשת רק לרישום."},{"q":"מה ההבדל בין DBL ל-TWIN?","a":"שניהם חדר זוגי. ב-DBL יש מיטה זוגית אחת, וב-TWIN יש שתי מיטות נפרדות."},{"q":"מהו דוקט ומהי טרנזקציה?","a":"דוקט = תיק נסיעה. לכל נסיעה דוקט נפרד. טרנזקציה = עסקה: כל שירות בדוקט (מלון, העברה, סיור) הוא שורה נפרדת."},{"q":"מה ההבדל בין Commission ל-Transaction Fee?","a":"Commission = עמלה שהספק משלם למשרד על מכירת השירות, ולכן היא שייכת לשירות. Transaction Fee = דמי טיפול שהמשרד גובה מהלקוח, והם שייכים לדוקט."},{"q":"למה צריך לדווח לספק על הזמנה מתוך המערכת?","a":"כי היא מתוך הקצאה. הספק נותן הקצאות לכמה סוכנויות, ואם לא מדווחים על כל חדר שנמכר נוצר אוברבוקינג."}],"check":["אני יודע/ת להסביר כל כרטיס מושג במשפט אחד, בעל פה.","מצאתי בכותרת הדוקט את Incoming.","ספרתי את הטרנזקציות בדוקט וזיהיתי כל אחת לפי האייקון.","מצאתי בשורת מלון את סוג החדר ואת בסיס האירוח.","מצאתי Supplier Price ו-Commission בתוך שירות, ואת החלק Transaction Fee בדוקט."],"sources":["TB_master §1, §2, §12","00_docs_summary: מושגים מרכזיים","hishtalmut_01 §2–§4, §6, §8 (קריאת שורת מלון)","hishtalmut_02 §9 (למה מדווחים)","hishtalmut_04 חלק א׳ (קריאת טרנזקציית המלון), חלק ב׳","video_galor_01 חלק א׳, חלק ב׳ §4–§5 (Transaction Fee מול Commission)"],"record":"none"},{"id":"base-docket","track":"BASE","order":2,"icon":"🗂️","title":"מבנה הדוקט ואיתור דוקט","goal":"למצוא דוקט קיים ולהתמצא בו: כותרת, חמשת החלקים, המקשים וסמלי הסטטוס.","why":"בבחינה חוזרים לדוקט שוב ושוב: לשינויים, לאישורים ולמסמכים. הבוחן גם שואל בעל פה איך מוצאים דוקט ומה רואים בו.","before":[{"term":"Header","text":"החלק העליון של הדוקט: מספר חד-ערכי, שם הדוקט (הנוסע הראשון, או שם הקבוצה), Incoming או Group, סטטוס, תאריך פתיחה, סוכן וסניף. יש גם יתרה בדולר ובשקל: אדום = חובה, ירוק = זכות. ובנוסף רווח (Profit)."},{"term":"Passengers / Services / Transaction Fee / Accounting / Communication","text":"חמשת החלקים של הדוקט, מלמעלה למטה: נוסעים, שירותים (טרנזקציות), דמי טיפול, מסמכים חשבונאיים (חשבונית, שוברים, קבלה), ותיעוד התקשרות ומשימות."},{"term":"Edit / Menu","text":"על כל שורה יש עיפרון (Edit) לפרטים ולעריכה, ו״המבורגר״ (Menu, שלושה פסים) לפעולות כמו שינוי, ביטול ושובר. המקשים הכחולים בראש כל חלק הם לפעולה כללית, למשל הוספת שירות."},{"term":"Status","text":"V ירוק = Confirmed: יש מקום בהקצאה. סימן שאלה כחול = Request: נגמרה ההקצאה, וההזמנה ממתינה לספק. עיגול כתום = Request for Cancellation: בוטל בדוקט אבל עוד לא דווח לספק. X אדום = מבוטל (Cancellation Confirmed)."}],"steps":[{"title":"מוצאים דוקט לפי מספר","text":"לוחצים [[Find]], בוחרים [[By Number]], מקלידים את מספר הדוקט ומחפשים.","why":"זו הדרך הכי מהירה. לכן רושמים את מספר הדוקט על השאלון מיד כשהוא נפתח.","shot":"מסך Find עם האפשרות By Number ושדה המספר. לסמן את שניהם."},{"title":"רשימת הדוקטים שלי","text":"אם אין מספר: [[Travel Files]] ואז [[My Travel Files]]. מוצאים את הדוקט לפי השם ולוחצים על המספר שלו. בעמודת הסוג: [[I]] = Incoming (בודדים), [[O]] = Outgoing, [[G]] = Group.","why":"דרך נוספת: לחיצה על הלוגו של טרוול בוסטר למעלה מציגה רשימה של הדוקטים.","shot":"רשימת My Travel Files. לסמן את עמודת הסוג (I / O / G) ואת מספר הדוקט הלחיץ.","verify":"שם ומיקום הכפתור שמציג רשימת דוקטים ליד הלוגו (בתמלול מופיע ״Scan (?)״)."},{"title":"קוראים את הכותרת","text":"בכותרת מוצאים: מספר הדוקט (אחרי #), שם הדוקט (הנוסע הראשון), [[Incoming]], סטטוס, תאריך פתיחה ומי פתח.","why":"שם הדוקט נלקח מהנוסע הראשון שהוזן. בדוקט קבוצתי מופיע שם הקבוצה.","shot":"כותרת הדוקט (אפשר להשתמש בצילום הקיים h1-docket). לסמן מספר, שם ו-Incoming.","img":"h1-docket","hl":[[3.5,3.7,31.4,11.1],[0.5,26,99,40]]},{"title":"יתרה ורווח","text":"בכותרת מוצאים את היתרה בשני מטבעות: דולר (מטבע הדוקט) ושקל. רקע אדום = חובה, ירוק = זכות. מוצאים גם את [[Profit]]. הרווח מופיע רק אחרי שמפיקים שוברים.","trap":"הזמנה שעוד לא אושרה (סימן שאלה) לא נספרת ביתרה. לפני שעונים ״כמה צריך לשלם?״, מאשרים את כל ההזמנות.","shot":"אזור היתרה בכותרת, בדוקט שכבר יש בו שוברים. לסמן את היתרה בדולר, בשקל ואת Profit.","verify":"איפה בדיוק בכותרת מופיע Profit, ואיך נראה הרקע האדום והירוק.","img":"h1-docket","hl":[[83.2,3.7,16,15.6],[38,72,14,26]]},{"title":"נוסעים","text":"בחלק [[Passengers]] רואים את כל הנוסעים. הצימוד ביניהם מראה מי ישן באותו חדר ([[Rooming]]) ומי משלם יחד ([[Financial]]).","why":"במשפחת כהן: ההורים והילד מצומדים לחדר אחד, והסבתא בחדר משלה.","shot":"חלק Passengers בדוקט של משפחה עם שני חדרים. לסמן את הצימוד של החדר.","verify":"איך נראה הצימוד במסך, ומה שמות האפשרויות Rooming ו-Financial בדיוק."},{"title":"עיפרון והמבורגר","text":"בחלק [[Services]] מוצאים בשורת שירות את העיפרון ([[Edit]]) ואת ההמבורגר ([[Menu]]). למעלה בחלק מוצאים את המקשים הכחולים: [[Add Services]] (מתוך המערכת) ו-[[Add Manual Services]] (בין הרים).","why":"בעיפרון: פרטים, אישור הזמנה וביטול אחרי אישור. בהמבורגר: שינוי (Amend), ביטול לפני אישור, ושובר.","shot":"שורת שירות בחלק Services. לסמן את העיפרון, את ההמבורגר ואת המקשים הכחולים בראש החלק.","img":"h2-services","hl":[[92.5,25,6.5,73]]},{"title":"סמלי סטטוס","text":"בעמודה [[S]] מעבירים את העכבר על הסמל של כל שירות ורואים את הסטטוס.","trap":"V ירוק לא אומר שההזמנה כבר דווחה לספק, ומבחוץ אי אפשר לדעת. נכנסים לעיפרון ואז [[Reservation]]: אם נשאר רק ביטול, ההזמנה אושרה.","shot":"חלק Services עם שירות ב-V ירוק ושירות בסימן שאלה כחול (אפשר את הצילום הקיים h2-services). לסמן את עמודת S.","img":"h2-services","hl":[[64.5,25,3.6,73]]},{"title":"חלקי הכספים","text":"גוללים למטה: [[Transaction Fee]], ואחריו [[Accounting]] עם הכפתורים [[Invoice]], [[Receipt]], [[Ticket/Voucher]] ו-[[Profit]], ובסוף [[Communication]].","why":"ב-Accounting הצבעים חשובים: אדום = מחייב את הדוקט, ירוק = מזכה, שחור = בלי השפעה. המסמכים עצמם נלמדים ביחידה נפרדת.","shot":"תחתית הדוקט: Transaction Fee, Accounting עם ארבעת הכפתורים, ו-Communication. לסמן את הכפתורים."},{"title":"עזרה במערכת","text":"בתפריט [[Tools]] בוחרים באפשרות האחרונה, [[Help]]. שם יש הסבר על כל חלק בדוקט, על המקשים ועל האייקונים.","shot":"תפריט Tools פתוח. לסמן את Help."}],"oral":[{"q":"מהו דוקט, וממה הוא בנוי?","a":"דוקט = תיק נסיעה. יש בו כותרת עם מספר, יתרה ורווח, ומתחתיה נוסעים, שירותים (טרנזקציות), דמי טיפול, החלק החשבונאי ותיעוד התקשרות."},{"q":"איך מוצאים דוקט קיים?","a":"הכי מהר: Find ואז By Number. אפשר גם Travel Files ואז My Travel Files, או לחיצה על הלוגו לרשימת הדוקטים."},{"q":"מה פירוש יתרה באדום ובירוק?","a":"אדום = יתרת חובה (הדוקט במינוס), ירוק = יתרת זכות. בדוקט FIT שגמרו לעבוד עליו היתרה צריכה להיות 0."},{"q":"מה ההבדל בין העיפרון להמבורגר?","a":"העיפרון (Edit) פותח את פרטי השירות, ומשם מאשרים הזמנה. ההמבורגר (Menu) הוא תפריט פעולות על השורה: שינוי, ביטול ושובר."},{"q":"מה פירוש סימן שאלה כחול ליד שירות?","a":"Request: נגמרה ההקצאה וההזמנה ממתינה לאישור הספק. צריך לאשר אותה (Report and Confirm). עד שמאשרים, היא לא נספרת ביתרה."},{"q":"איך יודעים שהזמנה כבר אושרה?","a":"מבחוץ אי אפשר לדעת. נכנסים לעיפרון ואז Reservation. אם נשארה רק אפשרות ביטול, ההזמנה אושרה."}],"check":["הגעתי לדוקט דרך Find ואז By Number.","מצאתי את אותו דוקט גם ב-My Travel Files, וראיתי את הסוג I.","אני יודע/ת להראות בכותרת: מספר, שם, Incoming ויתרה.","מצאתי את חמשת חלקי הדוקט לפי הסדר.","אני יודע/ת לקרוא את הסטטוס של כל שירות בעמודה S."],"sources":["TB_master §2, §6 (סטטוסים, הזמנה לא מאושרת לא נספרת ביתרה)","00_docs_summary: מבנה הדוקט, איתור דוקט, אישור ודיווח","hishtalmut_01 §9 (איתור דוקט), §8 (סטטוסים)","hishtalmut_02 §4 (איך מוצאים דוקט ישן), §9, §11, §12","hishtalmut_04 חלק א׳ (שלוש דרכים לפתוח דוקט)","hishtalmut_06 §2 (עמודת סוג I / O / G)","video_galor_01 חלק א׳ (Header, Passengers, Join), חלק ב׳ §1, §10, §13","tb/units.js fit-hotel2 (עמודה S)"],"record":"none"},{"id":"base-exam","track":"BASE","order":3,"icon":"📝","title":"יום הבחינה","goal":"לדעת איך בנוי פרק טרוול בוסטר בבחינה, ולעבוד בו לפי סדר קבוע.","why":"הבוחן בודק את הדרך וההיגיון, לא רק את התוצאה. סדר עבודה קבוע מונע טעויות, ותלמיד שיודע להסביר טעות מאבד רק מעט נקודות.","before":[{"term":"50 נקודות","text":"פרק טרוול בוסטר שווה 50 נקודות. FIT: דוקט 25, שינויים והפקת מסמכים 15, שאלות בעל פה 10. קבוצות: הצעת מחיר ודוקט 25, שינויים והפקת מסמכים 15, שאלות בעל פה 10."},{"term":"דרך והיגיון","text":"הבוחן בודק איך עבדתם, לא רק את הסכום הסופי. טעות שזיהיתם והסברתם לבוחן (״טעיתי, זיהיתי, מה שחסר הוא...״) מורידה כמה נקודות בלבד. לא מתחילים את התרגיל מחדש: חבל על הזמן."},{"term":"מה פתוח בבחינה","text":"גוגל ותרגום פתוחים. מותר לגלול ולחפש באתר בין הרים, לא צריך לשנן. את מה שמזינים לטרוול בוסטר מזינים באנגלית."},{"term":"שני צבעים","text":"בשאלה מסמנים בצבע אחד את מה שמזמינים מתוך המערכת, ובצבע אחר את מה שמזמינים מבין הרים. כך יודעים מראש איפה מזמינים כל שירות."}],"steps":[{"title":"קוראים את כל השאלה","text":"לפני שנוגעים במחשב קוראים את השאלה עד הסוף. מסמנים תאריכים, כמה חדרים ומי ישן בכל חדר, גילאי ילדים וסוגי חדרים.","trap":"סידור החדרים מופיע לפעמים רק בסעיף של המלון (לרוב הסעיף השלישי, אחרי ההעברות), ולא בפתיחה של השאלה.","shot":"שאלון לדוגמה (לא מסך מערכת), עם סימון של התאריכים ושל סידור החדרים בסעיף המלון."},{"title":"מסמנים בשני צבעים","text":"עוברים על כל סעיף ומסמנים: צבע אחד = מתוך המערכת ([[Add Services]]), צבע שני = בין הרים ([[Add Manual Services]]).","shot":"אותו שאלון, עם סעיפים מסומנים בשני צבעים שונים."},{"title":"מתחילים במלון","text":"ההזמנה הראשונה היא תמיד מלון מתוך המערכת: היא פותחת את הדוקט. לפני האישור בודקים שוב את סידור החדרים. אחרי האישור רושמים מיד את מספר הדוקט על השאלון.","why":"איך עושים את זה, צעד אחר צעד: ביחידה ״מלון ראשון פותח דוקט״.","shot":"כותרת דוקט חדש עם המספר (אפשר את הצילום הקיים h1-docket). לסמן את המספר."},{"title":"שירותים מתוך המערכת","text":"מזמינים את שאר השירותים מתוך המערכת: מלון שני, העברות, [[Activity]] ו-[[Guide]].","trap":"ב-Guide שמים לב לחריגות: ק״מ נוספים ושעות נוספות שכתובים בשאלה.","shot":"חלק Services בדוקט עם מלון, העברה, Activity ו-Guide. לסמן את האייקונים השונים."},{"title":"בין הרים","text":"באתר בין הרים בודקים את המחיר (נכנסים עד המחיר ועוצרים, לא מזמינים באמת), ומיד רושמים את השירות בטרוול בוסטר דרך [[Add Manual Services]].","trap":"שמות הטיולים באתר דומים מאוד, למשל ״העיר החדשה והעתיקה״ מול ״העיר העתיקה״. בודקים שבחרתם בדיוק את הטיול שבשאלה.","shot":"כפתור Add Manual Services בדוקט, ליד Add Services. לסמן אותו."},{"title":"מאשרים רק סימני שאלה","text":"עכשיו מאשרים רק הזמנות עם סימן שאלה: עיפרון, [[Reservation]], [[Report and Confirm]].","why":"את השאר מאשרים רק אחרי השינויים והביטולים. כך שינוי או ביטול לא מחייבים קודם לבטל אישור.","shot":"לשונית Reservation בתוך שירות בסטטוס Request. לסמן את Report and Confirm."},{"title":"קוראים לבוחן","text":"בסוף כל חלק משאירים את התוכנה ואת הדוקט פתוחים, וקוראים לבוחן. לא ממשיכים לחלק הבא לפני שהוא בדק.","why":"בהצעת מחיר של קבוצה זה חובה לפני השינויים: אין שם היסטוריה, והבוחן לא יוכל לראות מה היה לפני השינוי.","shot":"הדוקט פתוח עם כל השירותים לפני השינויים (מסך מלא, בלי סימון).","verify":"מה נחשב ״סוף חלק״ בשאלון הבגרות האמיתי: לבדוק בשאלון לדוגמה איפה מופיעה ההוראה לקרוא לבוחן."},{"title":"שינויים וביטולים","text":"מבצעים את השינויים והביטולים שבשאלה. ביטול מתוך המערכת: המבורגר ואז [[Cancel Reservation]]. ביטול של בין הרים: עיפרון, ומשנים סטטוס ל-[[Cancellation Confirmed]].","trap":"לא לוחצים [[Delete Transaction]]. בבחינה הביטול צריך להישאר גלוי בדוקט, עם X אדום.","shot":"שורת שירות מבוטלת עם X אדום בעמודת הסטטוס. לסמן את ה-X."},{"title":"מאשרים את כל השאר","text":"מאשרים כל הזמנה שנשארה מתוך המערכת, גם את הירוקות: עיפרון, [[Reservation]], [[Report and Confirm]]. אם יש בשאלה שם של מי שאישר או מספר הזמנה, מקלידים אותם. אם אין, לוחצים [[OK]].","why":"חובה לאשר את כל ההזמנות מתוך המערכת. אישור של בין הרים לא חובה, ולא נורא אם מאשרים.","shot":"חלון Report and Confirm עם השדות Confirmed with ו-Reference. לסמן את השדות ואת OK."},{"title":"מסמכים","text":"בחלק [[Accounting]]: [[Invoice]], ואחריו [[Ticket/Voucher]], ואחריו [[Receipt]]. בסוף שולחים [[Itinerary]] או [[Travel File Details]] אם השאלה מבקשת.","why":"גם מי שלא סיים את הדוקט מפיק חשבונית, שוברים וקבלה. אלה נקודות קלות, וחבל להפסיד אותן.","shot":"חלק Accounting אחרי חשבונית, שוברים וקבלה. לסמן את שלוש השורות ואת היתרה 0 בכותרת."},{"title":"תקלה? אומרים בקול","text":"אם משהו לא עובד, לא מתחילים מחדש. מחיר 0 בהזמנת מלון: יוצאים ומחפשים מחדש לפני האישור, ומספרים לבוחן. שורה שלא נקלטה בדוקט קבוצתי (הודעה [[Cannot make reservation since no rooms or passengers...]]): לא מנסים לתקן, ממשיכים, ומסבירים לבוחן מה חסר.","why":"בודקים דרך והיגיון. טעות או תקלה שהוסברה עולה מעט נקודות. זמן שהולך על התחלה מחדש עולה הרבה.","shot":"מסך Additions עם מחיר כולל 0 (אם אפשר לשחזר). לסמן את המחיר.","verify":"לצלם את הודעת השגיאה ״no rooms or passengers״ בנוסח המדויק שלה במערכת."}],"oral":[{"q":"למה מתחילים תמיד במלון?","a":"כי בדוקט FIT ההזמנה הראשונה פותחת את הדוקט, ושאר השירותים נכנסים אליו. מלון מתוך המערכת פותח את הדוקט עם שמות הנוסעים."},{"q":"למה מאשרים בהתחלה רק את ההזמנות עם סימן שאלה?","a":"כי אחרי אישור, ביטול או שינוי דורשים קודם לטפל באישור. לכן מאשרים קודם רק את מה שממתין, עושים שינויים וביטולים, ובסוף מאשרים את כל השאר."},{"q":"אילו הזמנות חייבים לאשר?","a":"את כל ההזמנות מתוך המערכת, גם הירוקות, כי צריך לדווח לספק שהמקום נוצל. הזמנות מבין הרים כבר אושרו אצל הספק, ולא חובה לאשר אותן."},{"q":"מה תעשו אם בבין הרים אין טיול בתאריך שבשאלה?","a":"מחפשים טיול חלופי ביום אחר בשבוע, ומסבירים לבוחן."},{"q":"גיליתם טעות בשירות שכבר הוזן. מה עושים?","a":"לא מתחילים את כל התרגיל מחדש. אומרים לבוחן מה הטעות ואיך מתקנים. בדוקט FIT אפשר לבטל את השורה ולהזמין מחדש."}],"check":["מספר הדוקט רשום על השאלון.","כל סעיף בשאלה מסומן כבוצע (מרקר או צ׳קליסט).","אין בדוקט שירות מתוך המערכת שלא אושר.","ביטולים מופיעים עם X אדום ולא נמחקו.","הפקתי חשבונית, שוברים וקבלה, ובדוקט FIT היתרה 0.","שלחתי Itinerary או Travel File Details, אם השאלה ביקשה."],"sources":["TB_master §3 (סדר עבודה של ירון), §12 (בגרות)","00_docs_summary: מבנה הבחינה, ״שלבי עבודה״ (ירון)","hishtalmut_02 §2, §5, §7, §9, §11, §12 (טיפ בחינה)","hishtalmut_04 חלק א׳ (סידור חדרים בסעיף המלון), חלק ה׳ (לקרוא לבוחנת לפני השינויים)","hishtalmut_06 §3 (מרקר וצ׳קליסט)","hishtalmut_09 §2 (טיולים דומים, אין טיול בתאריך), §5 (בבגרות: להסביר ולא להתחיל מחדש)","tb/units.js fit-hotel1 (באג מחיר 0)"],"record":"none"},{"id":"fit-hotel1","track":"FIT","order":1,"icon":"🏨","title":"מלון ראשון פותח דוקט","goal":"להזמין מלון מתוך המערכת למשפחת כהן (שני חדרים) ולפתוח דוקט חדש.","why":"בבחינה מתחילים תמיד במלון: ההזמנה הראשונה היא זו שפותחת את הדוקט, וכל שאר השירותים נכנסים אליו. טעות בסידור החדרים כאן נגררת לכל הדוקט.","before":[{"term":"משפחת כהן","text":"התרחיש שלנו: חדר 1 = אבא, אמא וילד בן 8. חדר 2 = סבתא, לבד. המלון הראשון בטבריה, והשני בירושלים. בסך הכול 4 נוסעים ו-2 חדרים."},{"term":"Price List","text":"מעבירים עכבר על המחיר של המלון ונפתח מחירון: מחיר ללילה לאדם, בעמודה לכל יום בשבוע. שורות: לאדם בחדר זוגי, ליחיד, Adult Share (מבוגר שלישי), Child Share (ילד בחדר ההורים, עם טווח גילים), ותוספת ל-HB ול-FB."},{"term":"No Agent","text":"ב-FIT הלקוח פרטי: אין סוכן ואין אשראי. לכן לא נוגעים בשדות של הסוכן לאורך כל ההזמנה."}],"steps":[{"title":"קוראים את השאלה עד הסוף","text":"לפני שנוגעים במחשב מסמנים: תאריכים ולילות בכל מלון, כמה חדרים ומי ישן בכל חדר, גיל הילד, סוג חדר ובסיס אירוח. אצל כהן: חדר 1 = 2 מבוגרים וילד בן 8, חדר 2 = מבוגרת אחת.","why":"סידור החדרים כתוב לפעמים רק בסעיף של המלון, ולא בפתיחה של השאלה.","shot":"שאלון לדוגמה עם סעיף המלון מסומן: תאריכים, שני החדרים וגיל הילד."},{"title":"נכנסים להזמנת מלון","text":"בתפריט העליון לוחצים [[Hotel]]. את השדה [[Agent]] משאירים ריק.","why":"ב-FIT הלקוח פרטי. אין סוכן, ולכן גם אין אשראי.","trap":"בחירת סוכן כאן משנה את כל החשבונאות של הדוקט.","shot":"מסך חיפוש המלונות (צילום קיים: h1-search). לסמן את Hotel בתפריט העליון ואת שדה Agent הריק.","img":"h1-search","hl":[[2.4,9.9,24,8.2]]},{"title":"שני חדרים ומבוגרים","text":"לוחצים על השורה [[1 Room, 2 Adults]]. ליד [[Rooms]] לוחצים [[+]] עד 2. לכל חדר יש מבוגרים וילדים משלו, ובכל חדר חדש מופיעים אוטומטית 2 מבוגרים. בחדר 2 (סבתא) מורידים ל-1 ב-[[−]].","shot":"חלון החדרים פתוח, עם שני חדרים מוגדרים (חדר 1: שני מבוגרים, חדר 2: מבוגר אחד). לסמן את מספר החדרים ואת המבוגרים בכל חדר.","why":"בחדר עם מבוגר אחד התיבה Twin מתחלפת ב-[[Double Room]]: יחיד שישן בחדר זוגי. בלי סימון מקבלים חדר יחיד רגיל.","trap":"כשמוסיפים חדר הוא נפתח עם 2 מבוגרים. אם לא מורידים, מזמינים נוסע שלא קיים.","img":"h1-rooms2","hl":[[31.4,13.5,25,6.7],[2.5,67.6,57.6,28]]},{"title":"ילד: גיל, ו-Twin אם צריך","text":"בחדר 1 לוחצים [[+]] ליד [[Children]]. מופיעה רשימת גיל: לוחצים עליה, גוללים ובוחרים [[8 Years old]] (הקלדה לא עובדת). אם השאלה מבקשת שתי מיטות נפרדות, מסמנים V ב-[[Twin]].","why":"גיל הילד קובע את המחיר שלו במחירון (Child Share).","trap":"גיל הילד מופיע אוטומטית כ-11. משנים לגיל שכתוב בשאלה.","shot":"חלון החדרים עם הילד בחדר 1 (צילום קיים: h1-rooms). לסמן את גיל הילד ואת תיבת Twin.","img":"h1-rooms2","hl":[[6,46.5,50,6.5],[6,55,50,8]]},{"title":"יעד: טבריה","text":"ב-[[Destination]] מקלידים 2–3 אותיות ובוחרים את העיר מהרשימה. עם \"Ti\" מופיעות שלוש ערים: [[Tiberias]], [[Tira]] ו-[[Tirat Carmel]]. בוחרים את הנכונה.","trap":"אם רק מקלידים ולא לוחצים על שורה ברשימה, החיפוש נעצר עם ההודעה [[Please enter destination name]] והשדה נצבע באדום.","shot":"שדה Destination עם הרשימה הנפתחת (צילום קיים: h1-dest, בירושלים). לצלם מחדש עם טבריה אם קיימת.","img":"h1-dest2","hl":[[1,51,37,14]]},{"title":"תאריכים וחיפוש","text":"לוחצים על [[Check-in]] ובוחרים את תאריך הכניסה. ב-[[Nights]] מקלידים את מספר הלילות, ותאריך היציאה מתעדכן לבד. לוחצים [[Search]].","trap":"בודקים שתאריך ה-[[Check-out]] תואם לשאלה.","shot":"שדות התאריכים וכפתור Search (צילום קיים: h1-search). לסמן Check-in, Nights ו-Search.","img":"h1-search2","hl":[[29.5,29,44,15],[83.5,76,14.2,14]]},{"title":"בוחרים מלון","text":"המלונות מסודרים לפי א״ב. מוצאים את המלון שבשאלה ולוחצים [[Details]].","shot":"רשימת תוצאות המלונות (צילום קיים: h1-results). לסמן את כפתור Details של המלון.","img":"h1-results","hl":[[79.7,70.1,17.1,4.8]]},{"title":"קוראים את המחירון","text":"מעבירים את העכבר מעל המחיר ונפתח מחירון: מחיר ללילה לאדם, בעמודה לכל יום בשבוע. אצל כהן: [[Person in DBL/TWIN]] (כל אחד מההורים), [[Person in Single]] (סבתא), [[Child Share (2-12)]] (הילד, בגילים 2–12). [[Half Board]] ו-[[Full Board]] הן תוספת ללילה לאדם.","why":"דוגמה מהמערכת: לילה אחד = 2 × 265.34 (ההורים) + 187.34 (הילד) + 343.34 (סבתא) = 1,061.36 דולר, ושלושה לילות = 3,184 דולר. זה בדיוק המחיר שמופיע. כך בודקים את המחיר בבעל פה.","shot":"המחירון שנפתח במעבר עכבר (צילום קיים: h1-pricelist). לסמן זוגי, יחיד, Adult Share, Child Share ותוספות HB/FB.","trap":"אם המחיר שונה בימים מסוימים (למשל סוף שבוע), רואים את זה בעמודות של הימים. בודקים את הימים של הלילות שהזמנתם.","img":"h1-pricelist2","hl":[[0.5,10.5,99,8.5],[0.5,19,99,8.5],[0.5,36,99,8.5]]},{"title":"סוג חדר והזמנה","text":"גוללים למטה לרשימת החדרים. בוחרים את סוג החדר שבשאלה (למשל Standard) בעיגול שליד המחיר, בודקים את בסיס האירוח ב-[[Board]], ולוחצים [[BOOK]].","shot":"רשימת סוגי החדרים (צילום קיים: h1-roomtypes). לסמן את העיגול של סוג החדר ואת BOOK.","img":"h1-roomtypes","hl":[[83.4,17.2,14.6,19.4],[78.5,86.1,12.6,9.6]]},{"title":"בסיס אירוח ומחיר","text":"במסך [[Additions]] בוחרים את בסיס האירוח שבשאלה: [[Bed & Breakfast]], [[Half Board]] או [[Full Board]]. בודקים שיש מחיר כולל, ולוחצים [[Proceed]].","trap":"אם המחיר הכולל 0, זה באג ידוע. אין דרך לתקן אותו במסך: יוצאים ומחפשים מחדש, ומספרים לבוחן. בודקים את זה עוד לפני הזנת השמות.","shot":"מסך Additions (צילום קיים: h1-additions). לסמן את בסיס האירוח, את המחיר הכולל ואת Proceed.","verify":"האם במחיר 0 מספיק לחפש מחדש, או שצריך לצאת מהמערכת לגמרי ולהיכנס שוב (המקורות סותרים).","img":"h1-additions","hl":[[1.9,51.4,43.6,22],[77.5,80.5,20.7,6],[85.7,87.7,12.3,6.1]]},{"title":"שמות המבוגרים","text":"לכל נוסע: [[Title]] ([[Mr.]] / [[Mrs.]]), [[Last name]] ו-[[First name]], באנגלית. לוחצים על אייקון ההעתקה ([[Copy]], הראשון מבין שלושת האייקונים): הנוסע נשמר, והנוסע הבא נפתח כבר עם אותו שם משפחה. בנוסע האחרון לוחצים [[Done]].","why":"הנוסע הראשון הוא הנוסע הראשי, ושמו הופך לשם הדוקט.","shot":"מסך פרטי נוסע מבוגר (צילום קיים: h1-pax-adult). לסמן Title, שם משפחה, שם פרטי, אייקון ההעתקה ו-Next Passenger.","trap":"ה-Copy עובד רק אחרי שממלאים את הנוסע. על נוסע ריק השדות נצבעים באדום.","img":"h1-pax-child2","hl":[[82.5,8,6,10],[16.5,30,25,11]]},{"title":"שם הילד ותואר","text":"לילד בוחרים [[Chd.]] ומקלידים שם פרטי. תאריך הלידה כבר ממולא לפי הגיל שבחרתם (8). משנים אותו רק אם בשאלה יש תאריך לידה. אחרי הנוסע האחרון ([[Done]]) מופיעה רשימה של כל הנוסעים לפי חדרים, עם V ליד כל אחד.","why":"האייקון השלישי ([[Find]], זכוכית מגדלת) פותח חיפוש נוסעים שכבר קיימים במערכת. בבחינה מקלידים שמות חדשים, אז לא צריך אותו.","shot":"מסך פרטי הילד (צילום קיים: h1-pax-child). לסמן Chd., הגיל ו-Done, וגם את אייקון הזכוכית המגדלת.","img":"h1-pax-all","hl":[[0.5,61,99,17],[0.5,81,99,17]]},{"title":"סוכן: לא בוחרים","text":"ב-[[Agent Information]] לא ממלאים כלום. לוחצים [[Continue]].","shot":"מסך Agent Information (צילום קיים: h1-agent). לסמן את השדה הריק ואת Continue.","img":"h1-agent","hl":[[3.6,25.3,57.3,5.4],[82.6,92.3,17.2,6]]},{"title":"מסך הסיכום: בודקים הכול","text":"בודקים: שמות, מלון, תאריכים, מספר חדרים, סוג חדר ובסיס אירוח. ברשימת הנוסעים, סוגר מחבר את מי שישנים באותו חדר (דני, מירי ונועה), וחץ בודד = נוסע לבד בחדר (שרה). בשורת המלון: [[1 x DBLB]] (חדר זוגי), [[1 x SGLB]] (חדר יחיד), [[1 x CHD]] (ילד), [[4 x B/B]].","why":"זה הרגע האחרון לתקן. אם משהו לא נכון: [[Cancel]] ומתחילים מחדש. אחרי Confirm נוצר דוקט, והתיקון קשה יותר.","shot":"מסך הסיכום (צילום קיים: h1-confirm-top). לצלם מחדש עם שני חדרים, ולסמן את סמלי החדרים.","img":"h1-confirm-top","hl":[[1.8,45,45,26],[1.8,84.9,96.4,11.2]]},{"title":"אמצעי תשלום ואישור","text":"מחליפים מ-[[You may charge now by credit card]] ל-[[Request other payment method]], ורק אז לוחצים [[Confirm]].","trap":"לא ללחוץ [[Create Travel File Proposal]]. זו רק הצעה, ולא נוצרת הזמנה.","shot":"אזור אמצעי התשלום וכפתור Confirm (צילום קיים: h1-payment). לסמן את Request other payment method ואת Confirm.","img":"h1-payment","hl":[[1.7,45.3,23.2,4.4],[82.5,84.3,7.8,5.4]]},{"title":"רושמים את מספר הדוקט","text":"אחרי האישור נפתח הדוקט. המספר שלו מופיע בכותרת, אחרי #. רושמים אותו מיד על השאלון. בודקים בחלק [[Passengers]] שיש 4 נוסעים בשני חדרים.","why":"בלי המספר קשה למצוא את הדוקט, וגם המורה והבוחן צריכים אותו.","shot":"כותרת הדוקט החדש (צילום קיים: h1-docket). לצלם מחדש עם 4 הנוסעים, ולסמן את המספר ואת החלוקה לחדרים.","img":"h1-docket","hl":[[3.5,3.7,31.4,11.1]]}],"oral":[{"q":"איזה מחיר במחירון מתאים לסבתא, ואיזה לילד?","a":"לסבתא, שישנה לבד: מחיר יחיד. לילד בחדר של ההורים: Child Share, אם הגיל שלו עד הגיל שכתוב בסוגריים."},{"q":"כמה עולה תוספת חצי פנסיון ללילה, ואיפה רואים את זה?","a":"במחירון שנפתח כשמעבירים עכבר על המחיר. מופיעה שם התוספת ל-HB ול-FB. BB הוא הבסיס, בלי תוספת."},{"q":"איך יודעים במחירון אם יש הבדל בין הימים בשבוע?","a":"במחירון יש עמודה לכל יום. אם בימים מסוימים (למשל סוף שבוע) המחיר אחר, רואים את זה שם. מחשבים לפי הימים של הלילות שהוזמנו."},{"q":"איך רואים במסך הסיכום מי ישן עם מי?","a":"סוגר ברשימת הנוסעים מחבר את מי שבאותו חדר; חץ בודד = לבד בחדר. בשורת המלון כתוב גם כמה חדרים מכל סוג: DBLB זוגי, SGLB יחיד, CHD ילד."},{"q":"למה לא בוחרים סוכן בדוקט FIT?","a":"כי הלקוח פרטי ומשלם בעצמו. אין סוכן ואין אשראי, והרווח שלנו הוא העמלה מהספק."},{"q":"איך מחשבים את מחיר הלילה של משפחת כהן מהמחירון?","a":"2 הורים × מחיר לאדם בזוגי + Child Share לילד + מחיר יחיד לסבתא. כפול מספר הלילות = המחיר הכולל."}],"check":["נפתח דוקט, והמספר שלו רשום על השאלון.","בדוקט 4 נוסעים: Mr., Mrs., ילד (Chd.) בן 8, והסבתא (Mrs.), עם שמות באנגלית.","שורת המלון: 2 חדרים, תאריכים ולילות לפי השאלה, סוג החדר ובסיס האירוח הנכונים.","המחיר בשורת המלון לא 0.","אין סוכן בדוקט."],"sources":["tb/units.js fit-hotel1 (נבדק במערכת האמיתית, אוקטובר 2026)","TB_master §4 (מלון פותח דוקט), §3","00_docs_summary: FIT — פתיחת דוקט מהזמנת מלון (Chd, אייקון דף כפול, זכוכית מגדלת)","hishtalmut_01 §7 (פתיחת דוקט, מחירון, מחיר 0, סמלי חדרים)","hishtalmut_04 חלק א׳ (הזמנת מלון, אמצע שבוע מול סוף שבוע, סמלים, תאריך לידה)","video_galor_01 חלק א׳ (הדגמת פתיחת דוקט: זוג וילד + חדר יחיד)","אימות במערכת 14.10.2026 (teacher66)"],"record":"docket"},{"id":"fit-hotel2","track":"FIT","order":2,"icon":"🏨","title":"מלון שני באותו דוקט","goal":"להוסיף מלון שני (ירושלים) לדוקט של משפחת כהן, בתאריכים ובסידור החדרים הנכונים.","why":"כל הטיול הוא דוקט אחד. מלון שני לא פותח דוקט חדש, אלא נוסף כשורה בתוך הדוקט הקיים. בדרך כלל יש בשאלה שני מלונות.","before":[{"term":"Add Services","text":"הכפתור הכחול בחלק Services. דרכו מוסיפים לדוקט פתוח שירות מתוך המערכת: מלון, העברה, Activity או Guide. Add Manual Services הוא להזמנות מבין הרים."},{"term":"Request","text":"סימן שאלה כחול בשורה: נגמרה ההקצאה, וההזמנה ממתינה לאישור. זה לא טעות שלכם. מאשרים אותה בהמשך (Report and Confirm)."}],"steps":[{"title":"נמצאים בתוך הדוקט","text":"בודקים שבכותרת מופיע מספר הדוקט של כהן. אם יצאתם ממנו: [[Find]] ואז [[By Number]].","shot":"כותרת הדוקט עם המספר (צילום קיים: h1-docket). לסמן את המספר.","img":"h1-docket","hl":[[3.5,3.7,31.4,11.1]]},{"title":"הוספת שירות: מלון","text":"בחלק [[Services]] לוחצים [[Add Services]] ובוחרים [[Hotel]].","trap":"לא להיכנס דרך [[Hotel]] בתפריט העליון. כך נפתח דוקט חדש.","shot":"תפריט Add Services פתוח (צילום קיים: h2-addservices). לסמן את Hotel.","img":"h2-addservices","hl":[[40.4,24.8,17.8,10.9]]},{"title":"מלכודת התאריכים","text":"המערכת ממלאת לבד את כל תאריכי הטיול, מהיום הראשון ועד האחרון.","trap":"חובה לשנות! אחרת המלון השני יוזמן לכל הטיול.","shot":"שדות התאריכים עם ברירת המחדל (צילום קיים: h2-default-dates). לסמן את טווח התאריכים.","img":"h2-default-dates","hl":[[29.5,29.6,43.8,14.2]]},{"title":"יעד ותאריכים: ירושלים","text":"ב-[[Destination]] מקלידים 2–3 אותיות ובוחרים את ירושלים מהרשימה. בוחרים את תאריך הכניסה בלוח, ומקלידים את מספר הלילות ב-[[Nights]].","why":"בלוח רואים מסומן את כל טווח הטיול. בוחרים רק את הלילות של המלון הזה: הכניסה לירושלים ביום היציאה מטבריה.","shot":"השדות אחרי התיקון (צילום קיים: h2-fixed-dates). לסמן Destination, Check-in ו-Nights.","img":"h2-fixed-dates","hl":[[2.5,29.6,70.8,14.2]]},{"title":"בודקים את סידור החדרים","text":"בודקים את שורת החדרים מול השאלה: חדר 1 = 2 מבוגרים וילד בן 8, חדר 2 = מבוגר אחד. בדרך כלל הסידור עובר מהמלון הראשון ולא משנים אותו. אם בשאלה הסידור במלון השני שונה, מתקנים כאן.","trap":"סידור החדרים כתוב לפעמים רק בסעיף של המלון. קוראים שוב את הסעיף של המלון השני.","shot":"שורת החדרים במסך החיפוש של המלון השני, עם שני החדרים. לסמן את השורה.","verify":"שהסידור עובר אוטומטית מהמלון הראשון כולל גיל הילד (8) ושני החדרים, ולא רק מספר הנוסעים.","img":"h2-fixed-dates","hl":[[2.5,9,22,10]]},{"title":"חיפוש, מלון וסוג חדר","text":"כמו במלון הראשון: [[Search]], ואז [[Details]], קריאת המחירון, סוג חדר, [[BOOK]], בסיס אירוח ו-[[Proceed]]. אם בשאלה חצי פנסיון, בוחרים [[Half Board]], והמחיר משתנה.","trap":"גם כאן בודקים שהמחיר לא 0.","shot":"רשימת סוגי החדרים (צילום קיים: h1-roomtypes). לסמן את סוג החדר, Board ו-BOOK.","img":"h1-roomtypes","hl":[[83.4,17.2,14.6,19.4],[78.5,86.1,12.6,9.6]]},{"title":"בלי שמות, ישר לסיכום","text":"במלון השני המערכת לא מבקשת שמות, כי הנוסעים כבר בדוקט. בסיכום בודקים: מספר הדוקט בכותרת, תאריכים, סוג חדר, בסיס אירוח, וסמלי החדרים (זוגי עם ״זרוע״ ויחיד).","shot":"מסך הסיכום של המלון השני (צילום קיים: h2-confirm-top). לסמן את מספר הדוקט ואת סמלי החדרים.","img":"h2-confirm-top","hl":[[1.8,14.3,47.6,4.5],[82,23.3,16,4]]},{"title":"תשלום ואישור","text":"שוב מחליפים ל-[[Request other payment method]] ולוחצים [[Confirm]].","shot":"אמצעי התשלום וכפתור Confirm (צילום קיים: h1-payment). לסמן את שניהם.","img":"h1-payment","hl":[[1.7,45.3,23.2,4.4],[82.5,84.3,7.8,5.4]]},{"title":"בודקים בדוקט","text":"בחלק [[Services]] יש עכשיו שתי שורות מלון. בכל אחת בודקים: תאריכים, לילות, מספר חדרים, סוג חדר ובסיס אירוח. בודקים שאין לילה כפול ואין לילה חסר בין המלונות. בעמודה [[S]] בודקים את הסטטוס.","why":"V ירוק = יש מקום בהקצאה. סימן שאלה כחול = Request: נגמרה ההקצאה. את שתיהן מאשרים בהמשך.","shot":"חלק Services עם שתי שורות מלון (צילום קיים: h2-services). לסמן את שתי השורות ואת עמודת S.","img":"h2-services","hl":[[0.5,35.2,99,12.6],[0.5,65.5,99,12.6]]}],"oral":[{"q":"איך מוסיפים מלון שני לדוקט, ולמה לא דרך Hotel בתפריט העליון?","a":"מתוך הדוקט: Add Services ואז Hotel. דרך התפריט העליון נפתח דוקט חדש, וכל הטיול צריך להיות בדוקט אחד."},{"q":"מה אפשר לקרוא מתוך שורת מלון בדוקט?","a":"תאריך התחלה וסיום, מספר לילות, שם המלון, מספר חדרים, סוג חדר, בסיס אירוח, סטטוס ומחיר."},{"q":"המלון השני קיבל סימן שאלה כחול. מה זה אומר?","a":"Request: נגמרה ההקצאה של המלון, וההזמנה ממתינה לאישור. מאשרים אותה דרך העיפרון: Reservation ואז Report and Confirm."},{"q":"למה במלון השני לא מזינים שמות?","a":"כי הנוסעים כבר נמצאים בדוקט מהמלון הראשון."}],"check":["יש שתי שורות מלון בדוקט אחד, בתאריכים הנכונים.","אין לילה כפול ואין לילה חסר בין טבריה לירושלים.","סידור החדרים בירושלים תואם לשאלה (2 מבוגרים וילד, ויחיד).","בסיס האירוח בכל מלון כמו בשאלה.","רשמתי לעצמי אם יש מלון בסימן שאלה, כדי לאשר אותו בהמשך."],"sources":["tb/units.js fit-hotel2 (נבדק במערכת האמיתית, אוקטובר 2026)","TB_master §4 (מלון שני), §6 (סטטוסים)","00_docs_summary: FIT — מלון נוסף, ״שלבי עבודה״","hishtalmut_01 §8 (מלון שני, קריאת שורת מלון, Request)","hishtalmut_02 §9 (גם ירוקים מאשרים)","hishtalmut_04 חלק א׳ (סידור חדרים בסעיף המלון, קריאת טרנזקציה)"],"record":"docket"},{"id":"fit-transfer","track":"FIT","order":3,"icon":"🚐","title":"העברה מתוך המערכת","goal":"להזמין מתוך המערכת העברה משדה התעופה למלון (וחזרה), עם קודי יעד, פרטי טיסה ורכב מתאים.","why":"כמעט בכל שאלת FIT יש העברות, ולרוב הן בסעיפים הראשונים. פרטי הטיסה עוזרים לנהג: אם הנחיתה משתנה, הוא יודע לעדכן את שעת האיסוף.","before":[{"term":"Transfer","text":"העברה: נסיעה משדה התעופה למלון בהגעה, או מהמלון לשדה התעופה בעזיבה. סידורי הקרקע הם רק בישראל. מתוך המערכת מזמינים ב-Transport."},{"term":"BGN / TLV / JRS / HFA","text":"קודים של 3 אותיות: BGN = נמל התעופה בן גוריון (כך במערכת), TLV = תל אביב, JRS = ירושלים, HFA = חיפה. בדרך כלל זה 3 האותיות הראשונות של העיר."},{"term":"Airline / Flight No.","text":"חברת התעופה בקוד של 2 אותיות (למשל LY, BA, AF, OS, AA, AC), ומספר הטיסה. שניהם כתובים בשאלה. גוגל פתוח בבחינה, אם לא בטוחים בקוד."},{"term":"Seater","text":"סוג הרכב לפי מספר המקומות: רכב ל-4, ל-6 או ל-8. אם השאלה כותבת איזה רכב, לוקחים אותו. אם לא, בוחרים לפי ההיגיון: 3 נוסעים → רכב ל-4, כי אין טעם לשלם על 6."}],"steps":[{"title":"הוספת שירות: Transport","text":"בתוך הדוקט, בחלק [[Services]], לוחצים [[Add Services]] ובוחרים [[Transport]].","trap":"לא [[Add Manual Services]]. הוא להעברה מבין הרים.","shot":"תפריט Add Services פתוח בדוקט של כהן. לסמן את Transport."},{"title":"מאיפה","text":"בשדה [[From]] מקלידים B ובוחרים [[Ben Gurion Airport]] מהרשימה.","why":"בדרך כלל ההעברה הראשונה היא משדה התעופה למלון, מיד עם הנחיתה.","shot":"שדה From עם הרשימה הנפתחת ו-Ben Gurion Airport. לסמן את הבחירה."},{"title":"תאריך ושעה","text":"התאריך מופיע לפי הלילה הראשון במלון. בודקים אותו מול השאלה. בשדה השעה מקלידים את שעת הנחיתה או האיסוף שכתובה בשאלה.","trap":"אם לא מקלידים שעה, ההעברה יוצאת בשעה 00:00.","shot":"שדות התאריך והשעה במסך החיפוש של Transport. לסמן את שניהם.","verify":"שם שדה השעה במסך, ובאיזה פורמט מקלידים (למשל 10:00)."},{"title":"לאן וחיפוש","text":"בשדה [[To]] בוחרים מהרשימה את עיר המלון. אצל כהן בהגעה: טבריה. לוחצים [[Search]].","shot":"שדה To עם העיר שנבחרה, וכפתור Search. לסמן את שניהם.","verify":"שטבריה מופיעה ברשימת היעדים של Transport במערכת התרגול."},{"title":"בוחרים רכב","text":"מופיעה רשימת רכבים לפי מספר מקומות. בוחרים לפי מספר הנוסעים. משפחת כהן = 4 נוסעים (2 מבוגרים, ילד וסבתא). מסמנים את הרכב ולוחצים [[Book]].","why":"בוחרים את הרכב הקטן ביותר שכל הנוסעים נכנסים אליו, אלא אם השאלה כותבת אחרת.","shot":"רשימת הרכבים (ל-4, ל-6, ל-8) עם המחירים. לסמן את הרכב שנבחר ואת כפתור ההזמנה.","verify":"האם לכהן (4 נוסעים) מתאים רכב ל-4; ושם הכפתור: Book או Book Now (המקורות סותרים)."},{"title":"קודי מוצא ויעד","text":"בשדות [[Origin]] ו-[[Destination]] מקלידים קוד של 3 אותיות: [[BGN]] לשדה התעופה, ולעיר את הקוד שלה (למשל [[JRS]], [[TLV]], [[HFA]]).","trap":"שדה התעופה הוא תמיד [[BGN]] במערכת.","shot":"מסך פרטי ההעברה. לסמן את Origin ואת Destination.","verify":"מה הקוד של טבריה במערכת (הוא לא מופיע במקורות), והאם ירושלים היא JRS או JLM."},{"title":"חברת תעופה ומספר טיסה","text":"ב-[[Airline]] מקלידים את קוד החברה (2 אותיות), וב-[[Flight No.]] את מספר הטיסה מהשאלה.","why":"אם מועד הנחיתה משתנה, הנהג יודע לעדכן את שעת האיסוף.","shot":"אותו מסך. לסמן את Airline ואת Flight No.","verify":"שהקוד של אל על במערכת הוא LY (ברשימת המקורות מופיעים רק הקודים, בלי שמות החברות)."},{"title":"בודקים ומתקדמים","text":"בודקים שהתאריך, השעה ושם המלון נכונים. הם נלקחים מהמסך הקודם ומהמלון שבדוקט. אם השעה 00:00, מתקנים כאן. לוחצים [[Continue]].","shot":"מסך פרטי ההעברה המלא, עם התאריך, השעה ושם המלון. לסמן את שם המלון ואת Continue."},{"title":"תשלום ואישור","text":"בסיכום בודקים שוב תאריך, שעה, מאיפה ולאן. מחליפים ל-[[Request other payment method]] ולוחצים [[Confirm]].","shot":"מסך הסיכום של ההעברה. לסמן את אמצעי התשלום ואת Confirm."},{"title":"בודקים בדוקט","text":"בחלק [[Services]] יש שורת העברה חדשה. בודקים בה: תאריך, שעה, מאיפה ולאן, פרטי טיסה ושם המלון.","shot":"שורת ההעברה בחלק Services. לסמן את השעה, הכיוון ופרטי הטיסה."},{"title":"העברה חזרה","text":"בעזיבה עושים את אותו תהליך בכיוון ההפוך: [[From]] = עיר המלון האחרון (אצל כהן ירושלים), [[To]] = [[Ben Gurion Airport]]. ב-[[Origin]] [[JRS]], וב-[[Destination]] [[BGN]], עם פרטי טיסת החזרה.","shot":"שורת ההעברה חזרה בדוקט, מירושלים ל-BGN. לסמן את הכיוון."}],"oral":[{"q":"למה מזינים מספר טיסה בהעברה?","a":"כדי שאם מועד הנחיתה משתנה, הנהג יידע ויעדכן את שעת האיסוף."},{"q":"יש 3 נוסעים. איזה רכב מזמינים ולמה?","a":"רכב ל-4, אלא אם השאלה כותבת אחרת. אין טעם לשלם על רכב ל-6."},{"q":"מה הקוד של נמל התעופה בן גוריון במערכת?","a":"BGN."},{"q":"מה ההבדל בין העברה מתוך המערכת להעברה מבין הרים?","a":"מתוך המערכת: Add Services ואז Transport. זו הזמנה מהקצאה, וצריך לאשר אותה (Report and Confirm). מבין הרים: בודקים מחיר באתר ורושמים דרך Add Manual Services, עם סטטוס OK ומחיר אחד לרכב."}],"check":["יש שורת העברה בתאריך ובשעה שבשאלה (לא 00:00).","Origin ו-Destination בקוד של 3 אותיות (BGN לשדה התעופה).","חברת התעופה ומספר הטיסה הוזנו.","סוג הרכב מתאים למספר הנוסעים או למה שכתוב בשאלה.","החלפתי אמצעי תשלום ואישרתי (Confirm)."],"sources":["TB_master §4 (Transport)","00_docs_summary: הזמנות מתוך המערכת — העברה","hishtalmut_01 §10 (Transport: BGN, רכב לפי נוסעים, פרטי טיסה, 00:00, העברה הפוכה)","hishtalmut_02 §4 (העברה מבין הרים, להשוואה)","hishtalmut_04 חלק א׳ (העברות בסעיפים הראשונים)"],"record":"docket"},{"id":"fit-activity","track":"FIT","order":4,"icon":"🎟️","title":"Activity: אתר, מוזיאון או סיור רגולרי","goal":"להזמין מתוך המערכת כניסה לאתר או למוזיאון, כל אטרקציה כהזמנה נפרדת.","why":"ביקור באתרים מופיע ברוב שאלות ה-FIT. בעל פה שואלים כמעט תמיד מה ההבדל בין Activity ל-Guide.","before":[{"term":"Activity","text":"פעילות שמצטרפים אליה ״יחד עם אחרים״: כניסה לאתר או למוזיאון, גן חיות, או סיור רגולרי שיוצא באופן קבוע. דוגמאות מהמערכת בירושלים: יד ושם, גן החיות התנ״כי."},{"term":"Activity / Guide","text":"Activity = לא פרטי, עם אנשים אחרים. Guide = משהו פרטי שלי: נהג או מדריך ברכב צמוד, במסלול שאנחנו קובעים. הכלל נכון גם במערכת וגם בבין הרים."}],"steps":[{"title":"הוספת שירות: Activity","text":"בתוך הדוקט, בחלק [[Services]], לוחצים [[Add Services]] ובוחרים [[Activity]].","shot":"תפריט Add Services פתוח. לסמן את Activity."},{"title":"יעד","text":"המערכת זוכרת את היעד הראשון בדוקט (אצל כהן: טבריה). ב-[[Destination]] מקלידים את היעד של האתר שבשאלה (למשל ירושלים) ובוחרים אותו מהרשימה.","shot":"מסך החיפוש של Activity עם שדה Destination והרשימה הנפתחת. לסמן את השדה."},{"title":"טווח תאריכים וחיפוש","text":"ברירת המחדל היא היום הראשון של הטיול. משנים את טווח התאריכים כך שיכלול את יום הביקור שבשאלה. לוחצים [[Search]].","trap":"אם לא משנים, מחפשים ביום הראשון של הטיול ולא ביום הביקור.","shot":"שדות התאריכים וכפתור Search במסך Activity. לסמן אותם."},{"title":"בוחרים אתר","text":"ברשימת האתרים מוצאים את האתר שבשאלה (למשל יד ושם) ולוחצים [[Details]].","shot":"רשימת האתרים בירושלים. לסמן את יד ושם ואת Details."},{"title":"סוג ותאריך","text":"בוחרים [[Type]] (למשל חצי יום או יום שלם, לפי מה שמופיע) ואת [[Date]] של הביקור לפי השאלה.","shot":"מסך הפרטים של האתר. לסמן את Type ואת Date.","verify":"אילו אפשרויות Type מופיעות באתר כמו יד ושם, והאם בכל האתרים יש Type."},{"title":"מקבלים מחיר","text":"לוחצים [[Select]]. מופיע מחיר.","shot":"אותו מסך אחרי Select, עם המחיר. לסמן את המחיר."},{"title":"מזמינים אתר אחד","text":"לוחצים [[Book]]. יש גם [[Add More Activities]], כמו עגלת קניות לכמה אתרים, אבל עדיף להזמין כל אטרקציה בנפרד.","why":"כל אטרקציה נהיית טרנזקציה נפרדת בדוקט. זה פשוט יותר.","shot":"הכפתורים Book ו-Add More Activities. לסמן את Book."},{"title":"בקשות מיוחדות","text":"במסך הבא יש מקום לבקשות מיוחדות. בדרך כלל אין. לוחצים [[Continue]].","shot":"מסך הבקשות המיוחדות. לסמן Continue."},{"title":"תשלום ואישור","text":"בסיכום בודקים תאריך וסוג שירות. מחליפים ל-[[Request other payment method]] ולוחצים [[Confirm]].","shot":"מסך הסיכום של ה-Activity. לסמן את התאריך, אמצעי התשלום ו-Confirm."},{"title":"בודקים בדוקט","text":"בחלק [[Services]] מופיעה שורה עם אייקון של Activity: שם האתר, העיר, התאריך והמחיר. לאתר נוסף (למשל גן החיות התנ״כי) חוזרים על כל השלבים מההתחלה.","shot":"שורת ה-Activity בחלק Services. לסמן את האייקון, שם האתר והתאריך."}],"oral":[{"q":"מה ההבדל בין Activity ל-Guide?","a":"Activity = פעילות לא פרטית, עם אנשים אחרים: כניסה למוזיאון, גן חיות או סיור רגולרי. Guide = סיור פרטי שלי, עם נהג או מדריך ברכב צמוד."},{"q":"למה עדיף להזמין כל אטרקציה בנפרד?","a":"כי כך כל אטרקציה היא טרנזקציה נפרדת בדוקט, וזה פשוט יותר."},{"q":"סיור רגולרי מבין הרים. לאיזה סוג שירות רושמים אותו?","a":"ל-Activity (דרך Add Manual Services), כי מצטרפים לטיול קבוע עם אנשים אחרים."},{"q":"איך מזהים שורת Activity בדוקט?","a":"לפי האייקון המיוחד שלה. בשורה מופיעים שם האתר, העיר, התאריך והמחיר."}],"check":["לכל אתר בשאלה יש שורת Activity נפרדת.","התאריך בכל שורה הוא יום הביקור שבשאלה.","האתר הוא בדיוק האתר שבשאלה, בעיר הנכונה.","החלפתי אמצעי תשלום ואישרתי (Confirm)."],"sources":["TB_master §4 (Activity)","00_docs_summary: הזמנות מתוך המערכת — פעילות (Activity); מושגים מרכזיים","hishtalmut_01 §11 (Activity: יד ושם, גן החיות התנ״כי, כל אטרקציה בנפרד)","hishtalmut_02 §6 (Activity מול Guide)","hishtalmut_04 חלק א׳ (ב-Activity מקלידים יעד ספציפי)","video_galor_01 חלק א׳ (המערכת זוכרת את היעד)"],"record":"docket"},{"id":"fit-guide","track":"FIT","order":5,"icon":"🧭","title":"Guide: סיור פרטי","goal":"להזמין מתוך המערכת סיור פרטי ברכב צמוד, עם הרכב הנכון והתוספות שבשאלה.","why":"ב-Guide התלמידים טועים הרבה: ביעד, בתאריך הסיום ובתוספות. בבדיקה מסתכלים על סוג הרכב, תוספת הק״מ ותוספת השעות.","before":[{"term":"Guide","text":"סיור פרטי ברכב צמוד, עם נהג או מדריך, במסלול שאנחנו קובעים. המחיר נקבע לפי המרחק והשעות, ולא לפי האתרים. לכן המסלול עצמו לא נרשם בהזמנה."},{"term":"Half Day / Full Day","text":"חצי יום או יום מלא, לפי השאלה. המחיר כולל מכסה של שעות ושל ק״מ. מה שמעבר למכסה משלמים כתוספת."},{"term":"Private Touring","text":"סוג השירות שבוחרים: סיור פרטי ברכב לפי מספר המקומות (4, 6 או 10 Seater). האפשרות הראשונה ברשימה היא שירותי מדריך בלבד, ובדרך כלל לא בוחרים בה."},{"term":"Additional Kilometers / Additional Hours","text":"ק״מ נוספים ושעות נוספות מעבר למכסה. הכמות כתובה בשאלה. יש גם תוספת לינת מדריך, אבל רק בסיור של יותר מיום אחד."}],"steps":[{"title":"הוספת שירות: Guide","text":"בתוך הדוקט, בחלק [[Services]], לוחצים [[Add Services]] ובוחרים [[Guide]].","shot":"תפריט Add Services פתוח. לסמן את Guide."},{"title":"יעד: תמיד Israel","text":"ב-[[Destination]] בוחרים [[Israel]]. תמיד, בלי קשר למה שכתוב בשאלה.","why":"המחיר נגזר ממרחק ומשעות, לא מהאתרים.","trap":"גם אם בשאלה כתוב ים המלח, גליל, ירושלים או תל אביב, היעד הוא [[Israel]]. עיר לא תעבוד. זו אחת הטעויות הנפוצות.","shot":"מסך החיפוש של Guide עם Destination = Israel. לסמן את השדה."},{"title":"תאריך התחלה וסיום","text":"בוחרים את תאריך הסיור. לסיור של יום אחד מזינים תאריך סיום זהה לתאריך ההתחלה.","why":"אפשר להזמין סיור של כמה ימים, ולכן המערכת מבקשת גם תאריך סיום.","shot":"שדות תאריך ההתחלה והסיום, עם אותו תאריך בשניהם. לסמן אותם."},{"title":"חצי יום או יום מלא","text":"ב-[[Type]] בוחרים חצי יום או יום מלא, לפי השאלה. לוחצים [[Search]].","why":"אם לא בוחרים, מופיעות כל האפשרויות: קודם חצי יום ואחר כך יום מלא.","shot":"שדה Type פתוח וכפתור Search. לסמן אותם."},{"title":"בוחרים רכב","text":"ברשימה בוחרים [[Private Touring]] לפי מספר הנוסעים (4, 6 או 10 Seater), ולוחצים [[Book]]. משפחת כהן = 4 נוסעים.","trap":"האפשרות הראשונה ברשימה היא שירותי מדריך בלבד. בדרך כלל לא היא.","shot":"רשימת התוצאות של Guide. לסמן את שירותי המדריך בלבד (מה לא בוחרים) ואת Private Touring המתאים.","verify":"איזה רכב מתאים ל-4 נוסעים (4 Seater?), ומה השם המדויק של כל אפשרות ברשימה."},{"title":"ק״מ נוספים","text":"אם בשאלה יש ק״מ מעבר למכסה, מסמנים V ב-[[Additional Kilometers]] ומקלידים את מספר הק״מ הנוספים. דוגמה מההשתלמות: סיור יום מלא לים המלח ועין גדי, עם 45 ק״מ נוספים.","shot":"מסך התוספות. לסמן את V ואת שדה הכמות של Additional Kilometers.","verify":"באיזו עמודה מקלידים את הכמות (בתמלול: Units (?)), ומה המכסה של ק״מ ושעות שכלולה ביום מלא."},{"title":"שעות נוספות","text":"אם בשאלה יש שעות מעבר למכסה, מסמנים V ב-[[Additional Hours]] ומקלידים את מספר השעות (בדוגמה: 2).","shot":"אותו מסך. לסמן את V ואת שדה הכמות של Additional Hours."},{"title":"לינת מדריך: רק ביותר מיום","text":"יש עוד שלוש תוספות של לינת מדריך: צפון, דרום וירושלים. מסמנים אותן רק בסיור של יותר מיום אחד. בסיור של יום אחד לא נוגעים בהן.","shot":"אותו מסך. לסמן את שלוש שורות לינת המדריך.","verify":"המחירים ללילה כפי שמופיעים היום (בהשתלמות: צפון 80$, דרום 95$, ירושלים 108$)."},{"title":"בודקים ומתקדמים","text":"לוחצים [[Proceed]]. במסך הבדיקה בודקים את סוג הרכב ואת התוספות.","shot":"מסך הבדיקה אחרי Proceed. לסמן את סוג הרכב ואת שורות התוספות."},{"title":"תשלום ואישור","text":"מחליפים ל-[[Request other payment method]] ולוחצים [[Confirm]].","shot":"אמצעי התשלום וכפתור Confirm במסך הסיכום של Guide. לסמן את שניהם."},{"title":"בודקים בדוקט","text":"בחלק [[Services]] מופיעה שורה עם אייקון של Guide, למשל [[Private Tour 4 Seater Full Day]], ומחיר.","why":"אם הסכום נכון, כנראה כל הרכיבים נכונים. ובכל זאת בודקים רכב, ק״מ ושעות.","shot":"שורת ה-Guide בחלק Services. לסמן את האייקון ואת שם השירות."}],"oral":[{"q":"למה ב-Guide היעד הוא תמיד Israel?","a":"כי מחיר הסיור הפרטי נקבע לפי מרחק ושעות, ולא לפי האתרים. המסלול עצמו לא נרשם בהזמנה."},{"q":"מה כלול במחיר של יום מלא, ומתי משלמים תוספת?","a":"המחיר כולל מכסה של שעות ושל ק״מ. אם הסיור ארוך יותר או רחוק יותר, מוסיפים Additional Hours או Additional Kilometers."},{"q":"מתי מוסיפים לינת מדריך?","a":"רק בסיור של יותר מיום אחד. בסיור של יום אחד לא."},{"q":"איך בוחרים את הרכב ב-Guide?","a":"בוחרים Private Touring לפי מספר הנוסעים (4, 6 או 10 מקומות). לא את האפשרות של שירותי מדריך בלבד."}],"check":["Destination = Israel.","בסיור של יום אחד: תאריך הסיום = תאריך ההתחלה.","חצי יום או יום מלא, לפי השאלה.","Private Touring עם רכב שמתאים למספר הנוסעים.","ק״מ נוספים ושעות נוספות בדיוק כמו בשאלה, ובלי לינת מדריך ביום אחד.","החלפתי אמצעי תשלום ואישרתי (Confirm)."],"sources":["TB_master §4 (Guide)","00_docs_summary: הזמנות מתוך המערכת — רכב אשכול / סיור פרטי (Guide)","hishtalmut_01 §12 (Guide: Israel, תאריך סיום, Private Touring, תוספות, לינת מדריך, תרגיל ים המלח ועין גדי)","hishtalmut_02 §6 (Activity מול Guide)","hishtalmut_04 חלק א׳ (מלכודת Destination)","hishtalmut_09 §2 (בדיקת Guide: רכב, ק״מ, שעות)"],"record":"docket"},{"id":"fit-bh-site","track":"FIT","order":6,"icon":"🗺️","title":"אתר בין הרים — לקרוא נכון","goal":"למצוא באתר בין הרים העברה, סיור פרטי או סיור רגולרי, לקבל מחיר נכון לתאריך ולמספר הנוסעים, ולדעת איפה בעמוד נמצא המידע שהבוחן שואל עליו.","why":"את שירותי בין הרים לא מזמינים בטרוול בוסטר אלא באתר של הספק. מחיר שגוי מהאתר נכנס כסכום שגוי לדוקט, ובבעל פה שואלים גם על מידע מהאתר (ימים, שפות, ביטול, הנחת ילדים).","before":[{"term":"Free Sale","text":"הזמנה מחוץ למערכת. מזמינים אצל הספק (בין הרים), וטרוול בוסטר רק רושמת אותה. בבחינה לא מזמינים באמת: לוקחים את המחיר מהאתר ועוצרים."},{"term":"Private Tours","text":"שירות פרטי שלי: העברות (Airport Transfers) וסיורים פרטיים ברכב עם נהג. המחיר הוא לרכב, לא לנוסע."},{"term":"Daily Tours","text":"סיור רגולרי: טיול שיוצא באופן קבוע, והנוסעים מצטרפים אליו יחד עם אנשים אחרים. המחיר הוא לנוסע. Tour Packages = טיול של יותר מיום אחד."},{"term":"Pick up","text":"נקודת האיסוף ושעת האיסוף. בוחרים את הנקודה לפי העיר שבה הנוסעים ישנים באותו יום, גם אם השאלה לא כותבת את זה."}],"steps":[{"title":"נכנסים לאתר בין הרים","text":"פותחים את האתר beinharimtours.com בלשונית נפרדת, ליד טרוול בוסטר. האתר באנגלית. מותר לתרגם מילה פה ומילה שם בגוגל.","trap":"לא לתרגם את כל האתר לעברית: התרגום גרוע, והימים בלוח הזמינות משתבשים.","shot":"עמוד הבית של בין הרים, עם התפריט העליון. לסמן את [[Private Tours]]."},{"title":"העברה: בוחרים כיוון","text":"[[Private Tours]] ← [[Airport Transfers]]. בוחרים את הכיוון והעיר שבשאלה, למשל מירושלים לבן גוריון ביום האחרון. גוללים למטה ל-[[Prices]]: יש מחיר לרכב לפי מספר מקומות (עד 3, עד 6 וכו׳).","trap":"משפחת כהן היא 4 נוסעים (2 מבוגרים, ילד וסבתא). אי אפשר לקחת רכב של עד 3.","shot":"עמוד העברה אחד (למשל ירושלים ← בן גוריון), גלול לטבלת [[Prices]]. לסמן את שורות הרכבים לפי מספר נוסעים.","verify":"שם התפריט Airport Transfers מתחת ל-Private Tours (בתמלול ההשתלמות הנתיב מסומן בסימן שאלה)."},{"title":"העברה: Book Now ותאריך","text":"לוחצים [[Book Now]], בוחרים את התאריך שבשאלה ומכניסים את סך כל הנוסעים. בהעברה אין הבחנה בין מבוגר לילד.","why":"התאריך יכול לשנות את המחיר (למשל תוספת שבת), ולפי מספר האנשים האתר בוחר לבד את הרכב המתאים.","shot":"מסך [[Book Now]] של העברה: לוח התאריכים ושדה מספר האנשים. לסמן את המחיר שמתקבל."},{"title":"עוצרים במחיר","text":"כשמופיע המחיר, רושמים אותו על הדף ועוצרים. לא ממשיכים בהזמנה באתר.","trap":"לא ממלאים פרטים ולא משלמים באתר. בבחינה רק לוקחים את המחיר.","shot":"אותו מסך עם המחיר הסופי מסומן, לפני כל טופס פרטים."},{"title":"סיור פרטי: אזור וטיול","text":"[[Private Tours]] ← בוחרים אזור (למשל ירושלים) ← [[Explore More]] ← מוצאים את הטיול שבשאלה.","trap":"שמות הטיולים דומים מאוד זה לזה. משווים את השם בדיוק, מילה במילה, לשם שבשאלה.","shot":"רשימת הסיורים הפרטיים של אזור אחד. לסמן שני טיולים עם שמות דומים."},{"title":"קוראים את עמוד הטיול","text":"בעמוד הטיול מוצאים: [[Highlights]] (האתרים העיקריים), זמינות (באילו ימים ובאיזו שפה), [[Included]] ו-[[Not Included]], הערות חשובות (למשל לבוש צנוע), [[Cancellation Policy]] (מדיניות ביטול), ושאלות נפוצות (טיפ למדריך, ביטול ושינוי, הנחה לילדים, גיל מינימום).","why":"לא צריך לשנן. מותר לגלול ולחפש בבחינה, אבל חייבים לדעת איפה כל דבר נמצא.","shot":"עמוד טיול אחד, גלול כך שרואים את הזמינות, Included/Not Included ו-Cancellation Policy. לסמן כל אחד מהם."},{"title":"סיור פרטי: מחיר לתאריך","text":"לוחצים [[Book Now]]. בוחרים תאריך, מספר מבוגרים, מספר ילדים ועיר איסוף. רושמים את המחיר שמתקבל.","why":"בהשתלמות: מבחוץ הטיול עלה 920 דולר, ובשבת 1,080 דולר. המחיר של שבת לא מופיע בשום מקום בחוץ, ולכן חובה להיכנס ולבחור תאריך.","trap":"לא להעתיק את המחיר שמופיע בחוץ, על כרטיס הטיול.","shot":"מסך [[Book Now]] של סיור פרטי עם תאריך, מבוגרים, ילדים ועיר איסוף. לסמן את המחיר המעודכן."},{"title":"סיור רגולרי: מוצאים טיול","text":"[[Daily Tours]] (טיול של יום) או [[Tour Packages]] (יותר מיום) ← אזור ← הטיול שבשאלה ← [[Book Now]] ליד עיר המוצא.","trap":"גם כאן השמות דומים, למשל העיר העתיקה לעומת העיר החדשה והעתיקה. טיול לא נכון = סכום לא נכון.","shot":"רשימת ה-Daily Tours באזור ירושלים. לסמן שני טיולים עם שמות דומים.","verify":"שם התפריט באתר: Daily Tours או Day Tours (המקורות משתמשים בשניהם)."},{"title":"זמינות, שפה ושעת איסוף","text":"בודקים באילו ימים ובאיזו שפה הטיול יוצא, ובוחרים תאריך שבו הוא באמת יוצא. בוחרים נקודת איסוף לפי העיר שבה הנוסעים ישנים באותו יום, ורושמים את שעת האיסוף שלה (למשל 08:30).","why":"את שעת האיסוף חובה להזין אחר כך בטרוול בוסטר.","trap":"אם אין טיול בתאריך שבשאלה, מחפשים יום חלופי באותו שבוע ומספרים למורה או לבוחן.","shot":"מסך ההזמנה של סיור רגולרי: לוח הזמינות (ימים ושפה) ורשימת נקודות האיסוף עם השעות. לסמן את שעת האיסוף."},{"title":"שלושה בירורי מחיר","text":"בסיור רגולרי המחיר לנוסע. בודקים שלוש פעמים: 1 מבוגר ו-0 ילדים = מחיר מבוגר. 0 מבוגרים ו-1 ילד = מחיר ילד. כל הנוסעים יחד (משפחת כהן: 3 מבוגרים וילד) = סך הכול לבקרה. רושמים את שלושת המספרים.","why":"בטרוול בוסטר מזינים מחיר ליד כל נוסע, ובסוף משווים לסך הכול מהאתר.","shot":"מסך המחיר של סיור רגולרי עם שדות המבוגרים והילדים. לסמן את שני השדות ואת המחיר.","verify":"בחוברת כתוב לבחור באתר ״קבוצה גדולה״ אם נדרש. לבדוק באתר מה האפשרות הזו ומתי היא מופיעה."},{"title":"דף סיכום לפני טרוול בוסטר","text":"לפני שעוברים לטרוול בוסטר, בודקים שעל הדף כתובים: השם המדויק של השירות, התאריך, נקודת האיסוף והשעה, והמחיר (בסיור רגולרי: מבוגר, ילד וסך הכול).","why":"לפי סדר העבודה של ירון: מזמינים באתר ומיד רושמים בטרוול בוסטר, שירות אחרי שירות.","shot":"אין צורך בצילום מסך. אפשר לצלם דף עבודה עם הפרטים מסומנים במרקר."}],"oral":[{"q":"מה ההבדל בין Private Tours ל-Daily Tours?","a":"ב-Private Tours הנוסעים מקבלים רכב ונהג רק להם, והמחיר הוא לרכב. ב-Daily Tours מצטרפים לטיול קבוע עם אנשים אחרים, והמחיר הוא לנוסע."},{"q":"למה חייבים להיכנס ל-Book Now ולבחור תאריך?","a":"כי התאריך יכול לשנות את המחיר. למשל בשבת או בחג יש תוספת (920 דולר לעומת 1,080), והיא לא מופיעה בחוץ."},{"q":"באילו ימים יוצא הטיול בגרמנית? איפה מוצאים את זה?","a":"בעמוד הטיול, בחלק הזמינות: שם כתוב באילו ימים ובאיזו שפה הטיול יוצא."},{"q":"מה עושים אם אין טיול בתאריך שבשאלה?","a":"מחפשים טיול חלופי ביום אחר באותו שבוע, ומסבירים לבוחן."},{"q":"מאיזו נקודה בוחרים איסוף?","a":"מהעיר שבה הנוסעים ישנים באותו יום, לפי המלון שבדוקט."},{"q":"איפה מוצאים מה כלול בטיול ומה מדיניות הביטול?","a":"בעמוד הטיול: Included ו-Not Included, ו-Cancellation Policy. שאלות על טיפ, ביטול והנחת ילדים נמצאות בשאלות הנפוצות בתחתית העמוד."}],"check":["לכל שירות מבין הרים יש על הדף מחיר שנלקח אחרי Book Now ובחירת תאריך","השם של כל טיול הועתק בדיוק, ולא טיול עם שם דומה","בהעברה הוכנס סך כל הנוסעים, והרכב מתאים למספר שלהם","בסיור רגולרי רשומים מחיר מבוגר, מחיר ילד וסך הכול לבקרה","בסיור רגולרי רשומות נקודת איסוף ושעת איסוף, לפי העיר שבה ישנים באותו יום","לא בוצעה הזמנה באתר: עצרנו במחיר"],"sources":["TB_master §5","00_docs_summary: הזמנות מחוץ למערכת — אתר בין הרים","hishtalmut_02 §2–§3, §5–§6","hishtalmut_09 §2 (סיור רגולרי, טיול חלופי)","video_galor_01 (בין הרים נשאר, תרגום האתר)"],"record":"none"},{"id":"fit-manual-transfer","track":"FIT","order":7,"icon":"🚐","title":"העברה מבין הרים","goal":"לרשום בדוקט העברה שהוזמנה בבין הרים, עם סטטוס OK, ספק בין הרים ומחיר אחד לרכב.","why":"זו הפעם הראשונה שמזינים שירות ידנית. אותו דפוס בדיוק חוזר בסיור פרטי ובסיור רגולרי, ולחיצה על Save לפני המחיר משבשת את העמלה.","before":[{"term":"Add Manual Service","text":"הוספת שירות ידנית, לשירות שהוזמן מחוץ למערכת. זה לא Add Services, שמשמש להזמנות מתוך המערכת."},{"term":"Status OK","text":"ההזמנה בבין הרים מאושרת מיד אצל הספק, ולכן כבר ברישום מסמנים OK. אין צורך לדווח ולאשר אותה אחר כך."},{"term":"Supplier Price","text":"המחיר שהספק נותן. כאן מכניסים את המחיר שרשמתם מאתר בין הרים."},{"term":"מחיר לרכב","text":"בהעברה המחיר הוא לרכב כולו, לא משנה כמה נוסעים. לכן מכניסים סכום אחד, ליד נוסע אחד בלבד."}],"steps":[{"title":"פותחים הוספה ידנית","text":"בתוך הדוקט, בחלק [[Services]], פותחים את החץ שליד [[Add Services]] ובוחרים [[Add Manual Service]].","trap":"לא [[Add Services]]: הוא להזמנות מתוך המערכת.","shot":"חלק Services בדוקט עם החץ פתוח. לסמן את [[Add Manual Service]].","verify":"הכיתוב המדויק בתפריט: Add Manual Service או Add Manual Services (המקורות כותבים את שניהם)."},{"title":"בוחרים Transport","text":"בסוג השירות בוחרים [[Transport]].","shot":"רשימת סוגי השירותים הידניים. לסמן את [[Transport]]."},{"title":"מאיפה ולאן","text":"ממלאים From ו-To: עיר, שדה תעופה או תחנת רכבת. בהעברה חזור של משפחת כהן: From = שם המלון בירושלים, ועיר שנבחרת מהרשימה הנגללת. To = [[Ben Gurion Airport]]. אם בשאלה יש פרטי טיסה, מוסיפים אותם בפרטים.","shot":"טופס Transport ידני עם שדות From ו-To ממולאים. לסמן את שני השדות ואת בחירת העיר מהרשימה.","verify":"שמות השדות בטופס (From/To, Details, City) ואיפה בדיוק מזינים מספר טיסה."},{"title":"תאריך ושעה","text":"מזינים את תאריך ההעברה ואת שעת האיסוף שבשאלה. אם בשאלה אין שעת הגעה, שעת ההגעה היא שעה אחרי שעת האיסוף.","why":"בהשתלמות: נסיעה לבן גוריון נמשכת כשעה.","shot":"שדות התאריך והשעות בטופס. לסמן את שעת האיסוף ואת שעת ההגעה.","verify":"באילו שדות מזינים שעת יציאה ושעת הגעה בטופס Transport ידני."},{"title":"סטטוס OK","text":"משנים את הסטטוס ל-[[OK]].","why":"ההזמנה נעשתה אצל הספק ואושרה שם מיד. טרוול בוסטר כאן רק מערכת רישום.","shot":"שדה הסטטוס פתוח, עם [[OK]] מסומן."},{"title":"ספק: בין הרים","text":"בשדה [[Service Provider]] בוחרים [[Ben Harim]].","shot":"שדה הספק עם Ben Harim נבחר. לסמן את השדה.","verify":"שם השדה במסך: Service Provider, Supplier או Reserved through (המקורות משתמשים בשלושתם)."},{"title":"לא Save! עוברים למחיר","text":"לא לוחצים [[Save]] ולא [[Save & Exit]]. עוברים ישר ל-[[Passengers & Pricing]].","trap":"Save לפני שהוזן מחיר משבש את העמלה. בחוברת הישנה היה כתוב ללחוץ Save, וזה תוקן.","shot":"הטופס עם הכפתורים Save ו-Save & Exit מסומנים באדום (לא ללחוץ), והלשונית [[Passengers & Pricing]] מסומנת בירוק."},{"title":"מחיר אחד, נוסע אחד","text":"ב-[[Passengers & Pricing]], בחלק התחתון, מכניסים את מחיר ההעברה מבין הרים בשדה [[Supplier Price]], רק ליד נוסע אחד (הנוסע הראשי). לשאר הנוסעים לא מכניסים מחיר.","why":"המחיר הוא לרכב. בהשתלמות: העברה של 96 דולר נרשמה כסכום אחד.","trap":"לא לחלק את המחיר בין הנוסעים ולא להכניס אותו ליד כל נוסע: כך הסכום יוכפל.","shot":"Passengers & Pricing עם רשימת הנוסעים. לסמן את שדה [[Supplier Price]] ליד הנוסע הראשון בלבד."},{"title":"Calc","text":"לוחצים [[Calc]]. בודקים שהמחיר נשאר ולא התאפס.","why":"בלי Calc המחיר לפעמים משתנה או מתאפס. לכן לוחצים תמיד.","shot":"הכפתור [[Calc]] מסומן, והסכום אחרי החישוב.","verify":"הכיתוב על הכפתור: Calc או Calculate."},{"title":"Save & Exit ובדיקה","text":"רק עכשיו לוחצים [[Save & Exit]]. בדוקט מופיעה שורת העברה חדשה של בין הרים, עם סטטוס OK והמחיר הנכון.","shot":"הדוקט עם שורת ההעברה הידנית החדשה. לסמן את סמל הסטטוס ואת המחיר."}],"oral":[{"q":"מה ההבדל בין Add Services ל-Add Manual Service?","a":"Add Services מזמין מתוך המערכת, מהקצאה (Allocation). Add Manual Service רק רושם בדוקט הזמנה שכבר נעשתה אצל ספק חיצוני כמו בין הרים (Free Sale)."},{"q":"למה מסמנים סטטוס OK כבר ברישום?","a":"כי ההזמנה נעשתה במערכת של הספק ואושרה שם מיד. הספק כבר יודע עליה."},{"q":"למה מכניסים את המחיר רק ליד נוסע אחד?","a":"כי מחיר ההעברה הוא לרכב, לא לנוסע. אם מכניסים ליד כל נוסע, הסכום יוכפל."},{"q":"למה לא לוחצים Save לפני שמכניסים מחיר?","a":"כי זה משבש את העמלה. קודם מחיר ו-Calc, ורק אז Save & Exit."}],"check":["השירות נרשם דרך Add Manual Service ← Transport","From ו-To נכונים, כולל עיר מהרשימה","תאריך ושעה לפי השאלה (ואם אין שעת הגעה: שעה אחרי האיסוף)","סטטוס OK וספק Ben Harim","המחיר מופיע פעם אחת בלבד, ליד נוסע אחד, ושווה למחיר מהאתר"],"sources":["TB_master §5","00_docs_summary: הזמנות מחוץ למערכת — העברה","hishtalmut_02 §4, §6 (ההיגיון במחיר)","hishtalmut_04 חלק א׳ (Passengers & Pricing בהעברה)","hishtalmut_09 §2 (תמחור לעומת העברה)"],"record":"docket"},{"id":"fit-manual-private","track":"FIT","order":8,"icon":"🚙","title":"סיור פרטי מבין הרים","goal":"לרשום בדוקט סיור פרטי שהוזמן בבין הרים, כ-Guide, עם המחיר לתאריך הנכון.","why":"סיור פרטי נרשם כ-Guide ולא כ-Activity. בחירה לא נכונה של סוג השירות, או מחיר בלי תוספת שבת, הם טעויות נפוצות.","before":[{"term":"Guide","text":"משהו פרטי שלי: סיור פרטי ברכב עם נהג או מדריך. הכלל נכון גם בתוך המערכת וגם בבין הרים."},{"term":"Activity","text":"פעילות יחד עם אנשים אחרים: מוזיאון, אתר, סיור רגולרי. סיור פרטי הוא לא Activity."},{"term":"אותו דפוס","text":"הרישום זהה ליחידת ההעברה: סטטוס OK, ספק בין הרים, לא Save לפני המחיר, Calc ואז Save & Exit."}],"steps":[{"title":"הוספה ידנית: Guide","text":"בחלק [[Services]]: החץ שליד [[Add Services]] ← [[Add Manual Service]] ← [[Guide]].","trap":"לא [[Activities]]. גם המדריך בהשתלמות טעה כאן בהתחלה ותיקן: סיור פרטי = Guide.","shot":"רשימת סוגי השירותים הידניים. לסמן את [[Guide]]."},{"title":"שם הטיול","text":"מעתיקים את שם הטיול מאתר בין הרים ומדביקים בשדה השם.","why":"שמות הטיולים דומים מאוד. העתקה מונעת טעות בשם.","shot":"טופס Guide ידני עם שדה השם ממולא. לסמן את השדה."},{"title":"יעד מהרשימה","text":"ב-[[Destination]] מקלידים את האותיות הראשונות ובוחרים מהרשימה הנגללת (בהשתלמות: [[Dead Sea]]).","trap":"חובה לבחור שורה מהרשימה. טקסט שרק הוקלד לא נחשב.","shot":"שדה Destination עם הרשימה הנגללת פתוחה. לסמן את השורה שנבחרה."},{"title":"ספק: בין הרים","text":"בשדה הספק בוחרים [[Ben Harim]], כמו ביחידת ההעברה.","shot":"שדה הספק עם Ben Harim נבחר.","verify":"בחוברת השדה נקרא כאן Reserved through. לבדוק את שם השדה בטופס Guide ידני."},{"title":"תאריך ושעה","text":"מזינים את תאריך הטיול. בטיול של יום אחד, תאריך ההתחלה והסיום זהים. את השעה משאירים בברירת המחדל, אלא אם בשאלה כתוב מתי יוצאים (למשל ״יוצאים ב-11״).","why":"בסיור פרטי השעה מתואמת בין הנהג לנוסעים, ואפשר לקבוע כל שעה.","shot":"שדות התאריכים והשעות בטופס. לסמן את תאריך ההתחלה והסיום."},{"title":"סטטוס OK","text":"משנים את הסטטוס ל-[[OK]].","shot":"שדה הסטטוס עם [[OK]] מסומן."},{"title":"מחיר אחד בלי Save","text":"לא לוחצים [[Save]]. עוברים ל-[[Passengers & Pricing]] ומכניסים את המחיר מהאתר בשדה [[Supplier Price]], ליד נוסע אחד בלבד.","why":"גם בסיור פרטי המחיר הוא לרכב. בהשתלמות נרשם 1,080 דולר, המחיר של שבת.","trap":"המחיר הוא המחיר שהתקבל אחרי בחירת התאריך באתר, כולל תוספת שבת או חג. לא המחיר שבחוץ.","shot":"Passengers & Pricing עם [[Supplier Price]] ליד הנוסע הראשון בלבד."},{"title":"Calc ואז Save & Exit","text":"לוחצים [[Calc]], ואחר כך [[Save & Exit]]. בדוקט מופיעה שורת Guide של בין הרים, עם סטטוס OK והמחיר.","why":"את השוברים לא מפיקים עכשיו. מפיקים את כולם יחד בסוף.","shot":"הדוקט עם שורת ה-Guide הידנית. לסמן את סמל השירות, הסטטוס והמחיר."}],"oral":[{"q":"למה סיור פרטי נרשם כ-Guide ולא כ-Activity?","a":"Guide הוא שירות פרטי שלי. Activity הוא פעילות יחד עם אנשים אחרים, כמו מוזיאון או סיור רגולרי."},{"q":"למה מחיר הסיור הוא 1,080 ולא 920 כמו שכתוב בחוץ?","a":"כי הטיול בשבת, ובשבת או בחג יש תוספת. רואים אותה רק אחרי שבוחרים תאריך ב-Book Now."},{"q":"מתי משנים את השעה בסיור פרטי?","a":"רק אם בשאלה כתובה שעה. אחרת משאירים את ברירת המחדל, כי בסיור פרטי השעה מתואמת עם הנהג."}],"check":["השירות נרשם כ-Guide דרך Add Manual Service","שם הטיול הועתק בדיוק מהאתר","Destination נבחר מהרשימה, והספק Ben Harim","התאריך נכון, והשעה שונתה רק אם השאלה ביקשה","סטטוס OK","מחיר אחד ליד נוסע אחד, כולל תוספת שבת או חג אם יש"],"sources":["TB_master §5","00_docs_summary: הזמנות מחוץ למערכת — סיור פרטי","hishtalmut_02 §5 (רישום בטרוול בוסטר), §6 (Activity מול Guide)","hishtalmut_04 חלק א׳ (Passengers & Pricing במדריך)","hishtalmut_09 §2 (שעה בסיור פרטי)"],"record":"docket"},{"id":"fit-manual-regular","track":"FIT","order":9,"icon":"🚌","title":"סיור רגולרי מבין הרים","goal":"לרשום בדוקט סיור רגולרי מבין הרים, עם שעת האיסוף, מחיר מבוגר ליד כל מבוגר ומחיר ילד ליד כל ילד.","why":"בסיור רגולרי יש שתי טעויות שמורידות ניקוד: שוכחים את שעת האיסוף, או מכניסים מחיר אחד כמו בהעברה. הבקרה מול הסך הכול מהאתר תופסת את רוב הטעויות.","before":[{"term":"Activities","text":"סיור רגולרי הוא פעילות יחד עם אנשים אחרים, ולכן נרשם כמו מוזיאון: Activity ולא Guide."},{"term":"מחיר לנוסע","text":"בסיור רגולרי כל נוסע משלם. לכן מזינים מחיר ליד כל נוסע: מחיר מבוגר ליד מבוגר, מחיר ילד ליד ילד."},{"term":"Pickup Hour","text":"שעת האיסוף מהאתר, לפי נקודת היציאה (תל אביב, ירושלים וכו׳). בסיור רגולרי חובה להזין אותה."}],"steps":[{"title":"הוספה ידנית: Activities","text":"בחלק [[Services]]: החץ שליד [[Add Services]] ← [[Add Manual Service]] ← [[Activities]].","trap":"לא [[Guide]]. Guide הוא רק לסיור פרטי.","shot":"רשימת סוגי השירותים הידניים. לסמן את [[Activities]].","verify":"הכיתוב המדויק ברשימה: Activities או Activity."},{"title":"שם, יעד וספק","text":"מעתיקים את שם הטיול מהאתר ומדביקים. ב-[[Destination]] בוחרים את האזור מהרשימה (למשל ירושלים). בשדה הספק בוחרים [[Ben Harim]].","trap":"שמות דומים: העיר העתיקה לעומת העיר החדשה והעתיקה. בודקים שהשם תואם לשאלה.","shot":"טופס Activities ידני עם שם, יעד וספק ממולאים. לסמן את שלושת השדות.","verify":"שם שדה הספק בטופס הזה (Service Provider או Reserved through)."},{"title":"תאריך","text":"מזינים את התאריך שבו הטיול באמת יוצא, כפי שנבחר באתר (למשל יום רביעי, אם הטיול יוצא רק ברביעי).","shot":"שדה התאריך בטופס. לסמן אותו."},{"title":"שעת איסוף: חובה","text":"משנים את שעת ההתחלה לשעת האיסוף מהאתר, לפי נקודת היציאה. בהשתלמות: 08:30, והוקלד 0830. את שעת הסיום לא צריך לשנות.","trap":"תלמידים רבים שוכחים. בלי שעת איסוף הסעיף לא נפסל, אבל יורדות נקודות.","shot":"שדות השעות בטופס. לסמן את שעת ההתחלה עם שעת האיסוף."},{"title":"סטטוס OK","text":"משנים את הסטטוס ל-[[OK]]. לא לוחצים [[Save]].","trap":"Save לפני המחיר משבש את העמלה, כמו ביחידת ההעברה.","shot":"שדה הסטטוס עם [[OK]], והכפתור Save מסומן כ״לא ללחוץ״."},{"title":"מחיר ליד כל נוסע","text":"ב-[[Passengers & Pricing]], בחלק התחתון, מכניסים [[Supplier Price]] ליד כל נוסע: מחיר מבוגר ליד כל מבוגר, ומחיר ילד ליד כל ילד. משפחת כהן: מחיר מבוגר ליד שני ההורים וליד הסבתא, ומחיר ילד ליד הילד.","why":"בעבר פתחו חץ בתוך Pricing. היום מכניסים ישר בחלק התחתון.","trap":"לא סכום אחד ליד נוסע אחד, כמו בהעברה.","shot":"Passengers & Pricing עם ארבעה נוסעים. לסמן את המחיר ליד כל אחד, ואת ההבדל בין מחיר מבוגר למחיר ילד."},{"title":"Calc","text":"לוחצים [[Calc]].","shot":"הכפתור [[Calc]] והסכום הכולל אחרי החישוב."},{"title":"בקרה מול האתר","text":"לפני היציאה משווים: הסכום הכולל בטרוול בוסטר צריך להיות שווה לסך הכול שקיבלתם באתר בין הרים לכל הנוסעים יחד.","why":"כך מורה גילתה טעות: 285 בטרוול בוסטר מול 211 באתר.","trap":"אם יש הפרש, בודקים קודם: האם נבחר הטיול הנכון, והאם מחיר הילד הוזן ליד הילד.","shot":"הסכום הכולל ב-Passengers & Pricing, לצד דף העבודה עם הסך הכול מהאתר."},{"title":"Save & Exit","text":"לוחצים [[Save & Exit]]. בדוקט מופיעה שורת Activity של בין הרים, עם סטטוס OK.","shot":"הדוקט עם שורת הסיור הרגולרי. לסמן את השעה, הסטטוס והמחיר."}],"oral":[{"q":"למה בסיור רגולרי מכניסים מחיר ליד כל נוסע, ובהעברה רק ליד אחד?","a":"בהעברה המחיר הוא לרכב, ולכן סכום אחד. בסיור רגולרי המחיר הוא לנוסע, ומבוגר וילד משלמים מחיר שונה."},{"q":"למה סיור יומי נרשם כ-Activity?","a":"כי זו פעילות יחד עם אנשים אחרים, כמו מוזיאון. Guide הוא רק משהו פרטי שלי."},{"q":"למה חובה להזין שעת איסוף בסיור רגולרי, ובסיור פרטי לא?","a":"בסיור רגולרי הטיול יוצא בשעה קבועה מכל נקודת איסוף, והנוסעים צריכים להגיע אליה. בסיור פרטי השעה מתואמת עם הנהג."},{"q":"איך בודקים שהמחיר שהוזן נכון?","a":"משווים את הסכום הכולל בטרוול בוסטר לסך הכול שהאתר נתן לכל הנוסעים יחד."}],"check":["השירות נרשם דרך Add Manual Service כ-Activity, לא כ-Guide","התאריך הוא יום שבו הטיול באמת יוצא","שעת ההתחלה = שעת האיסוף מהאתר","סטטוס OK וספק Ben Harim","מחיר מבוגר ליד כל מבוגר ומחיר ילד ליד כל ילד","הסכום הכולל שווה לסך הכול מהאתר"],"sources":["TB_master §5","00_docs_summary: הזמנות מחוץ למערכת — סיור רגולרי","hishtalmut_02 §6","hishtalmut_04 חלק א׳ (שעת איסוף, מחיר לכל נוסע)","hishtalmut_09 §2 (הערת רפי על שעת איסוף, שמות טיולים דומים)"],"record":"docket"},{"id":"fit-confirm","track":"FIT","order":10,"icon":"✅","title":"אישור הזמנות","goal":"לאשר (לדווח לספק) כל הזמנה שבוצעה מתוך המערכת, ולדעת לבדוק אם הזמנה כבר אושרה.","why":"בבחינה חובה לאשר את כל ההזמנות שבוצעו מתוך המערכת. הזמנה שלא אושרה לא נספרת ביתרת הדוקט, ולכן תשובה ל״כמה צריך לשלם?״ תצא שגויה.","before":[{"term":"Allocation","text":"הקצאה: הספק שומר לנו מקומות (למשל 20 חדרים). כל עוד יש מקום, ההזמנה מאושרת מיד. אבל חובה לדווח לספק על כל מכירה, כי גם לסוכנויות אחרות יש הקצאות, ואחרת ייווצר אוברבוקינג."},{"term":"Free Sale","text":"הזמנה מחוץ למערכת (בין הרים). ההזמנה נעשתה אצל הספק, והוא כבר יודע עליה. לכן לא צריך לדווח."},{"term":"Report and Confirm","text":"הפעולה שמדווחת לספק ומאשרת את ההזמנה בדוקט. עושים אותה לכל שורה בנפרד."},{"term":"סמלי סטטוס","text":"V ירוק = Confirmed (יש מקום בהקצאה). סימן שאלה כחול = Request (נגמרה ההקצאה, ממתין לאישור). עיגול כתום עם שלוש נקודות = Request for Cancellation. X אדום = מבוטל. קיימים גם Waiting List ו-Sold Out."},{"term":"ירוק ≠ מאושר","text":"מבחוץ, בדוקט, אי אפשר לדעת אם הזמנה ירוקה כבר דווחה. רואים את זה רק בפנים: אם נשאר רק Cancel, היא אושרה."}],"steps":[{"title":"מחליטים מה מאשרים עכשיו","text":"סדר העבודה שירון ממליץ עליו: קודם מאשרים רק הזמנות עם סימן שאלה. אחר כך עושים ביטולים ושינויים. בסוף מאשרים את כל שאר ההזמנות, כולל הירוקות.","why":"הזמנה שאושרה קשה יותר לבטל או לשנות. כך חוסכים צעדים ובלבול.","shot":"דוקט עם כמה שורות: לפחות אחת עם V ירוק ואחת עם סימן שאלה כחול. לסמן את עמודת הסטטוס."},{"title":"מזהים את סוג השורה","text":"מעבירים את העכבר מעל סמל הסטטוס כדי לראות את שמו. מאשרים רק שורות שהוזמנו מתוך המערכת (Add Services): מלון, העברה, Activity ו-Guide מהמערכת.","shot":"סמל סטטוס עם החלון הקטן שנפתח בריחוף (למשל Confirmed או Request)."},{"title":"נכנסים לעיפרון","text":"לוחצים על העיפרון (Edit) בשורת ההזמנה.","shot":"שורת שירות בדוקט. לסמן את אייקון העיפרון."},{"title":"לשונית Reservation","text":"בתוך העיפרון עוברים ללשונית [[Reservation]].","shot":"מסך העריכה של השירות. לסמן את הלשונית [[Reservation]]."},{"title":"Report and Confirm","text":"לוחצים [[Reserve, Report and Confirm]] (או [[Report and Confirm]], לפי מה שמופיע).","trap":"לא ללחוץ [[Cancel, Report and Confirm]]. הכפתור הזה מבטל את ההזמנה.","shot":"לשונית Reservation עם כפתור האישור מסומן בירוק, וכפתור הביטול מסומן באדום.","verify":"הכיתוב המדויק על הכפתור: Reserve, Report and Confirm או Report and Confirm (המקורות כותבים את שניהם), והאם הוא משתנה לפי הסטטוס (ירוק או סימן שאלה)."},{"title":"מי אישר: שם או מספר","text":"אם בשאלה כתוב שם של מי שאישר (למשל רותי), מקלידים אותו ב-[[Confirmed with]]. אם יש מספר הזמנה, מקלידים אותו ב-[[Reference]]. אם אין כלום, לא ממלאים. לוחצים [[OK]] וחוזרים לדוקט.","shot":"חלון האישור עם השדות [[Confirmed with]] ו-[[Reference]] והכפתור [[OK]]."},{"title":"בודקים שהאישור נקלט","text":"נכנסים שוב לעיפרון ← [[Reservation]]. אם נשארה רק אפשרות ביטול, ההזמנה אושרה. אם עדיין יש [[Report and Confirm]], היא לא אושרה.","why":"מבחוץ אין סימן לכך שהאישור הצליח.","trap":"כאן מופיע [[Cancel, Report and Confirm]]. לא ללחוץ עליו!","shot":"לשונית Reservation של הזמנה שכבר אושרה: רק אפשרות הביטול. לסמן אותה באדום עם הכיתוב ״לא ללחוץ״."},{"title":"גם הירוקות","text":"חוזרים על השלבים לכל הזמנה מתוך המערכת, שורה אחרי שורה, גם אם יש לה V ירוק.","why":"V ירוק אומר שיש מקום בהקצאה, אבל עדיין צריך לדווח לספק שהמקום נמכר.","trap":"מורים ותיקים אישרו רק את הלא-ירוקים. לפי ההשתלמות זו טעות.","shot":"דוקט שבו כל שורות המערכת מאושרות.","verify":"סתירה במקורות: ב״שלבי עבודה״ של ירון (בחוברת) כתוב ״לאשר רק הזמנות ללא V ירוק בשלב זה״, ובחוברת כתוב ש-V ירוק = מהקצאה ועדיין לא דווח. בהשתלמות (מפגשים 2 ו-9) ירון אומר במפורש שגם ירוקות חייבים לאשר. ייתכן שהכוונה בחוברת היא רק לשלב הראשון (לפני שינויים). לוודא מול המורה ולבדוק במערכת: להיכנס לעיפרון של הזמנה ירוקה ולראות אם עדיין מופיע Report and Confirm."},{"title":"שורות בין הרים","text":"הזמנות מבין הרים (Add Manual Service, סטטוס OK) לא צריך לדווח. מי שמאשר גם אותן לא טועה, זו רק פעולה מיותרת.","shot":"דוקט עם שורת בין הרים ושורות מהמערכת. לסמן את שורת בין הרים עם הכיתוב ״לא צריך דיווח״."},{"title":"מאשרים לפני ״כמה לשלם?״","text":"לפני שעונים על שאלה כמו ״מה היתרה בדוקט?״ או ״כמה צריך לשלם?״, מוודאים שכל ההזמנות מהמערכת אושרו.","why":"הזמנה לא מאושרת (סימן שאלה) לא נכללת בסך מחיר הדוקט.","shot":"ראש הדוקט עם היתרה והסך הכולל. לסמן את שני המספרים."}],"oral":[{"q":"למה מאשרים רק הזמנות מתוך המערכת?","a":"הן מבוססות על הקצאה, וצריך לדווח לספק שנוצל מקום. הזמנות מבין הרים נעשו במערכת של הספק, והוא כבר יודע עליהן."},{"q":"להזמנה יש V ירוק. האם צריך לאשר אותה?","a":"כן. V ירוק אומר שיש מקום בהקצאה, אבל עדיין צריך לדווח לספק שהחדר נמכר."},{"q":"איך יודעים אם הזמנה כבר אושרה?","a":"נכנסים לעיפרון ← Reservation. אם נשארה רק אפשרות ביטול, היא אושרה. מבחוץ אי אפשר לדעת."},{"q":"מה פירוש סימן שאלה כחול?","a":"Request: נגמרה ההקצאה, וההזמנה עדיין ממתינה לאישור. אחרי Report and Confirm הסטטוס הופך ל-OK."},{"q":"מה ההבדל בין Allocation ל-Free Sale?","a":"Allocation = הקצאה מהספק, מזמינים מתוך המערכת ומדווחים לספק. Free Sale = מזמינים אצל הספק עצמו (בין הרים), וטרוול בוסטר רק רושמת."},{"q":"למה חשוב לאשר לפני שעונים כמה הלקוח צריך לשלם?","a":"כי הזמנה שלא אושרה לא נספרת ביתרת הדוקט, והסכום ייצא נמוך מדי."}],"check":["כל שורה שהוזמנה מתוך המערכת אושרה, כולל ירוקות","בעיפרון ← Reservation של כל שורה כזו נשארה רק אפשרות ביטול","שם המאשר או מספר ההזמנה הוזנו אם השאלה נתנה אותם","אף הזמנה לא בוטלה בטעות (אין X אדום שלא התבקש)","שורות בין הרים בסטטוס OK"],"sources":["TB_master §1, §6","00_docs_summary: אישור ודיווח הזמנות מתוך המערכת; שלבי עבודה (ירון)","hishtalmut_01 §2 (Allocation / Free Sale), §8 (סטטוסים)","hishtalmut_02 §9, §11","hishtalmut_04 חלק א׳ (אישור הזמנות)","hishtalmut_09 §2 (בדיקת אישור), §5 (מלכודת ביטול בטעות)","video_galor_01 (סטטוסים)"],"record":"docket"},{"id":"fit-amend","track":"FIT","order":11,"icon":"✏️","title":"שינויים בהזמנת מלון","goal":"לשנות הזמנת מלון קיימת: תאריכים, בסיס אירוח או סוג חדר, בלי לאבד את בסיס האירוח ובלי להיתקע בתשלום.","why":"שינויים הם חלק מ-15 הנקודות של שינויים ומסמכים. המורה רואה בהיסטוריה את ההזמנה הישנה ואת החדשה, ולכן חשוב לשנות דרך Amend ולא להמציא דרך אחרת.","before":[{"term":"Amend Reservation","text":"שינוי הזמנה קיימת. נמצא בתפריט ההמבורגר (שלושת הפסים) של שורת המלון, ובו שלוש אפשרויות: Change Dates, Change board basis, Change room type."},{"term":"אמצעי תשלום","text":"בכל שינוי, כמו בהזמנה הראשונה, מחליפים את אמצעי התשלום מכרטיס אשראי לאפשרות אחרת. בלי זה המערכת לא מתקדמת."},{"term":"לפני מסמכים","text":"בבחינה עושים שינויים לפני שוברים. אם כבר הופקו שובר, חשבונית או קבלה, קודם מבטלים אותם."},{"term":"Revision","text":"המורה בודק שינוי דרך העיפרון ← Revision (רואים את ההזמנה הישנה מחוקה), או דרך ההמבורגר ← Reservation History."}],"steps":[{"title":"בודקים שאין מסמכים","text":"בודקים בחלק [[Accounting]] ובשורת המלון שלא הופקו שובר, חשבונית או קבלה. אם הופקו: קודם מבטלים אותם. שובר מבטלים דרך ההמבורגר ← [[Cancel Voucher]].","why":"אחרי שובר המערכת לא מאפשרת לשנות או לבטל את ההזמנה.","shot":"שורת מלון עם מספר שובר לידה, ותפריט ההמבורגר פתוח עם [[Cancel Voucher]] מסומן.","verify":"איך מבטלים חשבונית וקבלה שכבר הופקו ב-FIT (המקורות אומרים רק ״קודם לבטל אותן״, בלי מסלול לחיצות)."},{"title":"פותחים Amend Reservation","text":"בשורת המלון לוחצים על ההמבורגר. מעבירים את העכבר מעל [[Amend Reservation]], ומשם זזים לצד, בקו ישר, אל התפריט המשני שנפתח.","shot":"תפריט ההמבורגר פתוח, העכבר על [[Amend Reservation]], והתפריט המשני עם שלוש האפשרויות. לסמן את שלושתן.","verify":"התנהגות התפריט (ריחוף ומעבר אופקי לתפריט המשני) לא מופיעה במקורות הכתובים. לבדוק במערכת ולצלם."},{"title":"שינוי תאריכים","text":"בוחרים [[Change Dates]]. משנים את תאריכי ה-From/To או את מספר הלילות לפי השאלה (למשל מגיעים יום אחד מאוחר יותר ועוזבים באותו יום, כלומר לילה אחד פחות). המערכת מחשבת מחיר מחדש.","shot":"מסך Change Dates עם התאריכים החדשים ממולאים. לסמן את השדות ואת הכפתור שמחשב מחדש.","verify":"שם הכפתור שמחשב מחדש במסך Change Dates (בחוברת Save, בהשתלמות ״חיפוש״ עם סימן שאלה)."},{"title":"תשלום ו-Confirm","text":"במסך האישור מחליפים את אמצעי התשלום מכרטיס אשראי ל-[[Request other payment method]], ולוחצים [[Confirm]]. עושים את זה בסוף כל אחד מסוגי השינוי.","trap":"בלי החלפת אמצעי התשלום המערכת לא נותנת להתקדם.","shot":"מסך האישור של השינוי, עם אמצעי התשלום החלופי מסומן ו-[[Confirm]]."},{"title":"שינוי בסיס אירוח","text":"בוחרים [[Change board basis]]. מזיזים את הנקודה לבסיס הרצוי (למשל מ-BB ל-HB). המחיר משתנה. לוחצים [[OK]], ואז אמצעי תשלום ו-[[Confirm]] כמו בשלב הקודם.","shot":"מסך Change board basis עם רשימת הבסיסים והתוספות. לסמן את הבסיס החדש ואת המחיר."},{"title":"שינוי סוג חדר","text":"בוחרים [[Change room type]] ובוחרים את סוג החדר החדש שבשאלה.","shot":"מסך Change room type עם רשימת סוגי החדרים. לסמן את הסוג החדש."},{"title":"מחזירים את בסיס האירוח","text":"במסך סוג החדר, בסיס האירוח חוזר לבד ל-BB. משנים אותו בחזרה לבסיס שהיה קודם (למשל [[Half Board]]), ורק אז לוחצים [[Proceed]], אמצעי תשלום ו-[[Confirm]].","trap":"אם לא מחזירים, ההפרש במחיר יוצא שגוי (בהשתלמות: מינוס 600 דולר), והנוסעים מאבדים את החצי פנסיון.","shot":"מסך סוג החדר עם בסיס האירוח מסומן באדום (חזר ל-BB), ולצידו אותו מסך אחרי ההחזרה ל-HB."},{"title":"בודקים את השורה","text":"בדוקט בודקים בשורת המלון: תאריכים, מספר לילות, סוג חדר, בסיס אירוח ומחיר.","trap":"אם המחיר לא הגיוני ולא מוצאים למה, ההמלצה בהשתלמות: לבטל את שורת המלון ולהזמין אותה מחדש, ולספר לבוחן.","shot":"שורת המלון בדוקט אחרי השינוי. לסמן את הלילות, סוג החדר ובסיס האירוח."}],"oral":[{"q":"אילו שינויים אפשר לעשות בהזמנת מלון דרך Amend Reservation?","a":"שינוי תאריכים (Change Dates), שינוי בסיס אירוח (Change board basis) ושינוי סוג חדר (Change room type)."},{"q":"מה המלכודת בשינוי סוג חדר?","a":"בסיס האירוח חוזר לבד ל-BB. צריך להחזיר אותו לבסיס הקודם, אחרת המחיר וההזמנה שגויים."},{"q":"למה לא מצליחים לשנות הזמנה שכבר יש לה שובר?","a":"שובר הוא התחייבות לספק. קודם מבטלים את השובר (Cancel Voucher), ורק אז משנים."},{"q":"איך המורה יודע שבאמת שיניתם את ההזמנה?","a":"בעיפרון ← Revision רואים את ההזמנה הישנה מחוקה ואת החדשה, או בהמבורגר ← Reservation History."}],"check":["השינוי נעשה דרך ההמבורגר ← Amend Reservation","בכל שינוי הוחלף אמצעי התשלום ונלחץ Confirm","אחרי שינוי סוג חדר, בסיס האירוח הוא הבסיס הנכון ולא BB","שורת המלון מציגה את התאריכים, הלילות, סוג החדר ובסיס האירוח שבשאלה","השינויים נעשו לפני הפקת שוברים"],"sources":["TB_master §6","00_docs_summary: שינוי (Amend Reservation)","hishtalmut_02 §8, §12 (ביטול אחרי שובר)","hishtalmut_04 חלק א׳ (ביטולים ושינויים)","hishtalmut_09 §2 (Revision, Reservation History, ביטול והזמנה מחדש)","הנחיית המשימה: ריחוף על Amend Reservation ומעבר אופקי לתפריט המשני (לא במקורות — סומן verify)"],"record":"docket"},{"id":"fit-cancel","track":"FIT","order":12,"icon":"❌","title":"ביטולים","goal":"לבטל שירות בדרך הנכונה לפי המצב שלו (לפני אישור, אחרי אישור, בין הרים, אחרי שובר), כך שיישאר X אדום גלוי בדוקט.","why":"בבחינה הביטול חייב להישאר גלוי (X אדום), כדי שהבוחן יראה שבוצע. Delete מוחק את השורה, וכך הבוחן לא רואה ביטול בכלל.","before":[{"term":"Cancel Reservation","text":"ביטול הזמנה. השורה נשארת בדוקט עם X אדום. זו הדרך בבחינה."},{"term":"Delete Transaction","text":"מוחק את השורה לגמרי. רק לתיקון טעות תוך כדי עבודה, לא לביטול שהתבקש בשאלה."},{"term":"Request for Cancellation","text":"עיגול כתום עם שלוש נקודות: ההזמנה בוטלה בדוקט, אבל הביטול עוד לא דווח לספק."},{"term":"Cancellation Confirmed","text":"סטטוס של ביטול שאושר. בבין הרים משנים את הסטטוס לזה בעצמנו, כי הביטול נעשה אצל הספק."}],"steps":[{"title":"מזהים את המצב","text":"לפני שמבטלים בודקים: האם השירות מתוך המערכת או מבין הרים? האם כבר אושר? (עיפרון ← [[Reservation]]: אם נשארה רק אפשרות ביטול, הוא אושר.) האם כבר הופק לו שובר?","why":"לכל מצב יש דרך ביטול אחרת.","shot":"דוקט עם שורות מסוגים שונים: מהמערכת, מבין הרים ועם מספר שובר. לסמן כל סוג."},{"title":"מהמערכת, לפני אישור","text":"בשורת ההזמנה לוחצים על ההמבורגר ← [[Cancel Reservation]] ← מאשרים. בשורה מופיע X אדום.","trap":"לא [[Delete Transaction]]. בבחינה הביטול צריך להישאר גלוי.","shot":"תפריט ההמבורגר פתוח. לסמן את [[Cancel Reservation]] בירוק ואת [[Delete Transaction]] באדום."},{"title":"מהמערכת, אחרי אישור","text":"עיפרון ← [[Reservation]] ← [[Cancel, Report and Confirm]]. מתקבל X אדום מיד, והביטול כבר דווח לספק.","trap":"אחרי אישור לא מבטלים מההמבורגר. אם ניסיתם וקיבלתם הודעה שההזמנה כבר דווחה למלון, לא ללחוץ OK. סוגרים (Back) ומבטלים דרך העיפרון.","shot":"לשונית Reservation של הזמנה מאושרת. לסמן את [[Cancel, Report and Confirm]].","verify":"סתירה במקורות: בחוברת הביטול אחרי אישור הוא תמיד בשני שלבים (Report Cancellation ואז Confirm Cancellation). בהשתלמות ירון מלמד Cancel, Report and Confirm בלחיצה אחת, ושני שלבים רק במקרה של עיגול כתום. לבדוק במערכת שהכפתור קיים ומוביל ל-X אדום."},{"title":"עיגול כתום: שלב 1","text":"אם בטעות לחצתם OK על הודעת השגיאה בהמבורגר, מופיע עיגול כתום (Request for Cancellation). נכנסים לעיפרון ← [[Reservation]] ← [[Report Cancellation]] ← [[Back to Travel File]].","shot":"שורה עם עיגול כתום, ולשונית Reservation עם [[Report Cancellation]] מסומן."},{"title":"עיגול כתום: שלב 2","text":"שוב עיפרון ← [[Reservation]] ← [[Confirm Cancellation]]. אם יש שם או מספר ביטול בשאלה, מזינים אותם ← [[OK]]. מתקבל X אדום. אם עדיין כתום, חוזרים על התהליך.","why":"ביטול הוא פעולה רגישה, ולכן המערכת דורשת שני שלבים.","shot":"לשונית Reservation עם [[Confirm Cancellation]] מסומן, ואחר כך השורה עם X אדום."},{"title":"שירות מבין הרים","text":"בהמבורגר של שורת בין הרים אין Cancel Reservation. נכנסים לעיפרון, משנים את הסטטוס ל-[[Cancellation Confirmed]] ולוחצים [[Save & Exit]]. מתקבל X אדום.","why":"את ההזמנה עשינו אצל הספק, ולכן גם הביטול נעשה שם. בטרוול בוסטר רק מעדכנים את הרישום. בבחינה לא מבטלים באמת באתר.","trap":"לא Delete מההמבורגר.","shot":"טופס העריכה של שירות ידני, עם שדה הסטטוס פתוח ו-[[Cancellation Confirmed]] מסומן."},{"title":"אחרי שובר","text":"אם לשירות כבר יש שובר: קודם בהמבורגר ← [[Cancel Voucher]]. רק אחר כך מבטלים לפי סוג השירות (השלבים למעלה).","why":"אחרי שובר Cancel Reservation נותן הודעת שגיאה. בבחינה עושים ביטולים לפני השוברים, אז זה רק לתיקון טעות.","shot":"תפריט ההמבורגר של שורה עם שובר. לסמן את [[Cancel Voucher]]."},{"title":"בודקים X אדום","text":"בודקים שבכל שורה שבוטלה מופיע X אדום, ושאף שורה לא נמחקה. המורה יכול לראות מה נעשה דרך העיפרון ← [[Revision]], או ההמבורגר ← [[Reservation History]].","shot":"הדוקט עם שורה מבוטלת (X אדום) לצד שורות מאושרות. לסמן את ה-X."}],"oral":[{"q":"מה ההבדל בין Cancel Reservation ל-Delete Transaction?","a":"Cancel Reservation מבטל, והשורה נשארת עם X אדום. Delete Transaction מוחק את השורה לגמרי, ומשתמשים בו רק לתיקון טעות."},{"q":"איך מבטלים סיור מבין הרים?","a":"בעיפרון משנים סטטוס ל-Cancellation Confirmed ו-Save & Exit. הביטול עצמו נעשה אצל הספק, ואצלנו רק מעדכנים את הרישום."},{"q":"מה פירוש עיגול כתום עם שלוש נקודות?","a":"Request for Cancellation: ההזמנה בוטלה בדוקט אבל הביטול עוד לא דווח לספק. מטפלים בשני שלבים: Report Cancellation ואז Confirm Cancellation."},{"q":"למה אי אפשר לבטל הזמנה שכבר יש לה שובר?","a":"השובר הוא התחייבות לספק. קודם מבטלים את השובר (Cancel Voucher), ורק אחר כך את ההזמנה."}],"check":["כל שירות שהשאלה ביקשה לבטל מופיע עם X אדום","אף שורה לא נמחקה ב-Delete Transaction","אין שורה שנשארה בעיגול כתום","שירות מבין הרים בוטל בשינוי סטטוס ל-Cancellation Confirmed","שום שירות לא בוטל בטעות"],"sources":["TB_master §6","00_docs_summary: ביטול","hishtalmut_02 §7, §10, §12 (ביטול אחרי שובר)","hishtalmut_04 חלק א׳ (ביטולים ושינויים)","hishtalmut_09 §2 (Revision, Reservation History), §5 (מלכודת ביטול בטעות)"],"record":"docket"},{"id":"fit-accounting","track":"FIT","order":13,"icon":"🧾","title":"חשבונית, שוברים, קבלה ורווח","goal":"להפיק בדוקט FIT חשבונית, שוברים וקבלה, לראות את הרווח, ולסיים עם יתרה 0.","why":"שלוש הפעולות האלה פשוטות מאוד ונותנות נקודות. גם מי שלא הספיק למלא את כל הדוקט צריך להפיק אותן, חבל להפסיד.","before":[{"term":"Invoice","text":"חשבונית: רשימת כל השירותים והמחירים, כמו ״חשבון בבקשה״ במסעדה. ב-FIT (בלי סוכן) היא רישומית בלבד: מופיעה בשחור ולא משנה את היתרה."},{"term":"Voucher","text":"שובר: התחייבות לשלם לספק, כמו צ׳ק דחוי. המערכת מפיקה את כל השוברים יחד. הדוקט עובר ליתרת חובה, ומופיע הרווח (Profit). T = שובר תחבורה, V = כל השאר."},{"term":"Receipt","text":"קבלה: קיבלנו כסף מהנוסע. מופיעה בירוק, והיתרה חוזרת ל-0."},{"term":"יתרה 0","text":"בדוקט FIT, בלי סוכן ובלי אשראי, היתרה בסוף צריכה להיות 0. זה אחד הסימנים שהדוקט מסודר. הרווח שלנו הוא העמלה מהספק."}],"steps":[{"title":"קודם מסיימים שירותים","text":"לפני המסמכים: כל השינויים והביטולים בוצעו, וכל ההזמנות מתוך המערכת אושרו.","why":"אחרי שובר אי אפשר לשנות או לבטל בלי לבטל קודם את השובר. והזמנה לא מאושרת לא נספרת ביתרה.","shot":"דוקט מוכן: כל השורות מאושרות או מבוטלות. לסמן את עמודת הסטטוס."},{"title":"יורדים ל-Accounting","text":"גוללים לתחתית הדוקט, לחלק [[Accounting]]. שם הכפתורים [[Invoice]], [[Receipt]], [[Ticket/Voucher]] ו-[[Profit]].","shot":"חלק Accounting בתחתית הדוקט. לסמן את ארבעת הכפתורים.","verify":"הכיתוב על כפתור השוברים: Ticket/Voucher (חוברת) או Voucher (השתלמות)."},{"title":"חשבונית","text":"לוחצים [[Invoice]]. מתקבל מספר חשבונית. לוחצים [[Back to Travel File]].","why":"בסדר הרגיל החשבונית באה ראשונה: זו רשימת הפריטים והמחירים שמציגים לנוסע.","trap":"אם החשבונית כבר הופקה, המערכת לא מאפשרת להפיק שוב.","shot":"מסך החשבונית עם המספר שלה, והכפתור [[Back to Travel File]] מסומן."},{"title":"בודקים: שחור, בלי שינוי","text":"בחלק Accounting מופיעה שורת החשבונית בשחור. היתרה בראש הדוקט לא השתנתה.","shot":"שורת החשבונית בשחור ב-Accounting, ולצידה היתרה בראש הדוקט.","verify":"בהדרכת גלאור (מפגש 1) נאמר שחשבונית מס מופיעה באדום ושמסמך שחור הוא חשבונית עסקה. בהשתלמות ובחוברת: ב-FIT החשבונית שחורה. לבדוק את הצבע ואת סוג החשבונית בדוקט FIT."},{"title":"שוברים: כולם יחד","text":"לוחצים [[Ticket/Voucher]]. מופיע השובר הראשון. אפשר לדפדף ב-[[Show next voucher]], אבל אין צורך. לוחצים [[Back to Travel File]].","why":"המערכת מפיקה בבת אחת את כל השוברים, לכל שירות שלא בוטל.","shot":"מסך השובר הראשון, עם [[Show next voucher]] ו-[[Back to Travel File]] מסומנים."},{"title":"בודקים את השוברים","text":"ליד כל שירות שלא בוטל מופיע מספר שובר: T להעברות (תחבורה), V לכל השאר. היתרה בראש הדוקט עברה לחובה (אדום), ומופיע [[Profit]].","why":"הפקת שוברים היא ביצוע המכירה. רק עכשיו מופיעים העלות הכוללת והרווח.","shot":"רשימת השירותים עם מספרי השוברים. לסמן שובר T ושובר V, ואת היתרה האדומה בראש הדוקט."},{"title":"קבלה","text":"לוחצים [[Receipt]]. ב-[[Amount]] משאירים את הסכום (משנים רק אם השאלה מבקשת תשלום חלקי). משנים את אמצעי התשלום ל-[[Cash]] ולוחצים [[Generate Receipt]]. מתקבל מספר קבלה ← [[Back to Travel File]].","shot":"מסך הקבלה. לסמן את [[Amount]], [[Cash]] ו-[[Generate Receipt]]."},{"title":"בודקים: ירוק ו-0","text":"שורת הקבלה מופיעה ב-Accounting בירוק, והיתרה בראש הדוקט חזרה ל-0.","trap":"אם היתרה לא 0: בדקו שלא שיניתם את הסכום בטעות, ושכל ההזמנות אושרו לפני השוברים.","shot":"ראש הדוקט עם יתרה 0, ושורת הקבלה הירוקה ב-Accounting."},{"title":"חלון הרווח","text":"לוחצים [[Profit]]. רואים את העלות של כל שירות, את סך העלויות ואת הרווח. את הרווח רואים גם בראש הדוקט.","shot":"חלון Profit. לסמן את סך העלויות ואת הרווח.","verify":"מה בדיוק מוצג בחלון Profit בדוקט FIT. התיאור המפורט במקורות (Actual Profit, %, Selling Price, Net) הוא מדוקט קבוצתי."},{"title":"פותחים מסמך","text":"כדי לראות מסמך, לוחצים על המספר שלו: מספר החשבונית, מספר הקבלה או מספר השובר.","shot":"מספר חשבונית ב-Accounting מסומן, והמסמך שנפתח."}],"oral":[{"q":"מה ההבדל בין Invoice, Voucher ו-Receipt?","a":"Invoice = רשימת השירותים והמחירים, ב-FIT לא משנה את היתרה (שחור). Voucher = התחייבות לספק, היתרה עוברת לחובה. Receipt = קיבלנו כסף מהנוסע, היתרה חוזרת ל-0 (ירוק)."},{"q":"מה ההבדל בין שובר T לשובר V?","a":"T הוא שובר תחבורה (העברות). V הוא שובר לכל שאר השירותים."},{"q":"למה היתרה בדוקט FIT צריכה להיות 0 בסוף?","a":"כי הלקוח פרטי, בלי סוכן ובלי אשראי. הוא משלם את כל הסכום, והרווח שלנו הוא העמלה מהספק."},{"q":"איפה רואים את הרווח?","a":"בראש הדוקט, ובחלון Profit בחלק Accounting. הוא מופיע רק אחרי הפקת השוברים."},{"q":"למה אחרי השוברים היתרה אדומה?","a":"כי השובר הוא התחייבות לשלם לספק. כאילו הוצאנו כסף מהכיס, ועוד לא קיבלנו מהנוסע."}],"check":["יש חשבונית אחת, בשחור","לכל שירות שלא בוטל יש מספר שובר (T או V)","יש קבלה בירוק, באמצעי תשלום Cash","היתרה בראש הדוקט היא 0","יודעים להראות לבוחן את הרווח בראש הדוקט ובחלון Profit"],"sources":["TB_master §3, §7","00_docs_summary: הפקת מסמכים (FIT); מבנה הדוקט","hishtalmut_02 §11–§12","hishtalmut_04 חלק א׳ (החלק החשבונאי בדוקט בודדים)","video_galor_01 §3, §10 (שובר, קונבנציית צבעים)"],"record":"docket"},{"id":"fit-documents","track":"FIT","order":14,"icon":"📧","title":"מסמכים ללקוח","goal":"לשלוח במייל Itinerary (אישור הזמנה בלי מחירים) ו-Travel File Details (פירוט עם מחירים), רק עם השירותים שבאמת קיימים.","why":"שליחת המסמכים היא חלק מ-15 הנקודות של שינויים ומסמכים, ודרכם המורה והבוחן בודקים את הדוקט כולו: סכומים, העברות, סוגי חדרים ותאריכים.","before":[{"term":"Itinerary","text":"אישור הזמנה לנוסע, בלי מחירים. מופיעים בו רק שמות הנוסעים והשירותים המאושרים. שירות מבוטל או לא מאושר לא מופיע."},{"term":"Travel File Details","text":"פירוט הדוקט עם מחירים. מופיעים בו כל השירותים, גם המבוטלים, ולכן מורידים את ה-V מהמבוטלים לפני שליחה."},{"term":"Send Page","text":"כפתור השליחה (מעטפה). מקלידים כתובת מייל ולוחצים Send. בלי מייל אי אפשר לשלוח."},{"term":"לאיזו כתובת?","text":"אף פעם לא שולחים לכתובת אמיתית בלי הנחיה של המורה. בתרגול: לכתובת שהמורה נתן (למשל לעצמכם). בבחינה: לכתובת שהבוחן נותן."}],"steps":[{"title":"קודם הדוקט מוכן","text":"לפני השליחה: כל השינויים והביטולים בוצעו, וכל ההזמנות מתוך המערכת אושרו.","why":"ב-Itinerary מופיעים רק שירותים מאושרים. שירות שלא אושר פשוט ייעלם מהמסמך.","shot":"הדוקט עם כל השורות מאושרות או מבוטלות. לסמן את עמודת הסטטוס."},{"title":"פותחים Itinerary","text":"בראש הדוקט לוחצים [[Itinerary]]. בודקים שמופיעים שמות הנוסעים וכל השירותים המאושרים, ושאין מחירים.","shot":"הכפתור [[Itinerary]] בראש הדוקט, ומסמך ה-Itinerary שנפתח. לסמן את רשימת השירותים."},{"title":"שולחים את ה-Itinerary","text":"לוחצים [[Send Page]] (המעטפה), מקלידים את הכתובת שהמורה או הבוחן נתנו, ולוחצים [[Send]].","trap":"לא שולחים לכתובת אמיתית של לקוח או של מישהו אחר בלי הנחיה של המורה.","shot":"חלון Send Page עם שדה המייל. לסמן את השדה ואת [[Send]]."},{"title":"פותחים Travel File Details","text":"פותחים את [[Travel File Details]]. המסמך נטען לאט. מופיעים בו כל השירותים עם המחירים, גם המבוטלים.","shot":"מסך Travel File Details עם רשימת השירותים והמחירים.","verify":"מאיפה פותחים את Travel File Details בדוקט FIT (איזה כפתור או תפריט). המקורות לא מציינים."},{"title":"מורידים V ממבוטלים","text":"ליד כל שירות שבוטל (X אדום בדוקט) מורידים את ה-V, כדי שיישארו במסמך רק השירותים המאושרים.","trap":"אם שוכחים, הלקוח מקבל פירוט עם שירות שבוטל ועם המחיר שלו.","shot":"רשימת השירותים ב-Travel File Details. לסמן שירות מבוטל שה-V שלו הוסר."},{"title":"שולחים את ה-Travel File Details","text":"לוחצים [[Send Page]], מקלידים את הכתובת שהמורה או הבוחן נתנו, ולוחצים [[Send]]. חוזרים לדוקט.","shot":"חלון Send Page של Travel File Details עם [[Send]] מסומן."},{"title":"שם ומספר דוקט בנושא","text":"בתרגול, כשהמורה מבקש לשלוח לו: כותבים בנושא המייל את השם שלכם ואת מספר הדוקט.","why":"המורה מקבל 20 מיילים כאלה, וצריך לדעת ממי הגיע כל אחד.","shot":"חלון השליחה עם שדה הנושא, אם קיים. לסמן אותו.","verify":"האם בחלון Send Page יש שדה נושא (Subject) שאפשר לערוך."}],"oral":[{"q":"מה ההבדל בין Itinerary ל-Travel File Details?","a":"Itinerary הוא אישור הזמנה בלי מחירים, ומופיעים בו רק שירותים מאושרים. Travel File Details כולל מחירים ואת כל השירותים, גם המבוטלים, ולכן מורידים מהם את ה-V."},{"q":"שירות שבוטל מופיע ב-Itinerary?","a":"לא. ב-Itinerary מופיעים רק שירותים בסטטוס מאושר."},{"q":"איך שולחים מסמך במייל מתוך הדוקט?","a":"Send Page (המעטפה), מקלידים כתובת מייל, ולוחצים Send."}],"check":["ה-Itinerary נשלח לכתובת שהמורה או הבוחן נתנו","ב-Itinerary מופיעים כל השירותים המאושרים, ואין שירות מבוטל","ב-Travel File Details הוסר ה-V מכל שירות מבוטל","ה-Travel File Details נשלח לכתובת שהמורה או הבוחן נתנו","לא נשלח שום מייל לכתובת אמיתית בלי הנחיה"],"sources":["TB_master §7","00_docs_summary: הפקת מסמכים (FIT); מבנה הבחינה (מייל בוחן)","hishtalmut_02 §13","hishtalmut_06 (הגשה: מספר דוקט ושם)","hishtalmut_09 §1 (הדפסת Travel File Details), §6 (טוען לאט)","הנחיית המשימה: לא לשלוח לכתובת אמיתית בלי הנחיית המורה"],"record":"docket"},{"id":"grp-info","track":"GRP","order":1,"icon":"📝","title":"הצעת מחיר — פרטי הקבוצה","goal":"לפתוח הצעת מחיר חדשה לקבוצה, למלא שם, סוכן ואנשי צוות, ולשמור עם מספר הצעה.","why":"בקבוצה לא מזמינים מיד. קודם בונים הצעת מחיר לסוכן, ורק אחרי שהוא מאשר פותחים דוקט. טעות בסוכן כאן משבשת את כל החשבונאות בסוף.","before":[{"term":"Calculation Sheet","text":"הצעת המחיר לקבוצה. בונים בה את כל הטיול, והמערכת מחשבת מחיר לאדם לכמה גדלי קבוצה."},{"term":"Agent","text":"בקבוצה תמיד יש סוכן נסיעות. סוכן ירוק = יש לו אשראי. סוכן אדום = אין לו אשראי וצריך לשלם מיד. עובדים רק עם ירוק."},{"term":"Staff","text":"אנשי צוות שהקבוצה צריכה: נהג, מדריך מלווה, טבח, מורים מלווים. העלות שלהם מתחלקת בין כל המשתתפים."},{"term":"Free","text":"נוסע חופשי: הטבה שמארגן הקבוצה מבקש לעצמו. זה לא איש צוות, ומגדירים אותו במקום אחר (ביחידה הבאה)."},{"term":"Net","text":"בקבוצה המחירים מהספקים הם נטו, ואנחנו מוסיפים את הרווח (Markup). ב-FIT זה הפוך: ברוטו ועמלה מהספק."}],"steps":[{"title":"קוראים את כל השאלה","text":"מסמנים בשאלה: שם הקבוצה, הסוכן, כמה אנשי צוות ואיך הם ישנים, גדלי הקבוצה והחופשיים, תאריכים, ואת כל השירותים לפי ימים. כדאי לעבוד עם מרקר, כמו צ'קליסט.","why":"בהצעה קבוצתית יש הרבה פרטים קטנים, והסיכוי לטעות גבוה יותר מאשר ב-FIT.","shot":"אין צילום מסך — דף השאלה עם סימוני מרקר (אפשר תמונה של דף לדוגמה)."},{"title":"פותחים הצעה חדשה","text":"בתפריט העליון: [[Tools]] ואז [[Calculation Sheet]]. לוחצים [[Click here to add a new calculation sheet]].","shot":"תפריט Tools פתוח עם Calculation Sheet מסומן; ואחריו המסך עם הקישור Click here to add a new calculation sheet מסומן."},{"title":"שם הקבוצה","text":"בלשונית [[Information]] מקלידים ב-[[Group Name]] את שם הקבוצה מהשאלה, באנגלית.","shot":"לשונית Information, שדה Group Name מסומן."},{"title":"השדה For","text":"בשדה [[For]] כותבים את השם שלכם.","why":"כך המורה או הבוחן יודעים של מי ההצעה.","shot":"לשונית Information, שדה For מסומן.","verify":"המקורות סותרים מה כותבים ב-For: TB_master ו-hishtalmut_09 — שם התלמיד; 00_docs_summary — שם הסוכן; hishtalmut_06 — שם איש הקשר של הסוכן. לבדוק במערכת אם יש שדה נפרד לאיש קשר, ומה החוברת מבקשת."},{"title":"סוכן ירוק בלבד","text":"ב-[[Agent]] פותחים את הרשימה ובוחרים את הסוכן מהשאלה (למשל [[ABC Tours]]). מוודאים שהוא מסומן בירוק.","why":"סוכן ירוק = סוכן עם אשראי. זה מה שקובע איך החשבונית והקבלה יתנהגו בדוקט בסוף.","trap":"סוכן אדום יוצר בלגן בחשבונאות. אם כבר נפתח דוקט עם סוכן אדום, אין תיקון: עדכון סוכן בדוקט קיים לא עובד, וצריך להתחיל מחדש.","shot":"רשימת הסוכנים פתוחה, עם סוכן ירוק וסוכן אדום זה ליד זה; הסוכן הירוק מסומן."},{"title":"אנשי צוות: יחיד או זוגי","text":"ב-[[Staff in Single]] מקלידים כמה אנשי צוות ישנים בחדר יחיד, וב-[[Staff in Double]] כמה ישנים בחדר זוגי. בדוגמה שלנו כל הצוות ביחיד: למשל 2 ב-[[Staff in Single]] ו-0 ב-[[Staff in Double]].","why":"המערכת צריכה את הצוות כדי לתמחר את המלונות שלהם ולחלק את העלות בין המשתתפים.","trap":"לא לבלבל צוות עם חופשיים. החופשיים לא נכנסים כאן.","shot":"שדות Staff in Single ו-Staff in Double מסומנים, עם 2 ו-0."},{"title":"שומרים","text":"לוחצים [[Save]].","why":"שומרים אחרי כל שלב. אם המערכת מתנתקת, מה שנשמר לא נעלם.","shot":"כפתור Save מסומן בלשונית Information."},{"title":"רושמים את מספר ההצעה","text":"בשמירה הראשונה מופיע מספר הצעה ([[Sheet Number]]). רושמים אותו מיד על הדף.","why":"בלי המספר קשה למצוא את ההצעה אחרי ניתוק או בשיעור הבא.","shot":"מספר ההצעה שמופיע אחרי השמירה, מסומן."}],"oral":[{"q":"מה ההבדל בין סוכן ירוק לסוכן אדום?","a":"לסוכן ירוק יש אשראי: יש לו בטחונות והוא משלם לפי הסכם תקופתי. לסוכן אדום אין אשראי, והוא משלם מיד."},{"q":"מי נחשב איש צוות (Staff)?","a":"מי שהקבוצה צריכה כדי שהטיול יתקיים: נהג, מדריך מלווה, טבח, איש אקדמיה, מורים מלווים. העלות שלהם מתחלקת בין המשתתפים."},{"q":"למה בקבוצה עושים קודם הצעת מחיר, וב-FIT מזמינים מיד?","a":"ב-FIT הנוסע מקבל מחיר ומזמינים מיד. בקבוצה הסוכן עוד לא יודע כמה ימכור, ולכן מבקש הצעה לכמה גדלים. רק כשהוא מחליט פותחים דוקט."},{"q":"מה ההבדל בין ברוטו לנטו?","a":"ברוטו: הספק נותן מחיר ואנחנו מקבלים ממנו עמלה (FIT). נטו: הספק נותן מחיר נטו ואנחנו מוסיפים רווח (Markup) בעצמנו (קבוצות)."}],"check":["שם הקבוצה כתוב כמו בשאלה","הסוכן שנבחר מסומן בירוק","מספר אנשי הצוות ביחיד ובזוגי תואם לשאלה","לחצתם Save","מספר ההצעה רשום על הדף"],"sources":["TB_master §1, §8","00_docs_summary: קבוצות — הצעת מחיר","hishtalmut_04 חלק ב׳, חלק ג׳ לשונית 1","hishtalmut_06 §4.2, §6, §7 שלב א","hishtalmut_09 §3 שלב 1"],"record":"proposal"},{"id":"grp-prices","track":"GRP","order":2,"icon":"💲","title":"הגדרות מחיר — נטו, רווח וחופשיים","goal":"להגדיר תמחור נטו עם Markup באחוזים, ולבנות טבלת משלמים וחופשיים לפי השאלה.","why":"זו הטעות שהכי משבשת את התמחור: אם נשאר ברוטו, או שיש 0 בשורה הראשונה, כל המחירים בהצעה יוצאים שגויים.","before":[{"term":"Gross","text":"ברוטו: מחיר עם עמלה מהספק. זו ברירת המחדל במערכת, אבל לא מתאימה לקבוצה."},{"term":"Net","text":"נטו: המחיר שהספק לוקח. אנחנו מוסיפים עליו את הרווח. בקבוצה תמיד נטו, גם כשבשאלה זה לא כתוב."},{"term":"Markup","text":"הרווח שאנחנו מוסיפים, באחוזים. האחוז כתוב בשאלה."},{"term":"Free","text":"נוסע חופשי. \"אחד על כל 20\": ב-20 משלמים יש חופשי אחד, ב-40 יש שניים. העלות שלו מתחלקת בין המשלמים."}],"steps":[{"title":"עוברים ללשונית המחירים","text":"בהצעה שפתחתם עוברים ללשונית [[Price Definitions]]. את [[Currency]] לא משנים.","shot":"לשונית Price Definitions פתוחה, שדה Currency מסומן כ\"לא נוגעים\"."},{"title":"מעבירים מברוטו לנטו","text":"בחלון השני משנים מ-[[Gross]] ל-[[Net]] (האפשרות שמחשבת לפי מחירי נטו ועוד Markup).","why":"בקבוצה מקבלים מהספק מחיר נטו וקובעים את הרווח בעצמנו.","trap":"בשאלה לא כתוב \"נטו\". צריך לדעת את זה לבד! אם נשאר ברוטו, השדה של אחוז הרווח אפור ואי אפשר לשנות אותו.","shot":"החלון השני ב-Price Definitions, עם אפשרות ה-Net מסומנת.","verify":"הנוסח המדויק על המסך: hishtalmut_04 — \"Total based on net prices\"; 00_docs_summary — \"Totals are based on the sum of net prices plus mark up\". לבדוק במערכת ולעדכן את הטקסט."},{"title":"Markup באחוזים","text":"פותחים את ה-[[Markup]] ומקלידים את אחוז הרווח מהשאלה, מספר בלי הסימן %. מוודאים שהסוג הוא [[Percent]].","trap":"לא לשנות ל-[[Fix Amount]]. אם הסוג משתנה, כל התרגיל יוצא שגוי.","shot":"שדה Markup עם הסוג Percent ומספר האחוז, מסומנים.","verify":"00_docs_summary מתאר \"Add new Markup Type → Percent\". לבדוק אם צריך להוסיף שורה חדשה או רק להקליד בשורה קיימת."},{"title":"קוראים את ניסוח החופשיים","text":"בשאלה מחפשים: לאילו גדלי קבוצה הסוכן מבקש הצעה, ומה כלל החופשיים. בדוגמה שלנו: \"נוסע חופשי אחד על כל 20\". לכן: 20 משלמים → חופשי 1, 40 משלמים → 2 חופשיים.","why":"גם בניסוח \"חופשי אחד במינימום X\" כל X נוספים מוסיפים עוד חופשי.","shot":"אין צילום מסך — דוגמת חישוב קצרה (טבלה: משלמים / חופשיים)."},{"title":"ממלאים את טבלת הנוסעים","text":"בחלון האחרון, בכל שורה מקלידים מספר משלמים ומספר חופשיים. שורה חסרה מוסיפים ב-[[Click here to add new]].","trap":"אסור 0 בשורה הראשונה. 0 שם משבש את כל התמחור.","shot":"טבלת המשלמים והחופשיים עם השורות 20/1 ו-40/2 מסומנות."},{"title":"מוחקים שורות מיותרות","text":"שורה שלא מופיעה בשאלה (למשל 55 שמופיעה כברירת מחדל) מוחקים ב-[[X]] שבשורה.","shot":"שורה מיותרת בטבלה עם ה-X שלה מסומן."},{"title":"שומרים ובודקים","text":"לוחצים [[Save]]. לחיצה נוספת על [[Save]] מציגה [[No changes were made]], כלומר הכול נשמר.","why":"עד שנפתח דוקט אפשר לחזור לכאן, לשנות (למשל חופשיים) ולשמור שוב.","shot":"ההודעה No changes were made אחרי שמירה שנייה."}],"oral":[{"q":"למה בקבוצה מעבירים מ-Gross ל-Net?","a":"כי בקבוצה הספק נותן מחיר נטו, ואנחנו קובעים את הרווח (Markup) בעצמנו. ברוטו מתאים כשהרווח הוא עמלה מהספק, כמו ב-FIT."},{"q":"חופשי אחד על כל 15, וקבוצה של 40. כמה חופשיים?","a":"2: אחד ב-15 ואחד ב-30. ב-40 עוד לא מגיעים לשלישי."},{"q":"מי משלם על הנוסע החופשי?","a":"שאר המשתתפים. העלות שלו מתחלקת ביניהם (\"אין מתנות חינם\"), ולא המלון ולא החברה נותנים אותו."},{"q":"מה ההבדל בין Staff ל-Free?","a":"Staff = אנשי צוות שהטיול צריך (נהג, מדריך מלווה), מוגדרים ב-Information. Free = הטבה למארגן הקבוצה, מוגדרת ב-Price Definitions."}],"check":["מסומן Net ולא Gross","אחוז ה-Markup כמו בשאלה, והסוג Percent","בטבלה רק גדלי הקבוצה שבשאלה, עם מספר החופשיים הנכון","אין 0 בשורה הראשונה","לחצתם Save וקיבלתם No changes were made בשמירה חוזרת"],"sources":["TB_master §8.2","00_docs_summary: קבוצות — הצעת מחיר 2","hishtalmut_04 חלק ג׳ לשונית 2","hishtalmut_06 §4.4, §6 שאלות 3-4, §7 שלב ב","hishtalmut_09 §3 שלב 2"],"record":"proposal"},{"id":"grp-itinerary","track":"GRP","order":3,"icon":"🗓️","title":"מסלול: תאריכים, אוטובוס ומדריך","goal":"ליצור את ימי הטיול, ולהגדיר לכל יום אוטובוס (Transport) ומדריך (Guide) לפי השאלה.","why":"טעות בתאריכים כאן אי אפשר לתקן, וטעות בסוג היום (מלא/חצי/העברה) לא נותנת הודעת שגיאה אבל משנה את המחיר.","before":[{"term":"Transport","text":"האוטובוס של הקבוצה. לכל יום בוחרים: יום מלא, חצי יום, או בלי אוטובוס."},{"term":"Guide","text":"המדריך היומי. מגדירים אותו לכל יום באותה שיטה כמו האוטובוס."},{"term":"Transfer","text":"העברה בלבד, למשל משדה התעופה למלון ביום ההגעה."},{"term":"Full Day","text":"ברירת המחדל לכל יום. כל מה שלא כתוב בשאלה נשאר Full Day."}],"steps":[{"title":"עוברים ללשונית המסלול","text":"עוברים ללשונית [[Itinerary]].","trap":"לא עובדים בתצוגת [[Itinerary Horizontal]]. עובדים בתצוגה השנייה.","shot":"לשונית Itinerary פתוחה, עם שתי התצוגות; התצוגה שעובדים בה מסומנת.","verify":"hishtalmut_04 אומר לא לעבוד ב-Itinerary Horizontal, ו-00_docs_summary קורא לשלב הזה \"Horizontal-Itinerary\". לבדוק במערכת באיזו תצוגה מגדירים תאריכים."},{"title":"תאריך התחלה ומשך","text":"בוחרים תאריך התחלה. אחר כך ממלאים אחד מהשלושה: תאריך סיום, מספר ימים, או מספר לילות.","trap":"בודקים שלוש פעמים לפני שממשיכים. הרבה פעמים מכניסים רק תאריך, ונשאר יום אחד. או שבוחרים לילות במקום ימים.","shot":"שדה תאריך ההתחלה ושלושת השדות (סיום / ימים / לילות) מסומנים."},{"title":"יוצרים מסלול ושומרים","text":"לוחצים [[Create Itinerary]] ואחר כך [[Save]]. מעל שורת המלון מופיעות עכשיו [[Transport]] ו-[[Guide]].","trap":"לא רואים [[Transport]] או [[Guide]]? כנראה לא לחצתם [[Save]].","shot":"המסלול אחרי Save, עם השורות Transport ו-Guide מסומנות."},{"title":"תאריכים שגויים? הצעה חדשה","text":"אם הימים יצאו לא נכונים, לא מנסים לתקן. פותחים הצעה חדשה וממלאים שוב [[Information]] ו-[[Price Definitions]].","why":"שינוי תאריכים לא נקלט כמו שצריך ומזיז הכול ביום. שתי הלשוניות הראשונות קצרות ומהירות.","shot":"אין צילום מסך — כרטיס אזהרה."},{"title":"פותחים את Transport","text":"לוחצים על [[Transport]] בצד שמאל. לכל יום יש עיגולים ([[Full Day]], [[Half Day]], [[None]]) = הבחירה הכללית ליום, וריבועים ([[Transfer]], תוספת ערב) = תוספות.","shot":"חלון Transport פתוח; העיגולים והריבועים מסומנים בשני צבעים.","verify":"שם התוספת לערב/לילה: hishtalmut_04 — \"Night Tour\" (?); hishtalmut_06 — \"Night Activity\". לבדוק את השם על המסך."},{"title":"יום הגעה: None ו-Transfer","text":"ביום ההגעה (העברה בלבד) משנים את העיגול ל-[[None]], ומסמנים V ב-[[Transfer]]. כך גם ביום העזיבה.","trap":"אם משאירים [[Full Day]] ומסמנים [[Transfer]] — אין הודעת שגיאה, אבל המחיר לא יתאים.","shot":"יום ההגעה ב-Transport: None מסומן ו-V ב-Transfer."},{"title":"שאר הימים לפי השאלה","text":"עוברים בין הימים עם החץ. חצי יום = [[Half Day]]. יום בלי אוטובוס = [[None]]. סיור ערב = מסמנים את תוספת הערב. מה שלא כתוב נשאר [[Full Day]]. בסוף [[Save]].","shot":"החץ למעבר בין ימים מסומן, ויום עם Half Day."},{"title":"חוזרים ליום הראשון","text":"אחרי [[Save]] המסך נשאר על היום האחרון. חוזרים עם החץ ליום הראשון של הטיול לפני שממשיכים.","trap":"מי שממהר משנה ב-[[Guide]] את היום הלא נכון. תמיד מסתכלים על התאריך.","shot":"התאריך שמוצג אחרי Save (היום האחרון) מסומן, והחץ שמאלה."},{"title":"Guide באותה שיטה","text":"לוחצים על [[Guide]] וממלאים כל יום: [[Full Day]], [[Half Day]], [[None]], [[Transfer]], תוספת ערב — לפי השאלה. בסוף [[Save]].","trap":"[[Transport]] ו-[[Guide]] לא תמיד זהים. למשל: ביום העזיבה אוטובוס להעברה בלבד, אבל מדריך לחצי יום. קוראים את השאלה ולא מעתיקים.","shot":"חלון Guide פתוח, עם יום שבו ההגדרה שונה מה-Transport."}],"oral":[{"q":"מה עושים אם התאריכים במסלול יצאו שגויים?","a":"לא מתקנים. פותחים הצעה חדשה, כי שינוי תאריכים לא נקלט כמו שצריך ומזיז את כל המסלול."},{"q":"ביום ההגעה יש רק העברה משדה התעופה. מה מסמנים ב-Transport?","a":"None בבחירה הכללית ליום, ו-V ב-Transfer."},{"q":"בשאלה לא כתוב כלום על יום מסוים. מה עושים?","a":"משאירים את ברירת המחדל: Full Day, גם ב-Transport וגם ב-Guide."},{"q":"למה לפעמים יש מדריך ליום מלא ואוטובוס רק לחצי יום?","a":"Transport ו-Guide לא תמיד חופפים. למשל, בחצי השני של היום יש סיור רגלי ליד המלון, אז צריך מדריך ולא אוטובוס."}],"check":["מספר הימים והלילות תואם לשאלה","השורות Transport ו-Guide מופיעות מעל המלון","ביום ההגעה וביום העזיבה: None ו-V ב-Transfer (אם כך כתוב)","ה-Guide מולא מהיום הראשון, ולא מהיום האחרון","ימים שלא כתוב עליהם כלום נשארו Full Day","לחצתם Save אחרי Transport ואחרי Guide"],"sources":["TB_master §8.3-8.4","00_docs_summary: קבוצות — הצעת מחיר 3-5","hishtalmut_04 חלק ג׳ לשונית 3","hishtalmut_06 §7 שלבים ג-ה","hishtalmut_09 §3 שלבים 3-5"],"record":"proposal"},{"id":"grp-hotels","track":"GRP","order":4,"icon":"🏨","title":"מלונות בהצעה","goal":"להוסיף להצעה את המלונות מהשאלה, עם סוג חדר, תאריכים, לילות ובסיס אירוח.","why":"המלון הוא בדרך כלל ההוצאה האישית הגדולה בהצעה. סוג חדר או בסיס אירוח לא נכונים משנים את המחיר לכל משתתף.","before":[{"term":"Board Basis","text":"בסיס אירוח: Bed & Breakfast (לינה וארוחת בוקר), Half Board (חצי פנסיון) וכו'."},{"term":"Done","text":"יש שני כפתורי Done: פנימי (סוגר את החדר שבחרתם) וחיצוני (סוגר את כל חלון המלונות)."},{"term":"Staff","text":"אנשי הצוות שהוגדרו ב-Information מופיעים גם כאן בצד, כי המערכת מתמחרת גם את החדרים שלהם."}],"steps":[{"title":"פותחים הוספת מלון","text":"במסלול לוחצים [[Add Hotel]].","why":"סדר העבודה: קודם אוטובוס, אחר כך מדריך, ואז לינה.","shot":"המסלול עם הכפתור Add Hotel מסומן."},{"title":"יעד ושם המלון","text":"מקלידים את העיר ב-[[Destination]]. אם יודעים את שם המלון מקלידים אותו (גם חלק מהשם), ולוחצים [[Find]].","why":"בלי שם, [[Find]] מציג את כל המלונות בעיר.","trap":"שמות דומים: חיפוש \"Dan\" בירושלים מחזיר גם [[Dan Panorama]] וגם [[Dan Jerusalem]]. בוחרים בדיוק את המלון מהשאלה.","shot":"שדות Destination ושם המלון, וכפתור Find, מסומנים."},{"title":"סוג חדר ו-+","text":"מופיעים סוגי החדרים (למשל [[Standard]], [[Deluxe]]) עם הפרשי מחיר. בוחרים את הסוג מהשאלה ולוחצים [[+]].","trap":"תלמידים בוחרים אוטומטית את הסוג הראשון ברשימה. בודקים מול השאלה.","shot":"רשימת סוגי החדרים של המלון, עם ה-+ ליד הסוג הנבחר מסומן."},{"title":"תאריך, לילות ובסיס אירוח","text":"בתוך ה-[[+]] מקלידים תאריך כניסה ומספר לילות, ובוחרים [[Board Basis]] לפי השאלה.","why":"כדי לוודא את מספר הלילות, מסתכלים על בסיס האירוח ולא על הכניסה והיציאה, שמבלבלים.","shot":"חלון ה-+ עם התאריך, הלילות ו-Board Basis מסומנים, ובצד אנשי הצוות."},{"title":"חדרי הצוות","text":"בצד החלון מופיעים אנשי הצוות מלשונית [[Information]] (בדוגמה שלנו: כולם ביחיד). לא משנים כאן כלום, רק בודקים שהמספר נכון.","why":"המערכת מתמחרת גם את החדרים שלהם, והעלות מתחלקת בין המשתתפים.","shot":"אזור הצוות בחלון המלון מסומן.","verify":"לבדוק אם אפשר לשנות כאן את חלוקת הצוות או רק לצפות בה. המקורות רק מציינים שהצוות \"מוצג בצד\"."},{"title":"Done פנימי ו-Done חיצוני","text":"לוחצים [[Done]] הפנימי, ואחריו [[Done]] החיצוני. מלון נוסף באותה עיר אפשר להוסיף לפני ה-[[Done]] החיצוני. בסוף [[Save]].","trap":"לחיצה כפולה מוסיפה את המלון פעמיים.","shot":"שני כפתורי Done מסומנים במספרים 1 ו-2."},{"title":"מלון שני","text":"חוזרים על השלבים עבור המלון הבא בשאלה: [[Add Hotel]], יעד, [[Find]], סוג חדר, [[+]], תאריך ולילות, בסיס, [[Done]] ו-[[Done]], [[Save]].","trap":"לא רואים את המלון החדש? כנראה התצוגה עומדת על סוף הטיול. חוזרים אחורה עם החץ.","shot":"המסלול עם שני מלונות, כל אחד בימים שלו."},{"title":"מלון כפול או לילה כפול? X","text":"אם מלון נכנס פעמיים, או ששני מלונות נפלו על אותו לילה — לא מתחילים מחדש. לוחצים על ה-[[X]] הלבן בשורה, מאשרים את המחיקה, ומזמינים שוב בתאריך הנכון.","shot":"שורת מלון במסלול עם ה-X הלבן מסומן."}],"oral":[{"q":"למה אנשי הצוות מופיעים בחלון המלון?","a":"כי המערכת צריכה לתמחר גם את החדרים שלהם. העלות שלהם נכנסת לעלויות הקבוצתיות ומתחלקת בין המשתתפים."},{"q":"מה ההבדל בין Bed & Breakfast ל-Half Board?","a":"Bed & Breakfast = לינה וארוחת בוקר. Half Board = חצי פנסיון: לינה, ארוחת בוקר וארוחה נוספת."},{"q":"גיליתם ששני מלונות נפלו על אותו לילה. מה עושים?","a":"מוחקים את השורה השגויה ב-X, מאשרים, ומזמינים שוב בתאריך הנכון. לא צריך להתחיל את ההצעה מחדש."}],"check":["כל מלון מהשאלה מופיע פעם אחת בלבד","שם המלון וסוג החדר בדיוק כמו בשאלה","מספר הלילות בכל מלון נכון, ואין לילה עם שני מלונות","בסיס האירוח של כל מלון כמו בשאלה","לחצתם Save"],"sources":["TB_master §8.5","00_docs_summary: קבוצות — הצעת מחיר 6","hishtalmut_04 חלק ג׳ מלונות","hishtalmut_06 §7 שלבים ה-ו","hishtalmut_09 §3 שלב 6"],"record":"proposal"},{"id":"grp-activities","track":"GRP","order":5,"icon":"🎟️","title":"אתרים ופעילויות בהצעה","goal":"להוסיף את אתרי הביקור מהשאלה, במחיר קבוצתי כשיש, בתאריך ובשעות הנכונים.","why":"כאן נמצאות רוב המלכודות של הצעה קבוצתית: אתרים עם שמות דומים, מחיר רגיל במקום קבוצתי, ואזור חיפוש לא נכון.","before":[{"term":"Include FIT Rate","text":"סימון שמציג גם אתרים שיש להם רק מחיר לבודדים. בלעדיו חלק מהאתרים לא מופיעים (למשל גן החיות התנ\"כי)."},{"term":"Group Rate","text":"מחיר קבוצתי. כשלאתר יש גם מחיר קבוצתי וגם רגיל, חובה לבחור את הקבוצתי."},{"term":"Destination","text":"האזורים במערכת: Jerusalem, Tel Aviv, Eilat, Dead Sea, Galilee. בכל אזור יש רק כמה אתרים."}],"steps":[{"title":"פותחים הוספת פעילות","text":"במסלול לוחצים [[Add Activity]] ובוחרים אזור ב-[[Destination]].","trap":"לאתרים בצפון האזור הוא [[Galilee]], לא \"כנרת\". לא מוצאים? לוחצים [[Find]] בלי אזור ומקבלים את כל האתרים.","shot":"חלון Add Activity עם שדה Destination מסומן."},{"title":"מסמנים Include FIT Rate","text":"מסמנים V ב-[[Include FIT Rate]] ולוחצים [[Find]].","trap":"בלי הסימון חלק מהאתרים לא יופיעו.","shot":"תיבת Include FIT Rate עם V, וכפתור Find, מסומנים.","verify":"שם התיבה: hishtalmut_04 — \"Include FIT Rate\"; hishtalmut_09 — \"Include FIT\". לבדוק את הנוסח המדויק."},{"title":"לא מקלידים שם אתר","text":"עדיף לא להקליד שם אתר. אחרי [[Find]] בוחרים מהרשימה.","why":"בכל אזור יש 3–4 אתרים בלבד. אות אחת שגויה בשם, ו-[[Find]] לא מחזיר כלום.","shot":"רשימת האתרים של אזור אחרי Find."},{"title":"בוחרים את האתר הנכון","text":"בוחרים בדיוק את האתר מהשאלה. כשיש לאתר [[Group Rate]], בוחרים אותו.","trap":"שמות דומים: [[Tower of David]] (מגדל דוד) הוא לא [[City of David]] (עיר דוד). מצדה: יש עם רכבל ויש בלי — בודקים מה השאלה מבקשת. [[Tel Aviv Museum]] הוא לא מוזיאון ארץ ישראל.","shot":"אתר עם שתי שורות מחיר (Group Rate ומחיר רגיל), Group Rate מסומן."},{"title":"+ ותאריך","text":"פותחים [[+]] ליד האתר ובוחרים את התאריך מהשאלה.","shot":"חלון ה-+ של אתר, שדה התאריך מסומן."},{"title":"שעות בפורמט 12:00","text":"מקלידים שעת התחלה ושעת סיום כמו בשאלה, בפורמט 12:00 (עם נקודתיים ושני אפסים). אם בשאלה אין שעה, לא נוגעים בשעות.","trap":"\"12\" בלבד נותן שגיאת פורמט.","shot":"שדות שעת התחלה וסיום עם 10:00 ו-12:00, מסומנים."},{"title":"Done פנימי, ועוד אתר","text":"לוחצים [[Done]] הפנימי. עוד אתר באותו אזור? פותחים [[+]] נוסף באותו מסך. בסוף לוחצים [[Done]] החיצוני ו-[[Save]].","why":"אפשר לעשות [[Save]] גם בין אתר לאתר.","shot":"רשימת האתרים עם V ליד האתרים שנבחרו, ושני כפתורי Done."},{"title":"טעות בשעה או ביום","text":"שעה שגויה — מתקנים בעיפרון של הפעילות. יום שגוי — גוררים את הפעילות ביומן ליום הנכון. לא צריך למחוק.","why":"יש שמכניסים את כל האתרים ביום הראשון וגוררים כל אחד ליומו. שתי השיטות בסדר.","shot":"פעילות במסלול נגררת מיום ליום (חץ גרירה)."}],"oral":[{"q":"למה מסמנים Include FIT Rate בפעילויות?","a":"כי יש אתרים שיש להם רק מחיר לבודדים ואין להם מחיר קבוצתי. בלי הסימון הם לא מופיעים ברשימה."},{"q":"לאתר יש Group Rate ומחיר רגיל. איזה בוחרים ולמה?","a":"Group Rate. זה המחיר לקבוצה, הוא שונה (בדרך כלל זול יותר), ובהצעה לקבוצה רוצים את המחיר הנכון והזול."},{"q":"הזנתם אתר ביום הלא נכון. מה עושים?","a":"גוררים את הפעילות ביומן ליום הנכון. לא צריך למחוק."},{"q":"מה ההבדל בין Activity ל-Guide בהצעה קבוצתית?","a":"Activity = כניסה לאתר או ביקור (מוזיאון, מצדה). Guide = המדריך היומי של הקבוצה, שמוגדר לכל יום במסלול."}],"check":["כל האתרים מהשאלה מופיעים, כל אחד ביום הנכון","נבחר Group Rate בכל אתר שיש לו","האתר הנכון: מגדל דוד ולא עיר דוד, מצדה עם/בלי רכבל לפי השאלה, המוזיאון הנכון","השעות כמו בשאלה, בפורמט 12:00","לחצתם Done החיצוני ו-Save"],"sources":["TB_master §8.6","00_docs_summary: קבוצות — הצעת מחיר 7","hishtalmut_04 חלק ג׳ פעילויות","hishtalmut_06 §7 שלב ז","hishtalmut_09 §3 שלב 7"],"record":"proposal"},{"id":"grp-extras","track":"GRP","order":6,"icon":"🍽️","title":"מסעדות, כובעים ומים","goal":"להוסיף מסעדות לפי מיקום הקבוצה, כובעים ומים, ולבדוק את ההצעה ב-Totals.","why":"בלי סימון אחד קטן לא מופיעה אף מסעדה. ובסוף בניית ההצעה בודקים אותה מול הפתרון לפני שממשיכים.","before":[{"term":"Restaurant","text":"יש רק כשש מסעדות במערכת, ולכולן מחיר לבודדים בלבד."},{"term":"General","text":"מוצרים נוספים לקבוצה: כובעים ובקבוקי מים."},{"term":"Totals","text":"תדפיס מרוכז של ה-Calculation Sheet, בלי ספרות אחרי הנקודה. נוח להשוואה מול הפתרון."}],"steps":[{"title":"שומרים לפני שממשיכים","text":"לוחצים [[Save]].","why":"תמיד שומרים לפני שלב חדש. יש ניתוקים.","shot":"כפתור Save במסלול מסומן."},{"title":"מסעדה: Include FIT Rate","text":"לוחצים [[Add Restaurant]], מסמנים V ב-[[Include FIT Rate]], ולוחצים [[Find]]. לא צריך לבחור עיר.","trap":"בלי הסימון לא מופיעה אף מסעדה. אם כבר הקלדתם עיר — מוחקים אותה ולוחצים [[Find]].","shot":"חלון Add Restaurant, תיבת Include FIT Rate עם V ו-Find מסומנים."},{"title":"מסעדה לפי מיקום הקבוצה","text":"ברשימה מופיעים שם המסעדה והעיר. בוחרים את המסעדה מהשאלה, ובודקים שהיא בעיר שבה הקבוצה נמצאת באותו יום.","trap":"לא נותנים מסעדה בטבריה ביום שהקבוצה באילת.","shot":"רשימת המסעדות עם עמודת העיר מסומנת."},{"title":"+, תאריך ושעות הגיוניות","text":"פותחים [[+]], בוחרים תאריך ומקלידים שעות. אם בשאלה אין שעה, בוחרים שעה הגיונית: ארוחת ערב בערך 19:00–21:00, ארוחת צהריים בערך 13:00–14:00. בסוף [[Done]] הפנימי ו-[[Done]] החיצוני.","trap":"לא ארוחת ערב ב-06:00–08:00.","shot":"חלון ה-+ של מסעדה עם תאריך ו-19:00–21:00."},{"title":"כובעים: רק ביום הראשון","text":"לוחצים [[Add General]], מסמנים [[Include FIT Rate]] ולוחצים [[Find]]. ליד הכובעים פותחים [[+]] ובוחרים רק את היום הראשון. אין צורך בשעה. [[Done]].","why":"כובע מחלקים פעם אחת.","shot":"חלון Add General עם הכובעים, ה-+ והיום הראשון מסומנים."},{"title":"מים: כל יום","text":"ליד בקבוקי המים פותחים [[+]] ובוחרים טווח מהיום הראשון עד היום האחרון (אלא אם בשאלה כתוב אחרת). אין צורך בשעה. [[Done]] הפנימי ו-[[Done]] החיצוני.","trap":"פריט ביום ריק מופיע למעלה, וביום עם שירותים אחרים — למטה. לא נבהלים אם לא רואים אותו מיד.","shot":"חלון ה-+ של המים עם טווח תאריכים מהיום הראשון עד האחרון."},{"title":"שומרים ובודקים את כל המסלול","text":"לוחצים [[Save]]. עוברים על המסלול מול השאלה: כל שירות, יום, שעה. המסך מציג עד 5 ימים, ולימים הבאים עוברים עם החץ בצד.","shot":"המסלול המלא, עם החץ לימים הבאים מסומן."},{"title":"Print ואז Totals","text":"לוחצים [[Print]] ובוחרים [[Totals]]. משווים כל רכיב (מלון, מסעדות, פעילויות...) לדף הסכומים של המורה.","why":"אם רכיב אחד לא מתאים, חוזרים למסלול ובודקים שבחרתם את האתר או המסעדה הנכונים.","shot":"תפריט Print פתוח עם Totals מסומן, ודוגמת התדפיס."}],"oral":[{"q":"לא מוצאים אף מסעדה. מה הסיבה?","a":"כנראה לא סימנתם Include FIT Rate. למסעדות יש רק מחירים לבודדים."},{"q":"בשאלה לא כתובה שעה לארוחת הערב. מה מקלידים?","a":"שעה הגיונית, למשל 19:00–21:00. כל שעה סבירה מתקבלת."},{"q":"מתי מחלקים כובעים ומתי מים?","a":"כובע — פעם אחת, ביום הראשון. מים — בדרך כלל כל יום, לפי השאלה."}],"check":["כל מסעדה בעיר שבה הקבוצה נמצאת באותו יום","שעות המסעדות כמו בשאלה, או הגיוניות","כובעים רק ביום הראשון, מים בכל הימים (או לפי השאלה)","לחצתם Save","Print → Totals תואם לדף הסכומים"],"sources":["TB_master §8.7-8.9","00_docs_summary: קבוצות — הצעת מחיר 8","hishtalmut_04 חלק ג׳ מסעדות, מוצרים נוספים","hishtalmut_06 §7 שלבים ח-ט","hishtalmut_09 §3 שלבים 8-9, §4"],"record":"proposal"},{"id":"grp-read","track":"GRP","order":7,"icon":"📊","title":"קריאת ה-Calculation Sheet","goal":"לקרוא את דף התחשיב: עלויות קבוצתיות ואישיות, מחיר מכירה ותוספות — ולענות על שאלות מחיר.","why":"בבחינה שואלים מחירים מתוך הדף הזה, וגם שאלות הבנה עליו. ואחריו עוצרים וקוראים לבוחן לפני השינויים.","before":[{"term":"Group Costs","text":"עלויות קבועות לכל הקבוצה: אוטובוס, מדריך, אנשי צוות. מתחלקות בין המשתתפים, לכן העלות לאדם יורדת כשיש יותר משתתפים."},{"term":"Individual Costs","text":"עלויות לכל משתתף: מלון, מסעדות, פעילויות, General, ועלות החופשיים (Add for Free)."},{"term":"Cost / Markup / Total","text":"Cost = העלות שלנו לאדם (נטו). Markup = הרווח. Total selling price = מחיר המכירה לאדם."},{"term":"Supplements","text":"תוספות והנחות: חצי פנסיון לכל המסלול, תוספת יחיד, הנחה לילד שלישי בחדר, הנחה למבוגר שלישי בחדר."},{"term":"Staff ≠ Free","text":"צוות (נהג, מדריך מלווה, מורים מלווים, טבח) = עלות קבוצתית, למעלה. חופשי = הטבה למארגן, למטה ב-Add for Free."}],"steps":[{"title":"בודקים שהכול בפנים","text":"לפני שנכנסים לתחשיב, עוברים על השאלה: כל מה שנדרש נמצא במסלול, לא חסר כלום ואין משהו מיותר.","shot":"אין צילום מסך — כרטיס תזכורת."},{"title":"פותחים את התחשיב","text":"עוברים ללשונית [[Calculation Sheet]]. החישוב לוקח כמה שניות.","shot":"לשונית Calculation Sheet פתוחה, כל הדף."},{"title":"עמודה לכל גודל קבוצה","text":"בראש הדף יש עמודה לכל גודל קבוצה מ-[[Price Definitions]]. בדוגמה שלנו: 20 משלמים עם חופשי 1, ו-40 עם 2 חופשיים. כל המחירים הם לאדם בחדר זוגי.","why":"אלה הצעות שונות לאותה קבוצה, עם אותם שירותים. רק מספר המשתתפים והחופשיים משתנה.","trap":"זה לא כמה קבוצות שונות.","shot":"כותרות העמודות (גדלי קבוצה וחופשיים) מסומנות."},{"title":"עלויות קבוצתיות","text":"בחלק [[Group Costs]]: אוטובוס, מדריך ואנשי צוות. סך העלויות מחולק במספר המשתתפים, והתוצאה בשורה [[Net per person]].","why":"בקבוצה גדולה יותר העלות לאדם יורדת. בגדלים שונים ייתכן שיידרש אוטובוס אחר.","shot":"החלק Group Costs ושורת Net per person מסומנים."},{"title":"עלויות אישיות","text":"בחלק [[Individual Costs]]: מלון, מסעדות, [[Activities]], [[General]], ו-[[Add for Free]]. החץ הקטן ליד כל שורה פותח פירוט. הסיכום בשורה [[Total individual expenses]].","why":"[[Add for Free]] היא השורה שמשתנה בין העמודות: עלות החופשיים מתחלקת בין המשלמים.","shot":"החלק Individual Costs, שורת Add for Free ושורת Total individual expenses מסומנים."},{"title":"סיכום: עלות, רווח, מחיר","text":"בחלק הסיכום: [[Cost per person]] (העלות שלנו לאדם), [[Markup]] (הרווח), ו-[[Total selling price]] (מחיר המכירה לאדם).","why":"\"עלות נטו\" = Cost. \"מחיר מכירה\" = Total. \"עלות כוללת\" בשאלה = לרוב כולל רווח.","shot":"שלוש השורות Cost per person, Markup, Total selling price מסומנות."},{"title":"תוספות והנחות","text":"בתחתית, ב-[[Supplements]]: תוספת חצי פנסיון לכל המסלול, [[Single Supplement]] (תוספת יחיד), הנחה לילד שלישי בחדר, והנחה למבוגר שלישי בחדר.","shot":"החלק Supplements בתחתית הדף מסומן."},{"title":"אין סך לכל הקבוצה","text":"המחיר הכולל לכל הקבוצה לא מופיע בדף הזה, רק מחיר לאדם. הוא יופיע רק אחרי פתיחת הדוקט, בשורה הוורודה.","shot":"אין צילום מסך — כרטיס הסבר."},{"title":"עוצרים וקוראים לבוחן","text":"כאן עוצרים! משאירים את ההצעה פתוחה וקוראים לבוחן או למורה, לפני כל שינוי.","why":"בהצעת מחיר אין היסטוריה של שינויים (כמו שיש בדוקט FIT). אחרי שינוי, אי אפשר לראות מה היה קודם.","trap":"מי שמדלג ומשנה לפני הבדיקה — אין דרך לדעת אם הטעות הייתה במקור או בשינוי.","shot":"אין צילום מסך — כרטיס עצירה בולט."}],"oral":[{"q":"בראש הדף יש שלוש עמודות. אלה שלוש קבוצות?","a":"לא. אלה שלוש הצעות לאותה קבוצה, עם אותם שירותים. ההבדל רק במספר המשתתפים והחופשיים."},{"q":"מה ההבדל בין Group Costs ל-Individual Costs?","a":"Group Costs קבועות לכל הקבוצה (אוטובוס, מדריך, צוות) ומתחלקות בין המשתתפים. Individual Costs הן לכל משתתף (מלון, מסעדות, פעילויות)."},{"q":"איפה מופיעים אנשי הצוות ואיפה החופשיים?","a":"הצוות למעלה, בעלויות הקבוצתיות. החופשיים למטה, בשורה Add for Free בעלויות האישיות."},{"q":"למה עלות החופשיים לאדם יכולה לרדת כשהקבוצה גדלה?","a":"כי אותו מספר חופשיים מתחלק בין יותר משתתפים."},{"q":"איפה רואים את המחיר הכולל לכל הקבוצה?","a":"לא ב-Calculation Sheet. רק אחרי פתיחת דוקט, בשורה הוורודה."},{"q":"מה זה Single Supplement?","a":"התוספת למי שישן לבד בחדר. מופיעה בתחתית הדף, ב-Supplements."}],"check":["אתם יודעים לקרוא Net per person בכל עמודה","אתם יודעים לקרוא Total individual expenses","אתם יודעים איפה Cost per person, Markup ו-Total selling price","אתם יודעים איפה Single Supplement","עצרתם וקראתם לבוחן לפני שינויים"],"sources":["TB_master §9, §8.10","00_docs_summary: קבוצות — Calculation Sheet","hishtalmut_04 חלק ד׳, חלק ה׳","hishtalmut_06 §6 שאלות 5-9","hishtalmut_09 §1 עצירה לפני השינויים, §4"],"record":"proposal"},{"id":"grp-changes","track":"GRP","order":8,"icon":"✏️","title":"שינויים בהצעה ושליחה","goal":"לבצע שינויים שהבוחן מבקש (בסיס אירוח, הערה, ביטול, רווח), לבדוק את המחיר החדש ולשלוח את ההצעה.","why":"שינויים ומסמכים הם חלק נפרד בציון. בקבוצה עושים את כל השינויים בהצעה, לפני שפותחים דוקט.","before":[{"term":"Remark","text":"הערה ליום מסוים. בוחרים אותה מרשימה מוכנה לפי המספר שבשאלה. בדוקט היא תופיע כשורה לבנה."},{"term":"Markup","text":"אפשר לשנות את אחוז הרווח לכל ההצעה, או רק לשירות אחד (למשל מסעדה)."},{"term":"Itinerary","text":"את רוב השינויים עושים במסלול. ה-Calculation Sheet רק מחשב מתוכו."}],"steps":[{"title":"רק אחרי הבוחן","text":"מתחילים שינויים רק אחרי שהבוחן בדק את ההצעה ואישר להמשיך (ראו יחידת קריאת ה-Calculation Sheet). מומלץ לשלוח [[Totals]] לפני השינויים, ושוב אחריהם.","shot":"אין צילום מסך — כרטיס תזכורת."},{"title":"שינוי בסיס אירוח","text":"במסלול לוחצים על [[Board]] בשורת המלון, בוחרים את הבסיס החדש (למשל [[Bed & Breakfast]]) ביום שבשאלה, סוגרים ולוחצים [[Save]].","shot":"שורת מלון במסלול עם Board מסומן, והחלון שנפתח.","verify":"hishtalmut_04: ללחוץ על \"Board\" ולא על \"Board Basis\"; hishtalmut_09 קורא לכפתור \"Board Bases\". לבדוק את שם הכפתור המדויק."},{"title":"הוספת הערה ליום","text":"בוחרים את היום. בהמבורגר שליד היום בוחרים [[Edit Day]], ואז [[Remarks]]. פותחים את הרשימה ובוחרים את מספר ההערה מהשאלה. [[OK]] ואחר כך [[Save]].","trap":"בוחרים הערה שיש בה טקסט. הערה ריקה לא תופיע בדוקט.","shot":"תפריט ההמבורגר של יום עם Edit Day, ורשימת Remarks פתוחה.","verify":"hishtalmut_04 ו-TB_master: \"Edit Day\" → \"Remarks\"; hishtalmut_06: \"Itinerary Day\" / \"Day\" → \"Remark\". לבדוק את שמות הפריטים בתפריט."},{"title":"ביטול שירות","text":"לוחצים על ה-[[X]] הלבן ליד השירות, מאשרים [[Yes]], ולוחצים [[Save]].","shot":"שירות במסלול עם ה-X מסומן, וחלון האישור."},{"title":"רווח לשירות אחד","text":"ב-[[Calculation Sheet]] פותחים את החץ של הקטגוריה (למשל [[Activities]]) ובוחרים את השירות. [[Add Markup]], מסמנים [[Apply Markup]], מקלידים את האחוז החדש ולוחצים [[OK]].","why":"כשפותחים שוב, מוצגים רק השירותים שבהם האחוז שונה מהמקורי — כך בודקים שהשינוי נשמר.","shot":"חלון Add Markup של שירות, עם Apply Markup והאחוז מסומנים."},{"title":"רווח לכל ההצעה","text":"לשינוי ה-[[Markup]] הכללי: בחלק ה-[[Totals]] / ה-[[Markup]] לוחצים [[Edit]], משנים את האחוז ולוחצים [[OK]]. השינוי חל על הכול.","shot":"שורת ה-Markup הכללי עם כפתור Edit מסומן.","verify":"המקורות סותרים בדרך: TB_master — \"Totals → Edit\"; hishtalmut_04 — \"בלשונית ה-Markup לוחצים Edit\"; 00_docs_summary — \"Totals → Add Markup → Edit\". לבדוק את הנתיב המדויק."},{"title":"מחיר חדש אחרי כל שינוי","text":"חוזרים ל-[[Calculation Sheet]] ובודקים שהמחירים התעדכנו. רושמים את המחיר החדש לגודל הקבוצה שהבוחן שואל עליו.","why":"כל שינוי, ביטול או שינוי רווח משנה את המחיר הסופי, והבוחן ישאל עליו.","shot":"Calculation Sheet אחרי שינוי, עם Total selling price מסומן."},{"title":"שליחת ההצעה","text":"לוחצים [[Print]] ובוחרים [[Itinerary]] או [[Send Proposal by Mail]], לפי השאלה. מקלידים כתובת מייל ולוחצים [[Continue]].","shot":"תפריט Print עם Itinerary ו-Send Proposal by Mail מסומנים, ושדה המייל.","verify":"00_docs_summary מוסיף אחרי Continue לחיצה על SEND. לבדוק אם יש מסך נוסף אחרי Continue."}],"oral":[{"q":"למה עוצרים לבוחן לפני שינויים בהצעת מחיר?","a":"כי בהצעת מחיר אין היסטוריה של שינויים. אחרי שינוי אי אפשר לבדוק מה היה קודם."},{"q":"איך מוסיפים הערה ליום?","a":"בהמבורגר של היום: Edit Day, ואז Remarks, בוחרים את מספר ההערה, OK ו-Save."},{"q":"מה ההבדל בין שינוי Markup לשירות לבין שינוי כללי?","a":"לשירות: Add Markup על שירות אחד, רק המחיר שלו משתנה. כללי: Edit על ה-Markup, השינוי חל על כל ההצעה."},{"q":"למה בקבוצה עושים את כל השינויים בהצעה ולא בדוקט?","a":"כי שינויים בדוקט קבוצתי אחרי פתיחה לא נקלטים כמו שצריך. פותחים דוקט רק כשהסוכן אומר: זו ההצעה שאני רוצה."}],"check":["כל שינוי שהבוחן ביקש בוצע, ואחריו Save","ההערה שנבחרה מכילה טקסט","השירות שבוטל לא מופיע במסלול","רשמתם את המחיר החדש אחרי השינויים","ההצעה נשלחה למייל שבשאלה"],"sources":["TB_master §8.11-8.12","00_docs_summary: קבוצות — שינויים, שליחה","hishtalmut_04 חלק ה׳, חלק ו׳","hishtalmut_06 §7 שלב יא","hishtalmut_09 §4 השינויים בתרגיל"],"record":"proposal"},{"id":"grp-docket","track":"GRP","order":9,"icon":"📁","title":"פתיחת דוקט קבוצתי ואישורים","goal":"לפתוח דוקט מההצעה עם חלוקת החדרים הנכונה, להבין את השורות בו, ולאשר כל שירות.","why":"בלי אישור לכל שירות לא יוצאים שוברים. ואת הדוקט הקבוצתי לא משנים אחרי שנפתח, ולכן בודקים הכול לפני.","before":[{"term":"Group Travel File","text":"דוקט קבוצתי. ב-FIT כתוב Individual Travel File. ברשימת הדוקטים הסוג מסומן G."},{"term":"שורה ורודה","text":"הסכום הכולל שהסוכן צריך לשלם לנו על כל הקבוצה, כולל הרווח. אותו סכום יופיע בחשבונית."},{"term":"שורה לבנה","text":"הטקסט של ההערה שהוספתם במסלול."},{"term":"Confirm","text":"בקבוצה כל השירותים מגיעים לא מאושרים, ומאשרים כל אחד בנפרד — כי כל ספק מאשר בנפרד."}],"steps":[{"title":"בודקים לפני פתיחה","text":"עוברים שוב על ה-[[Itinerary]] מול השאלה, ובודקים שה-[[Calculation Sheet]] תואם לפתרון.","why":"אחרי פתיחת הדוקט לא משנים אותו. כל השינויים נעשים בהצעה.","shot":"אין צילום מסך — כרטיס אזהרה."},{"title":"Create Travel File","text":"בהצעה לוחצים [[Create Travel File]].","shot":"הכפתור Create Travel File מסומן."},{"title":"חדרים או נוסעים?","text":"ממלאים את החלוקה בפועל: [[Persons in Double]] ו-[[Persons in Single]]. אם בשאלה כתוב מספר חדרים — ממלאים בשדה החדרים. אם כתוב מספר אנשים — בשדה הנוסעים. השדה השני מתחשב לבד.","trap":"\"20 חדרים זוגיים\" זה 40 איש. קוראים בשאלה אם מדובר בחדרים או בנוסעים.","shot":"חלון Create Travel File עם עמודת חדרים ועמודת נוסעים, שתיהן מסומנות.","verify":"כפתור הסיום בחלון: hishtalmut_04 — Create; hishtalmut_06 ו-00_docs_summary — OK. לבדוק."},{"title":"רושמים את מספר הדוקט","text":"מתקבל מספר דוקט כחול. רושמים אותו מיד, ולוחצים עליו כדי להיכנס לדוקט.","why":"שכחתם? ב-[[Information]] של ההצעה: משמאל מספר ההצעה, מימין מספר הדוקט. מתוך הדוקט חוזרים להצעה דרך [[Tools]] ו-[[Calculation Sheet]].","shot":"מספר הדוקט הכחול מסומן; ולשונית Information עם שני המספרים."},{"title":"מכירים את הדוקט","text":"בודקים: כתוב [[Group Travel File]], שם הקבוצה, הסוכן. אין שמות נוסעים. יש שורה ורודה (הסכום כולל רווח) ושורה לבנה (ההערה).","why":"בדוקט עצמו שם הסוכן יכול להופיע בשחור. העיקר שבהצעה נבחר סוכן ירוק.","shot":"כותרת הדוקט עם Group Travel File מסומן, השורה הוורודה והשורה הלבנה מסומנות."},{"title":"מלון פעמיים — זה תקין","text":"כל מלון מופיע בשתי שורות: אחת לנוסעים ואחת לאנשי הצוות. ליד שורת הצוות מופיע מספר אנשי הצוות.","why":"המחיר בשורת הצוות יכול להיות שונה. זו לא טעות. השורה השנייה היא לא של החופשיים.","shot":"שתי שורות של אותו מלון, עם מספר אנשי הצוות מסומן."},{"title":"מאשרים כל שירות","text":"בכל שורת שירות לא מאושרת (סימן אדום): עיפרון, [[Reservation]], [[Reserve, Report and Confirm]]. אם יש מספר אישור בשאלה מקלידים אותו, ואם אין — [[OK]]. שורה אחרי שורה.","why":"בחיים האמיתיים כל ספק מקבל בקשה נפרדת ומאשר אותה. אין אישור גורף.","trap":"לא מאשרים את השורה הוורודה ואת שורת ההערה.","shot":"חלון Reservation של שירות, עם Reserve, Report and Confirm מסומן.","verify":"סתירה במקורות: TB_master, hishtalmut_04 ו-hishtalmut_09 — עיפרון → Reservation → Reserve, Report and Confirm; 00_docs_summary — עיפרון → Status OK → Save & Exit. לבדוק במערכת איזו דרך עובדת בדוקט קבוצתי (ואם שתיהן — איזו החוברת מלמדת)."},{"title":"בודקים שאושר","text":"אין סימן חיצוני בטוח. נכנסים לעיפרון ואז [[Reservation]]: אם נשאר רק כפתור ביטול — השירות אושר.","trap":"לא ללחוץ [[Cancel Report and Confirm]] — זה מבטל את ההזמנה! גם שורה ירוקה יכולה להיות לא מאושרת, אז מסתכלים על הכפתור ולא על הצבע.","shot":"חלון Reservation של שירות מאושר, עם כפתור הביטול היחיד מסומן באדום \"לא ללחוץ\"."},{"title":"שגיאה: no rooms or passengers","text":"אם מופיעה הודעה כמו [[Cannot make reservation since no rooms or passengers have been defined in this transaction]] — לא מתקנים. ממשיכים לאשר את השאר, ומסבירים לבוחן מה חסר.","why":"בדרך כלל זה שירות שנכנס מההצעה בלי מחיר. בבגרות בודקים דרך והיגיון: טעות שזוהתה והוסברה מורידה כמה נקודות בלבד, ולא מתחילים מחדש.","shot":"הודעת השגיאה על המסך."},{"title":"לא משנים את הדוקט","text":"אחרי שהדוקט נפתח לא משנים בו שירותים. גם X אדום שנוצר בטעות (למשל אחרי סדר לחיצות שגוי) — משאירים ומסבירים לבוחן.","why":"החיבור בין הדוקט להצעה לא עובד עד הסוף, ושינויים לא נקלטים כמו שצריך.","shot":"אין צילום מסך — כרטיס אזהרה."}],"oral":[{"q":"למה מלון מופיע פעמיים בדוקט הקבוצתי?","a":"שורה אחת לנוסעים ושורה שנייה לאנשי הצוות. היא לא של החופשיים."},{"q":"מה השורה הוורודה ומה השורה הלבנה?","a":"ורודה = הסכום הכולל שהסוכן משלם לנו, כולל רווח (כמו בחשבונית). לבנה = טקסט ההערה מהמסלול."},{"q":"למה מאשרים כל שירות בנפרד?","a":"כי כל ספק מקבל בקשה נפרדת ומאשר אותה. בלי אישור לא יוצא שובר לשירות."},{"q":"איך יודעים ששירות כבר אושר?","a":"נכנסים לעיפרון ואז Reservation. אם נשאר רק כפתור ביטול — אושר. לא לוחצים עליו."},{"q":"למה מספר הנוסעים בדוקט שונה מגדלי הקבוצה בהצעה?","a":"ההצעה נבנתה לכמה גדלים כי הסוכן לא ידע כמה ימכור. את הדוקט פותחים עם המספר הסופי."}],"check":["חלוקת החדרים בדוקט (זוגי / יחיד) תואמת לשאלה — חדרים או נוסעים","מספר הדוקט רשום","כל השירותים אושרו (חוץ מהשורה הוורודה וההערה)","לא נלחץ Cancel Report and Confirm על שירות","שגיאה שלא תוקנה — מוכנים להסביר אותה לבוחן"],"sources":["TB_master §10, §12","00_docs_summary: Create Travel File, דוקט קבוצתי","hishtalmut_04 חלק ז׳","hishtalmut_06 §2, §3, §7 שלבים יב-יג","hishtalmut_09 §5, §6 שינויים אחרי פתיחת דוקט"],"record":"docket"},{"id":"grp-accounting","track":"GRP","order":10,"icon":"🧾","title":"שוברים, חשבונית, תשלום ורווח","goal":"להפיק שוברים וחשבונית, לרשום תשלום חלקי של הסוכן בדרך הנכונה, ולמצוא את הרווח.","why":"כאן ההבדל הגדול מ-FIT: הסוכן עם אשראי, ולכן החשבונית ירוקה, הדוקט לא מתאפס, והיתרה בסוף היא הרווח.","before":[{"term":"Voucher","text":"שובר: התחייבות לשלם לספק, כמו צ'ק דחוי. בקבוצה השוברים נטו, שובר נפרד לכל שירות. T = תחבורה, V = כל השאר."},{"term":"Invoice","text":"חשבונית לסוכן. כשלסוכן יש אשראי היא כמו צ'ק דחוי שקיבלנו: ירוקה, והדוקט עובר ליתרת זכות."},{"term":"Payment by agent","text":"תשלום של הסוכן מתוך החשבונית. זו הקבלה הנכונה בדוקט עם סוכן."},{"term":"Profit","text":"הרווח = יתרת הדוקט = חשבונית פחות סך השוברים."},{"term":"אשראי, לא קבוצה","text":"ההבדל בחשבונאות נובע מסוכן עם אשראי, לא מכך שזו קבוצה. גם FIT דרך סוכן עם אשראי יתנהג כך."}],"steps":[{"title":"בודקים שהכול אושר","text":"לפני שוברים, מוודאים שכל השירותים אושרו (יחידת פתיחת הדוקט).","why":"שוברים יוצאים רק לשירותים מאושרים. אחרת הסכומים יוצאים שגויים.","shot":"אין צילום מסך — כרטיס תזכורת."},{"title":"מפיקים שוברים","text":"בתחתית הדוקט לוחצים [[Ticket/Voucher]]. לא צריך לדפדף בין השוברים: לוחצים [[Back to Travel File]] (בתחתית, מתחת ל-[[Show Next]]).","why":"אחרי השוברים היתרה עוברת לחובה (אדום), כי התחייבנו לשלם לספקים.","shot":"כפתור Ticket/Voucher בתחתית הדוקט; ומסך השובר עם Back to Travel File מסומן."},{"title":"בודקים את השוברים","text":"ליד כל שירות מופיע מספר שובר: T לתחבורה, V לשאר. לחיצה על השובר פותחת אותו. היתרה בכותרת באדום.","shot":"שורות שירות עם מספרי שובר T ו-V מסומנים, והיתרה האדומה בכותרת."},{"title":"מפיקים חשבונית","text":"בתחתית הדוקט לוחצים [[Invoice]] ואז [[Back to Travel File]]. בתחתית מופיעה שורת חשבונית ירוקה עם מספר.","why":"היתרה הופכת לירוקה (זכות): החשבונית לסוכן עם אשראי נחשבת כאילו הכסף כבר התקבל.","shot":"שורת ה-Invoice הירוקה בתחתית, והיתרה הירוקה בכותרת."},{"title":"תשלום: מההמבורגר של החשבונית","text":"בשורת ה-[[Invoice]] לוחצים על ההמבורגר ובוחרים [[Payment by agent]].","trap":"לא ללחוץ [[Receipt]] בתחתית הדוקט! זה תשלום כפול: היתרה עולה בעוד כסף שלא קיים.","shot":"תפריט ההמבורגר של שורת ה-Invoice, עם Payment by agent מסומן; כפתור Receipt מסומן ב-X אדום."},{"title":"משנים את הסכום","text":"מוחקים את סכום ברירת המחדל ומקלידים את הסכום ששולם לפי השאלה. בוחרים [[Cash]]. מוודאים שהסכום החדש באמת נקלט, ורק אז לוחצים [[Generate]]. אחר כך [[Back to Travel File]].","trap":"ברירת המחדל היא כל היתרה. אם לא משנים — נרשם תשלום מלא ([[Fully Paid]]), ואחרי זה אי אפשר לתקן.","shot":"חלון Payment by agent עם שדה הסכום ו-Cash מסומנים, וכפתור Generate.","verify":"שם הכפתור: hishtalmut_06 — \"Generate\"; hishtalmut_09 — \"Generate Receipt\". לבדוק."},{"title":"היתרה לא משתנה","text":"אחרי התשלום היתרה נשארת כמו שהייתה, ולא נוספת שורה חדשה. ליד החשבונית מופיע [[Partially Paid]] ו-[[i]]. לחיצה על [[i]] מראה את מספר הקבלה ואת היתרה לתשלום. אפשר לראות גם ב-[[Information]], בשדה [[To pay]].","why":"הסוכן משלם מתוך ההתחייבות שבחשבונית, לא כסף נוסף. תשלום נוסף — שוב באותה דרך.","shot":"שורת ה-Invoice עם Partially Paid וה-i מסומנים; ולשונית Information עם To pay."},{"title":"מוצאים את הרווח","text":"הרווח מופיע בשני מקומות: ביתרת הדוקט (ירוק, למעלה) ובחלון [[Profit]] בתחתית הדוקט. ב-[[Profit]] רואים את פירוט השוברים, את סך כל העלויות, את סך הגבייה ואת הרווח. חוזרים ב-[[Back to Travel File]].","why":"רווח = חשבונית פחות שוברים. שאלה כמו \"מה סך העלויות בדוקט?\" עונים מחלון [[Profit]], לא במחשבון.","shot":"חלון Profit עם סך העלויות והרווח מסומנים; והיתרה בכותרת הדוקט."},{"title":"שולחים Travel File Details","text":"לוחצים [[Travel File Details]] (נטען לאט), ואז [[Send Page]], כתובת מייל ו-[[Send]].","why":"בקבוצה אין שם מחיר לכל שירות. יש חישוב כולל: נוסעים, [[Single Supplement]], [[Free of Charge]], סך לתשלום, מקדמה שהתקבלה ויתרה.","shot":"מסמך Travel File Details של קבוצה, עם החישוב הכולל מסומן, וכפתור Send Page."}],"oral":[{"q":"מה קורה ליתרה כשמפיקים שוברים?","a":"היא יורדת ונכנסת לחובה (אדום), כי התחייבנו לשלם לספקים."},{"q":"מה קורה ליתרה כשמפיקים חשבונית לסוכן עם אשראי?","a":"הדוקט עובר ליתרת זכות (ירוק). החשבונית היא התחייבות מלאה של הסוכן, כמו צ'ק דחוי."},{"q":"מה קורה ליתרה אחרי Payment by agent?","a":"לא משתנה. הסוכן משלם מתוך ההתחייבות שכבר נרשמה בחשבונית."},{"q":"למה לא משתמשים ב-Receipt בדוקט עם סוכן?","a":"כי זה תשלום כפול: הכסף כבר נרשם בחשבונית, ו-Receipt מוסיף עוד כסף שלא קיים."},{"q":"למה הדוקט הקבוצתי לא מתאפס כמו ב-FIT?","a":"כי היתרה בסוף היא הרווח: חשבונית פחות שוברים. ההבדל נובע מסוכן עם אשראי, לא מכך שזו קבוצה."},{"q":"איפה רואים את הרווח ואת סך העלויות?","a":"הרווח: ביתרת הדוקט ובחלון Profit. סך העלויות: בחלון Profit."}],"check":["לכל שירות יש שובר (T או V)","יש שורת Invoice אחת ירוקה, והיתרה ירוקה","אין שורות Receipt מתחת לחשבונית","ליד החשבונית Partially Paid (לא Fully Paid), בסכום מהשאלה","אתם יודעים לקרוא את הרווח ואת סך העלויות בחלון Profit","Travel File Details נשלח"],"sources":["TB_master §1, §10","00_docs_summary: דוקט קבוצתי","hishtalmut_06 §4, §6 שאלות 10-19","hishtalmut_09 §6","video_galor_01: צבעי מסמכים חשבונאיים"],"record":"docket"}];
